Ceviri.ekle("bn","olay",{
"OLAYLAR_EK5:1291-05-18:0":{"b": ["আক্কার মামলুকদের হাতে পতন — সিরিয়া উপকূল থেকে ক্রুসেডারদের উচ্ছেদ: সিডন ও বৈরুত", "3ca7a464"], "d": ["দীর্ঘকাল জেরুজালেমের ক্রুসেডার রাজ্যের কেন্দ্র থাকা আক্কা মামলুক সুলতান আল-মালিক আল-আশরাফ খলিল দ্বারা বিজিত হলো এবং ক্রুসেডারদের ফিলিস্তিনে কর্তৃত্ব শেষ হলো। আক্কা ছেড়ে আসা টেম্পলার নাইটরা সিডনে আশ্রয় নিল; মামলুক বাহিনী এগিয়ে এলে তারা সমুদ্র-দুর্গ ছেড়ে সাইপ্রাসে পালাল এবং শহর একই গ্রীষ্মে মামলুকদের হাতে গেল। 1197 সাল থেকে ক্রুসেডারদের হাতে থাকা বৈরুতও 1291 সালে দামেস্কের গভর্নর সানজার আশ-শুজাই দখল করলেন। এভাবে দুই শতাব্দীর ক্রুসেডার উপস্থিতি সিরিয়া-ফিলিস্তিন উপকূল থেকে মুছে গেল।", "63b3c40c"]},
"OLAYLAR_EK5:1299-01-01:0":{"b": ["বিলেজিক ও ইয়ারহিসারের রাতের হামলায় বিজয়", "f461b0af"], "d": ["TDV বিলেজিক নিবন্ধ: 'বিলেজিক টেকফুরসহ অঞ্চলের অন্য টেকফুররা ওসমান গাজির বিরুদ্ধে ষড়যন্ত্র করলেও এই চক্রান্ত টের পাওয়ায় অটোমান বাহিনী আকস্মিক হামলায় ইয়ারহিসার ও বিলেজিক জয় করল (1299)।' দুটি দুর্গ এক অভিযানে, একই রাতের হামলায় দখল হয়েছে। এই তারিখ অটোমান রাষ্ট্রের প্রতিষ্ঠা বছর হিসেবে গৃহীত মোড়। একই তারিখে অন্তর্ভুক্ত অন্যান্য স্থান: ইনেগোল।", "ec452c9e"]},
"OLAYLAR_EK5:1302-07-27:0":{"b": ["কোয়ুনহিসার (বাফেউস) যুদ্ধ — বাইজেন্টাইন সেনাবাহিনীর বিরুদ্ধে প্রথম বড় বিজয়", "584a9512"], "d": ["TDV ওসমান প্রথম নিবন্ধ: ওসমান বে 27 জুলাই 1302 বাফেউসে (কোয়ুনহিসার) বাইজেন্টাইন সেনাবাহিনীর সঙ্গে লড়ে তাদের পরাজিত করলেন। এই বিজয় ওসমান বেকে আঞ্চলিক সীমান্ত বে থেকে রাজবংশ প্রতিষ্ঠাতার মর্যাদায় উন্নীত করা মোড়। যুদ্ধের পর বুরসা সমভূমি অটোমান নিয়ন্ত্রণে এলো এবং ইজনিকের অবরোধ শুরু হলো।", "b82fb787"]},
"OLAYLAR_EK5:1303-01-01:0":{"b": ["দিম্বোস বিজয় এবং এরপর কিতে ও উলুবাত দখল", "e168ab64"], "d": ["TDV ওসমান প্রথম নিবন্ধ: 702 (1303) সালে বুরসা, কেস্তেল, কিতে ও আদ্রানোস টেকফুরদের গঠিত জোট দিম্বোস গিরিপথে পরাজিত হলো; শত্রু লড়তে লড়তে সংকীর্ণ গিরিপথ পর্যন্ত পিছু হটল এবং কেস্তেল টেকফুর রণক্ষেত্রে নিহত হলেন। বিজয়ের অব্যবহিত পরে কিতে ও উলুবাত দুর্গ দখল করে বুরসার স্থল যোগাযোগ কেটে অবরোধ কঠোর করা হলো। তরুণ ওরহানও এই যুদ্ধে অংশ নিয়েছিলেন।", "4afb53bf"]},
"OLAYLAR_EK5:1304-01-01:0":{"b": ["সাকারিয়া অভিযান: লেবলেবিজিহিসার, লেফকে, মেকেজে ও গেইভের দখল", "a51ba4d3"], "d": ["TDV ওসমান প্রথম নিবন্ধ 704 (1304) সাকারিয়া অভিযানের ক্রম দেয়: 'লেবলেবুজি দুর্গে পৌঁছলে টেকফুর আনুগত্য দেখাল... লেফকেতে গেলেন... মেকেজেতে পৌঁছলেন... গেইভেতে গিয়ে খালি পাওয়া দুর্গ দখল করলেন।' লেফকে সাকারিয়া উপত্যকার বিলেজিকে উন্মুক্ত হওয়া দরজা। এই একক অভিযান উপত্যকা বরাবর বিস্তৃত দুর্গ শৃঙ্খল অটোমান নিয়ন্ত্রণে এনে ইজনিক অববাহিকার পূর্ব পার্শ্ব বন্ধ করেছে।", "ae2866c2"]},
"OLAYLAR_EK5:1304-01-01:1":{"b": ["খিওস জেনোয়ার জাকারিয়া পরিবারের নিয়ন্ত্রণে গেল", "9eebe4de"], "d": ["আইদিনোগুল্লারির হুমকির মুখে বাইজেন্টাইন সম্রাট জেনোয়ার বেনেদেত্তো জাকারিয়ার কাছে সাহায্য চান; দ্বীপটি তাঁর নিয়ন্ত্রণে যায় (নামমাত্র বাইজেন্টাইন আনুগত্যসহ)। জাকারিয়া কর্তৃত্ব 1329 পর্যন্ত চলে।", "4d0e4fd8"]},
"OLAYLAR_EK5:1304-01-01:2":{"b": ["সামোস খিওসের জেনোয়ীয় (জাকারিয়া) মালিকানায় এল", "0e6f51e3"], "d": ["খিওসের নিয়ন্ত্রণ নেওয়া জেনোয়ার জাকারিয়া পরিবার প্রায় জনশূন্য সামোসকেও নিজেদের মালিকানায় যুক্ত করে (টিডিভি: 1304-1329)।", "8eb44fb2"]},
"OLAYLAR_EK5:1305-01-01:0":{"b": ["গেইভে গিরিপথ দুর্গগুলোর বিজয়: কারাচেপুশ, কারাতিগিন ও আবসু", "76907c78"], "d": ["TDV ওরহান নিবন্ধ: ওরহান 705 (1305) সাকারিয়া অভিযানে 'কারাচেপুশ (কাতোইকিয়া), ইজনিকের সামনে কারাতিগিন, আবসু (হিপসু: গেইভে গিরিপথে) দুর্গ জয় করলেন'। এই তিন দুর্গ সাকারিয়া উপত্যকা ও ইজনিক অববাহিকার মধ্যবর্তী পথ বন্ধ করে ইজনিকের স্থল সাহায্য সম্পূর্ণ কেটে দিয়েছে। গেইভে গিরিপথের কারাচেপুশ ও আবসুতে গাজি আবদুররহমানকে বসানো হয়েছিল; শহর এখন কেবল ক্ষুধায় পতিত হতে পারত।", "d330595f"]},
"OLAYLAR_EK5:1323-09-01:0":{"b": ["আদ্রানোস (ওরহানেলি) অভিযান — ওসমান বেগের শেষ অভিযান", "4811546c"], "d": ["TDV ওরহান নিবন্ধ 1323 সালের শরতের আদ্রানোস দুর্গ অভিযানকে ওসমান বেগের শেষ অভিযান হিসেবে লিপিবদ্ধ করে। আদ্রানোস টেকফুর কুড়ি বছর আগে দিম্বোসে অটোমানদের বিরুদ্ধে গঠিত টেকফুর জোটের সদস্য ছিলেন; এই অভিযান সেই হিসাব চুকানোর অর্থ বহন করে। দুর্গের সঠিক বিজয় দিন জানা নেই; অভিযান ওরহান বে চালিয়ে গেছেন।", "1e8ea25a"]},
"OLAYLAR_EK5:1324-01-01:0":{"b": ["ওসমান গাজির মৃত্যু এবং ওরহান বের বেগলিকে আরোহণ", "021487cd"], "d": ["বেগলিকের নামদাতা ওসমান গাজি আসপোরচা হাতুন ও মেকেজে ওয়াকফনামার সাক্ষ্য অনুযায়ী 724 (1324) সালে মারা গেলেন। 1305 সাল থেকে অভিযানে সেনাবাহিনীর নেতৃত্বদানকারী তাঁর ছেলে ওরহান পিতার মৃত্যুতে কোনো সিংহাসন-দ্বন্দ্ব ছাড়াই বেগলিকের প্রধান হলেন। প্রতিষ্ঠাতা প্রজন্মের নির্বিঘ্নে পতাকা হস্তান্তর উচ বেগলিক থেকে রাষ্ট্রের পথে রাজবংশের প্রথম বড় পরীক্ষা শান্তভাবে উত্তীর্ণ হওয়ার ইঙ্গিত দেয়।", "6f95e64a"]},
"OLAYLAR_EK5:1329-01-01:0":{"b": ["খিওস জাকারিয়ার কাছ থেকে নিয়ে বাইজেন্টাইনদের সঙ্গে যুক্ত", "f6741b26"], "d": ["সম্রাট তৃতীয় আন্দ্রোনিকোস জাকারিয়াকে দ্বীপ থেকে সরিয়ে তৃতীয় বেনেদেত্তোর গভর্নরত্বে দ্বীপটি বাইজেন্টাইনদের সঙ্গে যুক্ত করেন। দ্বীপটি 1346 সালে জেনোয়ার সিমোনে ভিনিওসি দখল করবেন।", "84f19c2b"]},
"OLAYLAR_EK5:1329-01-01:1":{"b": ["সামোস জাকারিয়ার কাছ থেকে বাইজেন্টাইনদের কাছে ফিরল (খিওস ধারা)", "08034974"], "d": ["জাকারিয়া লর্ডশিপের পতনের (1329 সালে খিওসের বাইজেন্টাইনদের সঙ্গে যুক্ত হওয়া) ফলে সামোসের জেনোয়ীয় মালিকানাও শেষ হয়।", "314dce74"]},
"OLAYLAR_EK5:1329-06-01:0":{"b": ["পেলেকানন (মালতেপে) যুদ্ধ এবং পুরো কোজাএলির দখল", "389e7bd4"], "d": ["TDV ওরহান নিবন্ধ: যুদ্ধের প্রথম দিন ওরহান গাজি বাইজেন্টাইন সেনাকে নিজের দিকে টানতে তিনশো জনের দল পাঠালেন; দ্বিতীয় দিন পাজারলুর নেতৃত্বাধীন বাহিনী সমভূমিতে নামায় যুদ্ধ বড় হলো এবং সম্রাট তিরবিদ্ধ হলে বাইজেন্টাইন সেনাবাহিনীতে আতঙ্ক ছড়াল। ফল নিশ্চিত: 'ওরহান সমগ্র কোজাএলি দখল করলেন; বিজয়ের পর ইজনিকবাসীদের কোনো আশা রইল না।' হেরেকে থেকে উস্কুদার পর্যন্ত উপকূলের শহরগুলো অটোমান শাসনে এলো, গেবজে অঞ্চলের কেন্দ্র হলো। এটি ছিল ইস্তানবুল রক্ষায় আসা শেষ বাইজেন্টাইন সাম্রাজ্যিক সেনাবাহিনী।", "73fe4332"]},
"OLAYLAR_EK5:1331-03-03:0":{"b": ["ইজনিকে প্রথম অটোমান মাদ্রাসা প্রতিষ্ঠা", "c85fb625"], "d": ["ওরহান বে ইজনিক দখলের ঠিক পরেই চান্দারলি কারা খলিলকে এখানে কাজি নিযুক্ত করলেন, একটি বাসিলিকাকে মসজিদে রূপান্তর করলেন এবং তার পাশে একটি ইমারেত ও একটি মাদ্রাসা নির্মাণ করিয়ে শহরের উন্নয়ন শুরু করলেন। TDV-র দাউদ-ই কায়সেরি নিবন্ধ অনুসারে মাদ্রাসার নির্মাণ 1336 সালে সম্পন্ন হয় এবং ওরহান গাজি দৈনিক 30 আকচে বেতনে দাউদ-ই কায়সেরিকে মুদাররিস করে আনলেন। এই মাদ্রাসা অটোমান জ্ঞানজীবনের প্রথম প্রাতিষ্ঠানিক পদক্ষেপ; বেগলিক বিজয়শক্তির পাশাপাশি জ্ঞানের ঐতিহ্যও যুক্ত করল। বিজয়ে নেওয়া একটি বাইজেন্টাইন রাজধানীর ইসলামি জ্ঞানকেন্দ্রে রূপান্তর অটোমানদের স্থায়ী রাষ্ট্র হওয়ার দাবির প্রথম বাস্তব নিদর্শন ছিল।", "4f11a077"]},
"OLAYLAR_EK5:1333-08-01:0":{"b": ["বাইজেন্টাইনদের করদ হওয়া — ইজমিত অবরোধ ও চুক্তি", "0c1ec8d3"], "d": ["TDV ওরহান নিবন্ধ: ওরহান 733 (1333) সালের গ্রীষ্মে বড় সেনাবাহিনী ও ক্যাটাপল্ট নিয়ে ইজমিত অবরোধ করলেন, সম্রাট চুক্তিতে সম্মত হলেন। অবরোধ তুলে নেওয়ার বিনিময়ে বাইজেন্টাইনরা ওরহানকে বছরে 12.000 স্বর্ণমুদ্রা (হাইপারপাইরন) দিতে রাজি হলো; 'এভাবে অটোমান আমিরের দৃষ্টিতে বাইজেন্টাইন করদ দেশের অবস্থায় পড়ল'। বিনিময়ে ওরহান সম্রাটের বন্ধু হবেন এবং বাইজেন্টাইন অধীন শহরগুলোতে হামলা করবেন না। একটি সীমান্ত বেগলিকের পূর্ব রোমকে করদ বানানো ক্ষমতার ভারসাম্য কতটা ঘুরেছে তার ঘোষণা ছিল।", "e2e3eeb4"]},
"OLAYLAR_EK5:1335-01-01:0":{"b": ["সামোথ্রাকি ভেনিসীয়দের কাছ থেকে জেনোয়ার গাত্তিলুজিও পরিবারে গেল", "c499ed5f"], "d": ["1204 সাল থেকে দ্বীপটি ধরে রাখা ভেনিসীয়দের জেনোয়ার গাত্তিলুজিও পরিবার দ্বীপ থেকে বের করে দেয়।", "97a996b3"]},
"OLAYLAR_EK5:1345-01-01:0":{"b": ["কারেসি বেগলিকের অন্তর্ভুক্তি: বালিকেসির, বেরগামা, বিগা, এদ্রেমিত ও এরদেক", "c7cb0511"], "d": ["TDV ওরহান নিবন্ধ (ইনালজিক) অন্তর্ভুক্তি 735 (1334-35) তারিখে রাখে: দেমিরহান বের মৃত্যুতে কারেসি গাজিরা ও হাজি ইলবে দুরসুন বেকে সিংহাসনে আমন্ত্রণ জানিয়ে ওরহানের কাছে সাহায্য চাইলেন। ওরহান প্রথমে বালিকেসির অভিমুখে গেলেন; শান্তি আলোচনায় যাওয়া দুরসুন বে বেরগামা দুর্গ থেকে ছোড়া তিরে মারা গেলে বেগলিক পুরোপুরি অটোমান ভূখণ্ডে যুক্ত হলো। একই অভিযানে কিরমাস্তি ও মিহালিচ আনুগত্য দেখাল, গোলিয়াজি দখল হলো এবং আগে নিরাপত্তা দিয়ে ছেড়ে দেওয়া উলুবাত চূড়ান্তভাবে দখল হলো। ওরহান কারেসি সানজাকে সুলেইমান পাশাকে নিয়োগ করে বিগাকে সীমান্ত কেন্দ্র করলেন — রুমেলিতে উত্তরণের নাবিক কর্মীবাহিনী এভাবে অর্জিত হলো। দ্রষ্টব্য: TDV-র কারেসিওগলুরা নিবন্ধ একই ঘটনার জন্য 746 (1345) তারিখ দেয়; বিশ্বকোষ নিজের মধ্যেই পরস্পরবিরোধী। একই তারিখে অন্তর্ভুক্ত অন্যান্য স্থান: চানাক্কালে।", "f5ed82c2"]},
"OLAYLAR_EK5:1346-06-15:0":{"b": ["সামোস খিওস মাওনার মালিকানায় এল", "01628b2f"], "d": ["জেনোয়ার সিমোনে ভিনিওসির খিওস দখল এবং শাসন মাওনা কোম্পানির হাতে ছাড়ার ফলে সামোসও খিওসের জেনোয়ীয়দের (মাওনা) মালিকানায় যায় (টিডিভি: 1346-1475)।", "3b122d12"]},
"OLAYLAR_EK5:1352-01-01:0":{"b": ["ওরহান গাজির জেনোয়াবাসীদের সঙ্গে প্রথম ক্যাপিটুলেশন", "e64cb196"], "d": ["ভেনিস-জেনোয়া যুদ্ধের সময় জেনোয়াবাসীদের সঙ্গে চুক্তি করা ওরহান গাজি 1352 সালের ফেব্রুয়ারিতে প্রণালী যুদ্ধের পর পেরার প্রতিরক্ষায় 1000 তীরন্দাজ পাঠালেন এবং সৈন্য পরিবহনের জন্য 60.000 স্বর্ণমুদ্রা জোগাড় করলেন; বিনিময়ে জেনোয়াবাসীদের প্রথম ক্যাপিটুলেশন প্রদান করলেন। চুক্তির পূর্ণ পাঠ আজ পর্যন্ত টিকে নেই। এটি অটোমানদের কোনো ইউরোপীয় নৌশক্তির সঙ্গে প্রথম আনুষ্ঠানিক চুক্তি এবং পঁয়ত্রিশ বছর পর 1387 সালে নবায়িত হবে।", "68c60677"]},
"OLAYLAR_EK5:1354-03-02:0":{"b": ["গালিপোলি দখল — রুমেলিয়ায় স্থায়ী সেতুমুখ", "ba51a160"], "d": ["1349-1352 সালের মধ্যে কান্তাকুজেনোসের মিত্র হিসেবে আশপাশ চেনা গালিপোলি অটোমানরা 1354 সালে দখল করল; শহরের প্রাচীর ভেঙে দেওয়া এক বড় ভূমিকম্প সুযোগ এনে দিয়েছিল। চিম্পের সংকীর্ণ সেতুমুখ এভাবে প্রণালীর রুমেলিয়া তীরে প্রকৃত ঘাঁটিতে পরিণত হলো এবং থ্রেসের দিকে দরজা পুরোপুরি খুলে গেল। গালিপোলি 1366 সালে সাভয় ক্রুসেড অভিযানে হাতছাড়া হবে, তবে 1376 সালের দ্বিতীয় বিজয়ে চূড়ান্তভাবে অটোমান কর্তৃত্বে আসবে। একই তারিখে যুক্ত হওয়া অন্যান্য স্থান: কিলিতবাহির।", "cac0192e"]},
"OLAYLAR_EK5:1357-09-01:0":{"b": ["রুমেলিয়ার বিজেতা সুলায়মান পাশার মৃত্যু", "2dc98228"], "d": ["ওরহান বের জ্যেষ্ঠ পুত্র ও রুমেলিয়া বিজয়ের স্থপতি সুলায়মান পাশা সূত্রগুলোতে 758 (1357), 759 ও 760 (1359) হিসেবে দেওয়া তারিখগুলোর মধ্যে সবচেয়ে গ্রহণযোগ্য 1357 সালের শরতে শিকারের সময় ঘোড়া থেকে পড়ে মারা গেলেন। 1352-1354 সালের মধ্যে তাঁর অভিযানে রুমেলিয়ায় স্থায়ী অটোমান উপস্থিতি গড়ে তোলা এই শাহজাদার মৃত্যু উত্তরাধিকারের ক্রম ভাই মুরাদের হাতে ছেড়ে দিল। বোলায়িরে সমাহিত সুলায়মান পাশার সমাধি ইউরোপে অটোমানদের প্রাচীনতম রাজবংশীয় স্মৃতিসৌধ হিসেবে রয়ে গেছে।", "1f780557"]},
"OLAYLAR_EK5:1361-01-01:0":{"b": ["পেনচিক আইন — জ্যানিসারি বাহিনীর ভিত্তি স্থাপন", "e5877c2d"], "d": ["রুমেলিয়া বিজয়ের পর উলামা কারামানলি কারা রুস্তেমের পরামর্শে যুদ্ধবন্দীদের এক-পঞ্চমাংশ অথবা তার অর্থমূল্য রাষ্ট্রের জন্য নির্ধারণ করার পেনচিক ব্যবস্থা কার্যকর করা হলো। এই বন্দীদের মধ্য থেকে বাছাই করাদের তুর্কি পরিবারের কাছে লালন-পালন করে সৈন্যদলে নেওয়ার মাধ্যমে সরাসরি সুলতানের অধীন স্থায়ী পদাতিক বাহিনীর — জ্যানিসারি বাহিনীর — মূল গড়ে উঠল। উপজাতীয় অশ্বারোহীর ওপর নির্ভরশীল একটি উচ বেগলিকের কেন্দ্রীয় সেনাবাহিনীসম্পন্ন রাষ্ট্রে রূপান্তর এই ব্যবস্থা দিয়েই শুরু হয়।", "f28873dd"]},
"OLAYLAR_EK5:1363-01-01:0":{"b": ["পশ্চিম থ্রেসে অভিযান: গুমুলচিনা বিজয়", "9ef69221"], "d": ["এডির্ন দখলের পর মেরিচ নদীর পশ্চিমে অগ্রসর উচ বাহিনী গাজি এভরেনোস বের নেতৃত্বে পশ্চিম থ্রেসের কেন্দ্র গুমুলচিনা দখল করল। শহরটি এভরেনোস বের অভিযানগুলো ম্যাসিডোনিয়ায় নিয়ে যাওয়ার অগ্রবর্তী ঘাঁটিতে পরিণত হলো। এভাবে থ্রেসের এজিয়ান উপকূল পর্যন্ত বিস্তৃত অংশ অটোমান নিয়ন্ত্রণে এল এবং থেসালোনিকির পথ খুলে গেল।", "0206d2bb"]},
"OLAYLAR_EK5:1369-01-01:0":{"b": ["ভার্না দোব্রুজা রাজ্যে যোগ দিল এবং রাজধানী হলো", "2bfe73f9"], "d": ["বুলগার জারত্বের বিভক্ত হওয়ার প্রক্রিয়ায় কৃষ্ণ সাগর উপকূলের ভার্না দোব্রোতিচের প্রতিষ্ঠিত দোব্রুজা রাজ্যের সঙ্গে যুক্ত হলো এবং এই ক্ষুদ্র রাষ্ট্রটির রাজধানী করা হলো।", "5115e7b2"]},
"OLAYLAR_EK5:1373-01-01:0":{"b": ["ফিলিবের পশ্চিমে: তাতারপাজারজিক ও ইহতিমানের অন্তর্ভুক্তি", "1664d0e1"], "d": ["1372 সালে ফিলিবে দখলের পর মেরিচ উপত্যকার উজান প্রান্তের তাতারপাজারজিক এবং সোফিয়ার দিকে খোলা গিরিপথ রক্ষাকারী ইহতিমান অটোমান শাসনের অধীনে এল। চিরমেন যুদ্ধের পর অনুগত হওয়া স্থানীয় বেদের হাতে থাকা এই রেখা সরাসরি শাসনের অধীনে আনা হলো এবং ফিলিবে-সোফিয়া পথ অবিচ্ছিন্ন হলো। এই অগ্রগতি বারো বছর পর সোফিয়া বিজয়ের পথের প্রস্তুতি।", "0e9acfa0"]},
"OLAYLAR_EK5:1373-05-15:0":{"b": ["সাভচি বের বিদ্রোহ — শাহজাদা ও বাইজেন্টাইন উত্তরাধিকারীর যৌথ বিদ্রোহ", "75198c33"], "d": ["প্রথম মুরাদের ছেলে সাভচি বে এবং বাইজেন্টাইন সম্রাট পঞ্চম ইওয়ানিসের ছেলে আন্দ্রোনিকোস পালাইওলোগোস 1373 সালের মে মাসের শুরুতে বুরসা ও কনস্টান্টিনোপলে একই সময়ে নিজ নিজ পিতার বিরুদ্ধে বিদ্রোহ করলেন। দুই রাজবংশের উত্তরাধিকারীকে একত্রিত করা এই জোট দ্রুত দমন করা হলো; সাভচি বে ধরা পড়ে চোখ অন্ধ করা হলো এবং মৃত্যুদণ্ড দেওয়া হলো। অটোমান বর্ণনায় বিদ্রোহের জন্য দেওয়া 787 (1385) তারিখটি ভুল; ঘটনাটি বাইজেন্টাইনদের অটোমান অধীনতায় প্রবেশের বছরগুলোর ঠিক পরে পড়ে এবং দুই প্রাসাদ কতটা জড়িয়ে ছিল তা দেখায়।", "9776426c"]},
"OLAYLAR_EK5:1374-01-01:0":{"b": ["স্ট্রুমা ও মেস্তা উপত্যকা: কিউস্তেন্দিল, পেত্রিচ, নেভ্রোকোপ ও দ্রামার অন্তর্ভুক্তি", "8c0980c4"], "d": ["চিরমেন বিজয়ের পর অটোমানদের কর দিতে শুরু করা সার্ব ও বুলগার স্থানীয় বেদের হাতে থাকা স্ট্রুমা ও মেস্তা উপত্যকা উচ বেদের অগ্রগতিতে সরাসরি অটোমান শাসনের অধীনে এল। কিউস্তেন্দিল, পেত্রিচ, নেভ্রোকোপ ও দ্রামার অন্তর্ভুক্তির ফলে ম্যাসিডোনিয়ার পূর্ব অর্ধেক খুলে গেল এবং থেসালোনিকি ও সেরেস অবরোধ বলয়ের মধ্যে পড়ল। মানচিত্রে রুমেলিয়ার দক্ষিণ-পশ্চিমে প্রসারণ এই অভিযানেরই ফল।", "a50a02ad"]},
"OLAYLAR_EK5:1381-04-01:0":{"b": ["তিমুর হেরাত দখল করলেন: কার্ত বংশের অবসান ও খোরাসানের তিমুরীয় হাতে যাওয়া", "15f6019e"], "d": ["1380 সালে খোরাসান সারবাদার, কার্ত ও মুজাফফরিদের মধ্যে সংঘর্ষে খণ্ডবিখণ্ড ছিল। তিমুর পুত্র মিরান শাহকে অঞ্চলে পাঠিয়ে নিজে হেরাতের দিকে অগ্রসর হলেন এবং কিছুদিন অবরোধের পর কার্ত মালিক গিয়াসুদ্দিন পির আলীর কাছ থেকে শহর হস্তগত করলেন। তাঁর প্রস্থানের পর ওঠা বিদ্রোহ মিরান শাহ রক্তাক্তভাবে দমন করলেন এবং 1255 থেকে হেরাতে শাসন করা কার্ত বংশের অবসান ঘটালেন। মাশহাদ থেকে নিশাপুর পর্যন্ত পুরো খোরাসান এই তারিখে তিমুরীয় শাসনে এলো।", "6ae06d43"]},
"OLAYLAR_EK5:1381-10-01:0":{"b": ["এরেতনা বেগলিকের অবসান এবং কাদি বুরহানেদ্দিন রাষ্ট্রের প্রতিষ্ঠা", "60dcaf57"], "d": ["1335 সালে ইলখানি গভর্নরশিপ থেকে উদ্ভূত এবং সিভাস ও কায়সেরিকেন্দ্রিক মধ্য আনাতোলিয়াকে ছেচল্লিশ বছর শাসনকারী এরেতনাওগুল্লার প্রাসাদের অভ্যন্তরীণ দ্বন্দ্বে ভেঙে পড়ল। 1378 সালের মে মাসে উজির হওয়া কাদি বুরহানেদ্দিন প্রতিদ্বন্দ্বী কিলিচআরসলান ও হাজি শাদগেলদিকে সরিয়ে 1381 সালের শরতে সুলতানত্ব ঘোষণা করে বেগলিকের অবসান ঘটালেন এবং নিজের নামে পরিচিত রাষ্ট্র গঠন করলেন। এভাবে অটোমানদের পূর্ব প্রতিবেশী বদলে গেল; সিভাস-কায়সেরি রেখা এর পর সতেরো বছর কাদি বুরহানেদ্দিনের হাতে থাকবে।", "f5b2be0c"]},
"OLAYLAR_EK5:1385-01-01:0":{"b": ["ম্যাসিডোনিয়ার অভ্যন্তরে অগ্রগতি: মানাস্তির ও ওহরিদ বিজয়", "63bb7838"], "d": ["ভিয়া এগনাতিয়ার ওপর অবস্থিত মানাস্তির এবং হ্রদতীরের ওহরিদ আলবেনিয়ার দিকে অভিযান চলাকালে অটোমান শাসনের অধীনে এল। দুটিই আদ্রিয়াটিক পর্যন্ত প্রসারিত পথের মূল ঘাঁটি ছিল; ওহরিদ আবার বলকানের সবচেয়ে প্রাচীন অর্থোডক্স আর্চবিশপ কেন্দ্রও ছিল। TDV-র মতে ওহরিদ বিজয়ের তারিখ সম্পর্কে নিশ্চিত তথ্য নেই; 787 (1385) এবং ক্রালিয়েভিচ মার্কোর মৃত্যুর পরের 797 (1395) তারিখ দুটি প্রস্তাব করা হয়েছে; এখানে 1385 ধরা হয়েছে। মানাস্তির পরবর্তী শতাব্দীগুলোতে রুমেলিয়ার অন্যতম প্রধান সামরিক কেন্দ্র হবে।", "e5418654"]},
"OLAYLAR_EK5:1385-09-18:0":{"b": ["সাভরা যুদ্ধ — আলবেনিয়ার দ্বার উন্মুক্ত", "dda6671b"], "d": ["বালশা রাজবংশের বিরুদ্ধে সংকটে পড়া আলবেনীয় বে কার্লো তোপিয়ার সাহায্যের আহ্বানে অটোমান বাহিনী সাভরা সমভূমিতে দ্বিতীয় বালশার সেনাবাহিনীকে পরাজিত করল; বালশা যুদ্ধক্ষেত্রে প্রাণ হারালেন। স্থানীয় বের আমন্ত্রণে প্রবেশ করা এই যুদ্ধ অটোমানদের আদ্রিয়াটিক উপকূল পর্যন্ত বিস্তৃত আলবেনীয় ভূমিতে প্রথম স্থায়ী প্রভাব এনে দিল। অঞ্চলের বেদের পারস্পরিক বিরোধকে সুযোগে পরিণত করার এই নীতি পরবর্তী শতাব্দীজুড়ে বলকান বিজয়ের অপরিবর্তনীয় পদ্ধতি হবে।", "05382964"]},
"OLAYLAR_EK5:1386-01-01:0":{"b": ["তিমুরের 'তিন বছরের অভিযান': আজারবাইজান ও উত্তর ইরান দখল", "2a98ec51"], "d": ["খোরাসান অভিযানকালে ইরানের বিক্ষিপ্ত অবস্থা কাছ থেকে দেখা তিমুর 788 সালে (1386) পশ্চিমে অগ্রসর হলেন। 'তিন বছরের অভিযান' নামে পরিচিত 1386-1388 অভিযানে মাজান্দারান, লুরিস্তান ও জর্জিয়া হয়ে আজারবাইজানে গিয়ে কারাবাখে পৌঁছলেন; তাবরিজ, আরদাবিল, উর্মিয়া ও নাখচিভান তিমুরীয় শাসনে এলো। উত্তর ইরান ও আজারবাইজান দখল, একসময় জোচি উলুস ও ইলখানিদের মধ্যে যেমন ছিল, স্বর্ণ ঊর্দুর সঙ্গে দীর্ঘ সংঘর্ষেরও সূচনা হলো।", "aaf3b558"]},
"OLAYLAR_EK5:1386-06-01:0":{"b": ["ফ্রেঙ্কইয়াজিসি যুদ্ধ ও কনিয়া অবরোধ — প্রথম কারামান অভিযান", "af4e5d77"], "d": ["জামাই হয়েও পশ্চিম আনাতোলিয়ায় অটোমান সম্প্রসারণে অসন্তুষ্ট কারামানওগলু আলাউদ্দিন আলি বের বিরুদ্ধে প্রথম মুরাদ নিজেই অভিযানে নামলেন; ফ্রেঙ্ক ইয়াজিসি নামের স্থানে সংঘটিত যুদ্ধে প্রশিক্ষিত ও অভিজ্ঞ অটোমান সেনাবাহিনী কারামানি বাহিনীকে পরাজিত করল। এর পর কনিয়া দুর্গ অবরোধ করা হলো, কিন্তু আলাউদ্দিন বেকে ক্ষমা করায় বেগলিক সম্পূর্ণ বিলুপ্ত হলো না। এই অভিযান অটোমান ও কারামানের মধ্যে এক শতাব্দী চলা এবং কেবল 1468 সালে চূড়ান্ত সংযুক্তিতে শেষ হওয়া দীর্ঘ হিসাব-নিকাশের সূচনা।", "087a605a"]},
"OLAYLAR_EK5:1387-01-22:0":{"b": ["মুশ কারাকোয়ুনলু শাসন থেকে তৈমুরের শাসনে গেল (789/1387)", "ed2e7a11"], "d": ["মঙ্গোল যুগের পর কারাকোয়ুনলু শাসনে যাওয়া মুশ 789 (1387) সালে কারাকোয়ুনলু ভূমির অধিকারী তৈমুরের শাসনে আসে। অ্যাটলাসে মুশ এই বছরে কারাকোয়ুনলু থেকে তৈমুরীয়ে লেখা।", "9475520a"]},
"OLAYLAR_EK5:1390-06-01:0":{"b": ["গালিপোলি নৌঘাঁটি প্রতিষ্ঠা — অটোমান নৌবহরের জন্ম", "47546241"], "d": ["অটোমান রাষ্ট্রের প্রথম সুসংগঠিত নৌঘাঁটি 1390 সালে ইলদিরিম বায়েজিদ গালিপোলিতে বাইজেন্টাইনদের রেখে যাওয়া নৌঘাঁটির জায়গায় প্রতিষ্ঠা করলেন। পশ্চিম আনাতোলিয়ার বেগলিকগুলোর নাবিক উত্তরাধিকার গ্রহণকারী অটোমানরা এভাবে প্রথমবারের মতো নিজেদের জাহাজ নিজেরা নির্মাণকারী নৌশক্তিতে পরিণত হলো। চানাক্কালে প্রণালীর মূল স্থানে অবস্থিত এই নৌঘাঁটি কনস্টান্টিনোপল অবরোধ থেকে এজিয়ান অভিযান পর্যন্ত দেড় শতাব্দী অটোমান নৌবহরের প্রধান ঘাঁটি হিসেবে কাজ করল।", "f214717c"]},
"OLAYLAR_EK5:1391-01-01:0":{"b": ["হামিদ-ইলি অটোমানদের সঙ্গে যুক্ত হলো: ইসপার্তা, বুর্দুর, উলুবোরলু, এইরদির", "e3da7de5"], "d": ["কারামানওগলু আলাউদ্দিন বের হামিদ-ইলি আক্রমণ এবং জনগণের অভিযোগের পরিপ্রেক্ষিতে অভিযানে বের হওয়া ইলদিরিম বায়েজিদ হামিদওগুল্লারের অবশিষ্ট সমস্ত ভূমি দখল করলেন এবং তার শাসনভার ছেলে ইসা চেলেবিকে দিলেন।", "8a997ead"]},
"OLAYLAR_EK5:1393-01-01:0":{"b": ["মুজাফফরিদ রাজবংশের অবসান: শাহ মনসুরের শিরাজের সামনে পরাজয়", "5fd14eb8"], "d": ["1318 থেকে ইয়াজদ, ফারস, ইসফাহান ও কিরমানে শাসন করা মুজাফফরিদদের শেষ শক্তিশালী শাসক শাহ মনসুর আত্মীয়দের সঙ্গে ঐক্য করে তিমুরের বিরুদ্ধে অভিযানে নামলেন। শিরাজের কাছে যুদ্ধে আমিরদের একজন বিপক্ষে চলে যাওয়ায় বেশিরভাগ বাহিনী হারিয়ে পরাজিত হয়ে নিহত হলেন। তিমুরের পরে বংশের সব সদস্যকেও হত্যা করানোয় মুজাফফরিদ কর্তৃত্ব শেষ হলো এবং ফারস ও কিরমান তিমুরীয় শাসনে যুক্ত হলো।", "8e89c2dc"]},
"OLAYLAR_EK5:1393-06-01:0":{"b": ["আমাসিয়ার অটোমান ভূমিতে যুক্ত হওয়া", "fe2860cf"], "d": ["ইলদিরিম বায়েজিদের মধ্য আনাতোলিয়া অভিযানকালে অবরুদ্ধ আমাসিয়ার আমির শহর অটোমানদের হাতে সমর্পণ করলেন এবং বায়েজিদ 1393 সালে শহরে প্রবেশ করলেন। সুলতান এর শাসনভার ছেলে মেহমেদ চেলেবির হাতে ছেড়ে দিলেন; শাহজাদা সানজাক হিসেবে আমাসিয়া এর পর অটোমান রাজবংশের সবচেয়ে গুরুত্বপূর্ণ শিক্ষাকেন্দ্রগুলোর একটি হয়ে উঠল। এই পছন্দ ভবিষ্যতের ফেতরেত যুগে নির্ধারক হবে; চেলেবি মেহমেদ রাষ্ট্রকে পুনরায় একত্রিত করার সংগ্রাম ঠিক এই আমাসিয়ার ভিত্তি থেকেই চালাবেন।", "389ab68d"]},
"OLAYLAR_EK5:1393-08-29:0":{"b": ["তিমুর বাগদাদ দখল করলেন — জালায়িরিরা আনাতোলিয়ায় পালাল", "4d5602b3"], "d": ["দীর্ঘ অবরোধের পর তিমুর বাগদাদ দখল করলেন; শহরের শাসক জালায়িরি সুলতান আহমেদ পশ্চিমে পালিয়ে প্রথমে মামলুকদের, পরে অটোমান দরবারে আশ্রয় নিলেন। তিমুরের পশ্চিমে সম্প্রসারণ এভাবে প্রথমবার অটোমান প্রভাব বলয়ের সঙ্গে সরাসরি স্পর্শ করল। দুই শাসকের মধ্যে শত্রুতার প্রথম শিকল এখান থেকে শুরু।", "2fac674f"]},
"OLAYLAR_EK5:1393-09-01:0":{"b": ["কৃষ্ণ সাগর উপকূলে ভার্না দখল", "a84b2abf"], "d": ["বুলগার জারত্বের দানিয়ুব ও কৃষ্ণ সাগরের মধ্যবর্তী ভূমি সংকুচিত করার সময় উপকূলের বৃহত্তম বন্দর ভার্না অটোমান শাসনের অধীনে গেল। বন্দরটি দখল দোব্রুজার দিকে অগ্রগতির পথ খুলে দিল এবং কৃষ্ণ সাগরের পশ্চিম উপকূলে অটোমানদের প্রথম বড় ঘাট এনে দিল। ভার্না একান্ন বছর পর ক্রুসেডার বাহিনী ধ্বংস হওয়া 1444 সালের বিজয়েরও মঞ্চ হবে।", "2e425501"]},
"OLAYLAR_EK5:1398-01-01:0":{"b": ["নেভশেহির ও ইউরগুপ অঞ্চল কারামানোগুল্লারির কাছ থেকে অটোমানদের হাতে গেল", "06ff59e8"], "d": ["ইলদিরিম বায়েজিদের কারামানোগুল্লারির বিরুদ্ধে অভিযানে নেভশেহির (মুশকারা) ও ইউরগুপ অঞ্চল 800/1398 সালে অটোমান শাসনে যায়; 1402 সালে আঙ্কারার যুদ্ধের পর তৈমুর অঞ্চলটি কারামানোগুল্লারিকে ফিরিয়ে দেন।", "5faa82e5"]},
"OLAYLAR_EK5:1398-07-15:0":{"b": ["কাদি বুরহানেদ্দিন রাষ্ট্রের পতন", "b13391e3"], "d": ["আক্কোয়ুনলু শাসক কারায়ুলুক ওসমান বের হাতে বন্দি কাদি বুরহানেদ্দিন সিভাসের সমর্পণের বিনিময়ে মুক্তির প্রস্তাব দিলেও শহরের জনগণ প্রতিরোধ করল এবং সুলতান প্রাচীরের সামনে মৃত্যুদণ্ডপ্রাপ্ত হলেন। সিভাসের নেতৃবৃন্দ তাঁর ছেলে আলাউদ্দিন আলি চেলেবিকে ক্ষমতায় বসালেও আক্কোয়ুনলু চাপের মুখে ইলদিরিম বায়েজিদের কাছে সাহায্য চাইল; সুলায়মান চেলেবির নেতৃত্বাধীন অটোমান বাহিনী কারায়ুলুককে পরাজিত করে শহরের নিয়ন্ত্রণ নিল। এভাবে কাদি বুরহানেদ্দিন রাষ্ট্র ইতিহাসে বিলীন হলো এবং সিভাস, তোকাত, নিকসার ও কায়সেরি অটোমান ভূমির সঙ্গে যুক্ত হলো। একই তারিখে যুক্ত হওয়া অন্যান্য স্থান: কিরশেহির, চোরুম।", "2a0c7f3a"]},
"OLAYLAR_EK5:1399-11-01:0":{"b": ["তিমুরের চরমপত্র: পলাতকদের প্রত্যর্পণ প্রত্যাখ্যাত", "33790bc8"], "d": ["তিমুরের চাপে জালায়িরি সুলতান আহমেদ ও কারাকোইউনলু নেতা কারা ইউসুফ অটোমান ভূমিতে আশ্রয় নিলেন; তিমুর এই দুই পলাতকের প্রত্যর্পণ চাইলেন, ইলদিরিম বায়েজিদ প্রত্যাখ্যান করলেন। এতে দুই শাসকের মধ্যে পারস্পরিক ভারী অপমানসূচক চিঠি বিনিময় শুরু হলো। একজন সৈন্য নড়ার আগেই যুদ্ধের আদর্শিক ভিত্তি এই চিঠিপত্রে গড়ে উঠল।", "ac66be59"]},
"OLAYLAR_EK5:1400-01-01:0":{"b": ["বুরসায় ইলদিরিম দারুশশিফা — প্রথম অটোমান হাসপাতাল", "5f0dc59a"], "d": ["ইলদিরিম বায়েজিদ বুরসায় জাঁকজমকপূর্ণ উলুজামি নির্মাণের বছরগুলোতে শহরকে একটি দারুশশিফাও উপহার দিলেন; ইমারেত, মাদ্রাসা, সরাইখানা ও সেতু নিয়ে গঠিত বিস্তৃত জনকল্যাণ কর্মসূচির চিকিৎসায় নিবেদিত অংশ ছিল এটি। রাষ্ট্রের প্রতিষ্ঠিত প্রথম হাসপাতাল এই ভবন চিকিৎসক তৈরির মেডিকেল স্কুলের কাজও করে অটোমান স্বাস্থ্যপ্রতিষ্ঠানের আদর্শ নির্ধারণ করল। আঙ্কারার বিপর্যয়ের মাত্র দুই বছর আগে সম্পন্ন এই কীর্তি বায়েজিদের বুরসাকে সাম্রাজ্যিক রাজধানীতে রূপান্তরের পরিকল্পনার শেষ ধাপগুলোর একটি।", "5765ebac"]},
"OLAYLAR_EK5:1400-08-01:0":{"b": ["তিমুর সিভাস ধূলিসাৎ করলেন", "f4d79de6"], "d": ["আকক্কোইউনলু কারায়ুলুক ওসমান বে ও এরজিনজানের আমির মুতাহারতেনের পথপ্রদর্শনে সিভাসের দিকে অগ্রসর তিমুর শহর আঠারো দিন অবরোধ করলেন এবং কারও রক্তপাত হবে না এই প্রতিশ্রুতিতে আত্মসমর্পণ নিয়ে বড় গণহত্যা চালালেন; রক্ষীদের পরিখায় ভরে জীবন্ত চাপা দিলেন। প্রাচীরসহ শহরের গুরুত্বপূর্ণ নিদর্শন ধ্বংস হলো, সিভাস জনসংখ্যাগতভাবে ভেঙে পড়ল। এটি আঙ্কারা যুদ্ধের দুই বছর আগে তিমুরের অটোমান ভূমিতে হানা প্রথম বড় আঘাত।", "8ddb3e3a"]},
"OLAYLAR_EK5:1401-02-01:0":{"b": ["ইলদিরিম বায়েজিদ এরজিনজান ও কেমাহ পুনরুদ্ধার করলেন", "7047ca08"], "d": ["তিমুরের সিরিয়া অভিযানে বেরোনোকে সুযোগ হিসেবে নেওয়া ইলদিরিম বায়েজিদ তিমুরের অধীন এরজিনজানের আমির মুতাহারতেনের হাত থেকে এরজিনজান ও কেমাহ নিলেন। সিভাসের ধ্বংসে হস্তক্ষেপ না করা সত্ত্বেও এই পদক্ষেপ তিমুরের পূর্ব আনাতোলিয়ার প্রভাব বলয়কে সরাসরি চ্যালেঞ্জ করার অর্থ বহন করত। দুই শাসকের সম্পর্ক এরপর মেরামতের অযোগ্য হলো।", "2160d645"]},
"OLAYLAR_EK5:1402-03-13:0":{"b": ["তিমুরের তাবরিজ থেকে পাঠানো আল্টিমেটাম — চার শর্ত", "3e1ac50e"], "d": ["তিমুর তাবরিজ থেকে পাঠানো দূতের মাধ্যমে চার শর্ত জানালেন: কেমাহ মুতাহারতেনকে ফেরত, আনাতোলীয় বেগদের কাছ থেকে নেওয়া ভূমি মালিকদের ফেরত, একজন অটোমান শাহজাদাকে জামিন পাঠিয়ে টুপি ও কোমরবন্ধ অধীনতার চিহ্ন হিসেবে গ্রহণ এবং কারা ইউসুফকে সমর্পণ। বায়েজিদ এর কোনোটিই মানলেন না; রাষ্ট্রনায়কদের পীড়াপীড়ি ও মুতাহারতেনের মধ্যস্থতা সত্ত্বেও আলোচনা ভেঙে পড়ল। তিমুর চীন অভিযানে যাওয়ার আগে আনাতোলিয়া সমস্যা চূড়ান্তভাবে বন্ধ করতে দৃঢ়সংকল্প ছিলেন।", "bd475bc3"]},
"OLAYLAR_EK5:1402-08-17:0":{"b": ["সারুহানোগলু পুনঃপ্রতিষ্ঠিত — মানিসা অটোমানদের থেকে বেরিয়ে গেল", "ac747b05"], "d": ["আঙ্কারা পরাজয়ের তিন সপ্তাহ পর তিমুরের সমর্থনে ওরহান বে বেগলিকের শীর্ষে বসলেন এবং সারুহান প্রদেশ আবার স্বাধীন হলো। মানিসা কেন্দ্রিক অঞ্চল 1390 সালের অটোমান অন্তর্ভুক্তির বারো বছর পর মানচিত্র থেকে বেরিয়ে গেল। এটি তিমুরের বেগলিক পুনরুজ্জীবন নীতির নিশ্চিত তারিখ জানা প্রথম প্রয়োগগুলোর একটি।", "9fe5744d"]},
"OLAYLAR_EK5:1402-08-20:0":{"b": ["আমির সুলেইমান রাষ্ট্রীয় কোষাগারসহ রুমেলিতে পালালেন", "0a2b7363"], "d": ["বুরসার রাষ্ট্রীয় কোষাগার, নথিপত্র, পরিবার ও ভাইদের সঙ্গে নিয়ে আমির সুলেইমান জেমলিক থেকে জাহাজে গুজেলচে হিসারে (আনাদোলু হিসার) গেলেন, সেখান থেকে গালিপোলিতে পৌঁছে এডির্নে সার্বভৌমত্ব ঘোষণা করলেন। রাষ্ট্রীয় আর্কাইভ ও কোষাগারের রুমেলিতে স্থানান্তর অটোমান ভারকেন্দ্রের এক প্রজন্ম ধরে বলকানে সরে যাওয়ার সূচনা। মানচিত্রে রুমেলি এই তারিখ থেকে আমির সুলেইমানের নিজস্ব রঙে আঁকা হয়।", "393aa053"]},
"OLAYLAR_EK5:1402-09-15:0":{"b": ["তিমুর আনাতোলীয় বেগলিকগুলো পুনঃপ্রতিষ্ঠা করলেন — তুর্কি ঐক্য ভাঙল", "15187774"], "d": ["আঙ্কারা বিজয়ের পর তিমুর সঙ্গে থাকা বেগদের পুরোনো ভূমি ফিরিয়ে দিলেন। কারামানোগলু মেহমেদ ও আলী বেগকে কারামান প্রদেশ ও কাইসেরি, কিরশেহির, সিভরিহিসার ও বেইশেহির; গেরমিয়ানোগলু দ্বিতীয় ইয়াকুব বেগকে কুতাহিয়া ও গেরমিয়ান প্রদেশ; জান্দারোগলু ইসফেন্দিয়ার বেগকে কাস্তামোনু-সিনোপ রেখার সঙ্গে চানকিরি ও কালেজিক দেওয়া হলো। আইদিন, মেন্তেশে ও তেকে প্রদেশও পুরোনো রাজবংশে ফিরল। ইলদিরিম বায়েজিদের দশ বছরে গড়া আনাতোলীয় তুর্কি ঐক্য একই গ্রীষ্মে ভেঙে গেল; মানচিত্রে এই বেগলিকগুলো আবার নিজ রঙে দেখা দেয়।", "3a86d489"]},
"OLAYLAR_EK5:1402-12-14:0":{"b": ["তিমুর ইজমির সেন্ট জন নাইটদের কাছ থেকে নিলেন", "66dd1dd4"], "d": ["কুতাহিয়া, দেনিজলি, আইদিন, আয়াসুলুক ও তিরে হয়ে পশ্চিমে নামা তিমুর 1344 থেকে খ্রিস্টানদের হাতে থাকা উপকূলীয় ইজমির অবরোধ করে দখল করলেন। ইলদিরিম বায়েজিদ বছরের পর বছর দখল করতে না পারা এই দুর্গ তিমুর অল্প সময়ে দখল করে আশপাশের দুর্গও নেওয়ার পর আইদিন প্রদেশ পুরোনো মালিকদের ছেড়ে পূর্বে ফিরলেন। শহর এরপর আইদিনোগলু জুনেইদ বেগের শাসনে গেল।", "b6c372a5"]},
"OLAYLAR_EK5:1402-12-20:0":{"b": ["ঈসা চেলেবি বুরসা দখল করলেন — আনাতোলীয় অংশের জন্ম", "955128c1"], "d": ["আঙ্কারা পরাজয়ের পর কারেসি অঞ্চলে সরে যাওয়া ঈসা চেলেবি তিমুর ইজমিরে থাকাকালে বুরসা দখল করলেন। তিমুরের সৈন্যদের লুণ্ঠিত ও পোড়ানো পুরোনো রাজধানীতে সার্বভৌমত্ব ঘোষণা করলেন এবং নিজের নামে মুদ্রা ছাপালেন; জানুয়ারি 1403-এ আনাতোলিয়ায় 'তুর্কিদের শাসক' উপাধিতে স্বীকৃত ছিলেন। মানচিত্রে মারমারার এশীয় তীর বরাবর বিস্তৃত এই অংশ ঈসা চেলেবির নিজস্ব রঙে দেখা যায়।", "fdd5eed3"]},
"OLAYLAR_EK5:1403-03-15:0":{"b": ["তিমুরের আনাতোলিয়া ত্যাগ", "93a98839"], "d": ["ইলদিরিম বায়েজিদ আকশেহিরে মারা গেছেন খবর পেয়ে তিমুর আনাতোলিয়ার কাজ শেষ ধরে পূর্বে ফিরলেন। পেছনে রইল তাঁর প্রতি আনুগত্য জানানো বেগলিকগুলো ও পরস্পরের বিরুদ্ধে দাঁড়ানো অটোমান শাহজাদারা; সিভাসের মতো কিছু শহর তিমুরের অধীন মেজিদ বের মতো আমিরদের হাতে ছেড়ে দেওয়া হলো। তিমুর আর আনাতোলিয়ায় ফেরেননি, তবে তাঁর গড়া এই খণ্ডিত ব্যবস্থা দশ বছর টিকল।", "646cb1bc"]},
"OLAYLAR_EK5:1404-03-01:0":{"b": ["আমির সুলেইমান আনাতোলিয়ায় গেলেন: বুরসা তাঁর হাতে এলো", "9b27aa5f"], "d": ["ঈসা চেলেবির পরাজয় শুনে আমির সুলেইমান চান্দারলি আলী পাশার সঙ্গে শক্তিশালী সেনাবাহিনী নিয়ে আনাতোলিয়ায় গিয়ে বুরসা দখল করলেন; মার্চ 1404 নথি কারাদেনিজ এরেগলিও তাঁর শাসনে ছিল দেখায়। অল্প সময়ে রুমেলি ও আনাতোলিয়ার বড় অংশে কর্তৃত্ব স্থাপনকারী সুলেইমানের বিরুদ্ধে চেলেবি মেহমেদ দাঁড়াতে পারলেন না। মানচিত্রে এই তারিখ থেকে চেলেবি মেহমেদের বুরসা পুনর্দখল (1410) পর্যন্ত দুই তীর এক রঙে, আমির সুলেইমানের অংশে দেখা যায়।", "bca67f28"]},
"OLAYLAR_EK5:1405-01-01:0":{"b": ["ইয়েনিশেহির সমভূমির যুদ্ধ — চেলেবি মেহমেদ আমাসিয়ায় সরে গেলেন", "f1568288"], "d": ["বুরসা ও আঙ্কারা হারানো চেলেবি মেহমেদ ইয়েনিশেহির সমভূমিতে আমির সুলেইমানের কাছে পরাজিত হয়ে পশ্চিম আনাতোলিয়ার সব অর্জন হারালেন এবং তোকাত-আমাসিয়া ঘাঁটিতে সরে গেলেন। এই পরাজয়ের পর সরাসরি সংঘর্ষ এড়িয়ে আনাতোলিয়ার অভ্যন্তরে কর্তৃত্ব দৃঢ় করায় মনোনিবেশ করলেন। ফেত্রেতের দীর্ঘতম নীরব পর্ব এভাবে শুরু হলো।", "8c8a3c8c"]},
"OLAYLAR_EK5:1406-01-01:0":{"b": ["আমির সুলায়মান চেলেবি মেহমেদের কাছ থেকে আঙ্কারা দখল করলেন", "d6a2acd6"], "d": ["তৈমুরের আনাতোলিয়া ত্যাগের পর চেলেবি মেহমেদের হাতে থাকা আঙ্কারা 1406 সালে আমির সুলায়মান অবরোধ করেন। দুর্গরক্ষক ইয়াকুব বে কিছুকাল প্রতিরোধ করলেও উজির-ই-আজম চান্দারলি আলি পাশার এক কৌশলে দুর্গটি সুলায়মানের হাতে সমর্পণ করেন। এর পর চেলেবি মেহমেদ কারামানওগলু মেহমেদ বের সঙ্গে চুক্তি করে সুলায়মানের বিরুদ্ধে অভিযানে নামেন।", "f2a18bf9"]},
"OLAYLAR_EK5:1408-06-01:0":{"b": ["চেলেবি মেহমেদ তৈমুরি মেজিদ বের কাছ থেকে সিভাস পুনরুদ্ধার করলেন", "90079b0c"], "d": ["তৈমুরের আক্রমণের পর সিভাসের শাসন তৈমুরের অনুগত মেজিদ বের হাতে ছেড়ে দেওয়া হয়েছিল। আমাসিয়ায় অবস্থানরত চেলেবি মেহমেদ তাঁর সেনাপতি বায়েজিদ পাশাকে শহর দখলের জন্য পাঠালেন এবং তীব্র প্রতিরোধের পর সিভাস দ্বিতীয়বারের মতো অটোমান রাজবংশের হাতে এল। এভাবে আঙ্কারার যুদ্ধের ছয় বছর পর মেহমেদের অংশ পূর্বে তার পুরোনো সীমানায় পৌঁছাল।", "22c266b9"]},
"OLAYLAR_EK5:1409-01-01:0":{"b": ["আর্তুকি রাজবংশের অবসান: মারদিনের কারাকোয়ুনলুদের হাতে সমর্পণ", "15b06f33"], "d": ["1106 সাল থেকে মারদিনে শাসনকারী এবং রাজবংশের সবচেয়ে দীর্ঘজীবী শাখা আর্তুকিরা আক্কোয়ুনলু চাপের মুখে টিকতে পারল না। শহর রক্ষা করা সম্ভব নয় বুঝতে পেরে মালিক আহমেদ কারাকোয়ুনলু শাসক কারা ইউসুফের সঙ্গে চুক্তি করে মারদিন তাঁর কাছে সমর্পণ করলেন। তিন শতাব্দীরও বেশি আর্তুকি কর্তৃত্ব এভাবে শেষ হলো; মারদিন ও তার আশপাশ এক শতাব্দী পর অটোমানদের হাতে যাওয়া পর্যন্ত কারাকোয়ুনলু-আক্কোয়ুনলু সংগ্রামের মঞ্চ হলো।", "52e31654"]},
"OLAYLAR_EK5:1410-02-13:0":{"b": ["ইয়ানবোলু যুদ্ধ — মুসা চেলেবি এডির্নে প্রবেশ করলেন", "8f978408"], "d": ["ওয়ালাচিয়া হয়ে রুমেলিয়ায় পৌঁছানো মুসা চেলেবি ওয়ালাচিয়া ও সার্বিয়ার সমর্থনে ইয়ানবোলুতে আমির সুলায়মানের বাহিনীকে পরাজিত করে এডির্নে প্রবেশ করলেন। ফেতরেত যুগে রুমেলিয়া প্রথমবারের মতো আমির সুলায়মানের হাতছাড়া হলো। তবে তাঁর কর্তৃত্ব স্থায়ী হয়নি; চার মাস পর কসমিডিয়নে পরাজিত হয়ে তাঁকে বলকানের অভ্যন্তরে সরে যেতে হবে।", "e80e7126"]},
"OLAYLAR_EK5:1412-10-01:0":{"b": ["ইনজেগিজ যুদ্ধ — চেলেবি মেহমেদের রুমেলিয়ায় প্রথম পরাজয়", "3c35cd43"], "d": ["বাইজেন্টাইনদের জাহাজে রুমেলিয়ায় পৌঁছানো চেলেবি মেহমেদ ইনজেগিজে মুসা চেলেবির সঙ্গে যুদ্ধে জড়ালেন; মুসা তাঁর অধীনস্থ সাত হাজার জ্যানিসারি নিয়ে মেহমেদকে পরাজিত করলেন এবং মেহমেদ আনাতোলিয়ায় ফিরে যেতে বাধ্য হলেন। এই পরাজয় মেহমেদকে সরাসরি যুদ্ধের বদলে রুমেলিয়ার উচ বে ও সার্বিয়ান ডেসপটকে নিজের পক্ষে টানার কৌশলের দিকে ঠেলে দিল। নয় মাস পরের চামুর্লু বিজয়ের ভিত্তি এই কূটনীতির মাধ্যমেই প্রস্তুত হয়েছিল।", "dd443a98"]},
"OLAYLAR_EK5:1415-03-01:0":{"b": ["কনিয়া অবরোধ ও কারামানওগুল্লারের সঙ্গে চুক্তি — হামিদ-ইলি, সাইদ-ইলি, বেইশেহির, সেইদিশেহির ও আকশেহির পুনরুদ্ধার", "0996257e"], "d": ["ফেতরেত যুগে অটোমান ভূমিতে আক্রমণ চালানো এবং বুরসা অবরোধ করে পুড়িয়ে দেওয়া কারামানওগুল্লারের বিরুদ্ধে চেলেবি মেহমেদ বড় অভিযান সংগঠিত করে মুহাররম 818-এ কনিয়া অবরোধ করলেন। কারামানওগলু দ্বিতীয় মেহমেদ বে শান্তি চাইতে বাধ্য হলেন; চুক্তির ফলে হামিদ-ইলি (ইসপার্তা অঞ্চল) ও সাইদ-ইলি আবার অটোমান ভূমির সঙ্গে যুক্ত হলো, বেইশেহির, সেইদিশেহির ও আকশেহিরও ফিরিয়ে দেওয়া হলো; 1402 সালে তৈমুর কারামানওগুল্লারকে যে সিভ্রিহিসার দিয়েছিলেন তাও অটোমানদের কাছে ফিরে এল। আঙ্কারার যুদ্ধে ভেঙে পড়া আনাতোলিয়ার ঐক্য জোড়া লাগতে শুরু করা এই অভিযান চেলেবি মেহমেদকে 'দ্বিতীয় প্রতিষ্ঠাতা' গণ্য করার বাস্তব কারণগুলোর একটি।", "952c9f73"]},
"OLAYLAR_EK5:1415-06-01:0":{"b": ["আইদিনওগলু জুনেইদ বের কাছ থেকে ইজমির দখল", "2377ca51"], "d": ["ফেতরেত কালে শাহজাদাদের মধ্যে বারবার পক্ষ বদলানো আইদিনওগলু জুনেইদ বের কেন্দ্র ইজমির দশ দিনের অবরোধের পর চেলেবি মেহমেদ দখল করলেন; জুনেইদকে ক্ষমা করে নিগবোলুর সানজাক বে পদে পাঠানো হলো। 1402 সালে তৈমুর আইদিনওগুল্লারকে যে শহর ফিরিয়ে দিয়েছিলেন, তা এভাবে তেরো বছর পর অটোমানদের কাছে ফিরে এল। জুনেইদ 1422 সালে শহরটি আবার দখল করবেন, আর বিষয়টি কেবল 1424-1426 সালে দ্বিতীয় মুরাদ চূড়ান্তভাবে নিষ্পত্তি করবেন।", "41fefe61"]},
"OLAYLAR_EK5:1416-01-01:0":{"b": ["তোরলাক কেমালের মৃত্যুদণ্ড — সারুহান চূড়ান্তভাবে অটোমানদের হলো", "8a09dbf1"], "d": ["শেখ বেদরেদ্দিন আন্দোলনের পশ্চিম আনাতোলিয়া শাখার নেতৃত্বদানকারী তোরলাক কেমাল মানিসা অঞ্চলে পরাজিত হয়ে মৃত্যুদণ্ডপ্রাপ্ত হলেন। এর পর সারুহান অঞ্চল চূড়ান্তভাবে অটোমান নিয়ন্ত্রণে এল এবং 1402 সালে তৈমুর যে বেগলিক পুনরুজ্জীবিত করেছিলেন তা ইতিহাসে বিলীন হলো। ফেতরেত যুগের পশ্চিম আনাতোলিয়ার শেষ রাজনৈতিক অবশেষগুলো এভাবে মুছে গেল।", "43bec619"]},
"OLAYLAR_EK5:1417-01-01:0":{"b": ["ভলোরা, বেরাত ও কানিনা বিজয়", "1e1949b8"], "d": ["অটোমানরা 1417 সালে আদ্রিয়াটিক উপকূলের ভলোরাকে দেশের অভ্যন্তরের বেরাত শহর ও কানিনা দুর্গসহ নিজেদের কর্তৃত্বে নিল। এক বছর পর ভেনিসের শহর পুনর্দখলের চেষ্টা ব্যর্থ হলো এবং এখানে সানজাক ব্যবস্থা গড়ে তুলে অটোমান কর্তৃত্ব স্থায়ী করা হলো। ভলোরা দখল অটোমানদের প্রথমবারের মতো আদ্রিয়াটিকে সরাসরি বন্দরের মালিক বানিয়ে ইতালির বিপরীতে সমুদ্রপারের একটি লাফের ঘাঁটি এনে দিল।", "508b9927"]},
"OLAYLAR_EK5:1419-01-01:0":{"b": ["মধ্য আনাতোলিয়া পুনরুদ্ধার: কায়সেরি ও কিরশেহির", "204eacb3"], "d": ["ফেতরেত যুগে কারামানওগুল্লারের হাতে যাওয়া মধ্য আনাতোলিয়ার শহরগুলো চেলেবি মেহমেদের রাষ্ট্রকে পুনর্গঠনের অভিযানকালে অটোমান শাসনে ফিরে এল। কায়সেরি ও কিরশেহিরের অন্তর্ভুক্তির ফলে আঙ্কারার যুদ্ধে হারানো কিজিলিরমাক অববাহিকা বহুলাংশে পুনরুদ্ধার হলো। এই অগ্রগতি চার বছর আগের কনিয়া অবরোধ দিয়ে শুরু হওয়া পূর্বমুখী নীতিরই ধারাবাহিকতা।", "c663fc08"]},
"OLAYLAR_EK5:1419-01-28:0":{"b": ["মামলুকরা কায়সেরি দুলকাদিরলি নাসিরুদ্দিন মুহাম্মদকে দিল", "aad4b00c"], "d": ["কারামানওগলু মেহমেদ বের বিরুদ্ধে অভিযানে বের হওয়া মামলুক বাহিনী কায়সেরি দখল করল; মামলুক সেনাপতি শহর ও তার আশপাশ দুলকাদিরলি নাসিরুদ্দিন মুহাম্মদের হাতে ছেড়ে দিয়ে নিজ দেশে ফিরে গেলেন।", "8cd84dc4"]},
"OLAYLAR_EK5:1421-06-25:0":{"b": ["প্রথম মেহমেদের মৃত্যু ও দ্বিতীয় মুরাদের সিংহাসনারোহণ", "98acac77"], "d": ["ফেত্রেত যুগ শেষ করে অটোমান দেশকে আবার এক হাতে একত্র করা প্রথম মেহমেদ 25 জুন 1421 এডির্নে মারা যান এবং তাঁর পুত্র মুরাদ বুরসায় সিংহাসনে বসেন। মৃত্যুর আগে বাইজেন্টাইনদের সঙ্গে করা ব্যবস্থা অনুযায়ী ছোট পুত্রদের জিম্মি হিসেবে সম্রাটের কাছে পাঠানো হবে, সম্রাটও হাতে থাকা সিংহাসনপ্রার্থী মুস্তাফা চেলেবিকে মুক্তি দেবেন না; দ্বিতীয় মুরাদ ভাইদের সম্রাটের কাছে পাঠাতে অস্বীকার করেন।", "c8093fa8"]},
"OLAYLAR_EK5:1423-01-01:0":{"b": ["তেকেওগুল্লারের চূড়ান্ত অবসান: আন্তালিয়া দখল", "e65565b2"], "d": ["আঙ্কারার যুদ্ধের পর তৈমুরের পুনরুজ্জীবনে নতুন করে গড়ে ওঠা তেকেওগুল্লার বেগলিক হামজা বের নেতৃত্বাধীন অটোমান বাহিনীর আন্তালিয়া অবরোধে শেষ হলো; বেগলিকের শেষ গুরুত্বপূর্ণ ব্যক্তি ওসমান চেলেবিকে সরিয়ে দেওয়া হলো। এভাবে ভূমধ্যসাগর উপকূলের তেকে-ইলি একুশ বছরের বিচ্ছিন্নতার পর চূড়ান্তভাবে অটোমানদের সঙ্গে যুক্ত হলো। বেগলিকটি হামিদওগুল্লার থেকে বেরিয়ে আসা শাখা হিসেবে 1321 সাল থেকে আন্তালিয়ায় শাসন করছিল।", "6b81398d"]},
"OLAYLAR_EK5:1423-05-01:0":{"b": ["তুরাহান বের মোরিয়া অভিযান ও হেক্সামিলিয়ন প্রাচীরের পতন", "c6c2706d"], "d": ["বাইজেন্টাইনদের প্রতিদ্বন্দ্বী সিংহাসনপ্রার্থী মুস্তাফা চেলেবিকে সমর্থন করায় দ্বিতীয় মুরাদ তুরাহান বেকে মোরিয়ার বিরুদ্ধে পাঠালেন। তুরাহান বে করিন্থ যোজককে এক প্রান্ত থেকে আরেক প্রান্ত পর্যন্ত বন্ধ করা হেক্সামিলিয়ন প্রাচীর ভেঙে উপদ্বীপে প্রবেশ করে বিপুল ধ্বংস ঘটালেন। শান্তি এই শর্তে হলো যে প্রাচীর আর নির্মিত হবে না এবং বার্ষিক কর দিতে হবে; মোরিয়া ডেসপটেট এভাবে সামরিকভাবে অরক্ষিত হয়ে পড়ায় 1460 সালের চূড়ান্ত বিজয়ের ভিত্তি সাঁইত্রিশ বছর আগেই প্রস্তুত হলো।", "3482eb23"]},
"OLAYLAR_EK5:1424-01-01:0":{"b": ["আথোস (আইনারোজ) মঠগুলোর অটোমান আশ্রয়ে প্রবেশ", "562de5ea"], "d": ["থেসালোনিকি অবরুদ্ধ থাকার বছরগুলোতে চালকিদিকির পূর্ব আঙুলে অবস্থিত আথোস মঠ প্রজাতন্ত্র দ্বিতীয় মুরাদের কাছে আবেদন করে আশ্রয় চাইল এবং অটোমান কর্তৃত্ব মেনে নিল। সন্ন্যাসীদের সম্পত্তি ও উপাসনার অধিকার নিশ্চিত করা হলো; কর প্রদানের বিনিময়ে মঠগুলোকে অভ্যন্তরীণ বিষয়ে স্বাধীন রাখা হলো। এই ব্যবস্থা অটোমানদের অর্থোডক্স প্রতিষ্ঠানগুলোর সঙ্গে গড়ে তোলা আশ্রয় সম্পর্কের সবচেয়ে দীর্ঘস্থায়ী দৃষ্টান্ত হলো এবং পাঁচ শতাব্দী স্থায়ী হলো।", "6be1a9f2"]},
"OLAYLAR_EK5:1427-01-01:0":{"b": ["তাজেদ্দিনওগুল্লার বেগলিকের অন্তর্ভুক্তি: নিকসার", "370ffd47"], "d": ["আমাসিয়ার বেইলারবেই ইয়ার্গুচ পাশার চাপে তাজেদ্দিনওগলু হুসামেদ্দিন হাসান বে নিকসার কেন্দ্রিক তাঁর দেশের চাবিগুলো 830 (1427) সালে সমর্পণ করলেন; তাঁকে রুমেলিয়ায় একটি সানজাক দেওয়া হলো। চতুর্দশ শতাব্দীর দ্বিতীয়ার্ধে প্রতিষ্ঠিত এবং সীমানা মাঝে মাঝে কেলকিত, আমাসিয়া, সামসুন, ওর্দু ও গিরেসুন পর্যন্ত বিস্তৃত বেগলিকটি এভাবে শেষ হলো। একই বছর হাজিএমিরওগুল্লারের ভূমিও জরিপ করে চানিক সানজাকের সঙ্গে যুক্ত করা হলো; মধ্য কৃষ্ণ সাগরের বেগলিকের যুগ সমাপ্ত হলো।", "06fa8222"]},
"OLAYLAR_EK5:1427-01-01:1":{"b": ["বেলগ্রেডের হাঙ্গেরিকে ছেড়ে দেওয়া — তাতা চুক্তি", "62481183"], "d": ["সার্ব ডেসপট স্তেফান লাজারেভিচের মৃত্যুতে হাঙ্গেরীয় রাজা সিগিসমুন্ড ও উত্তরাধিকারী গিওর্গ ব্রানকোভিচের মধ্যে হওয়া তাতা চুক্তি অনুযায়ী বেলগ্রেড দুর্গ হাঙ্গেরির হাতে ছাড়া হলো। দানিয়ুব ও সাভার মিলনস্থলে দাঁড়ানো দুর্গ সেদিন পর্যন্ত সার্ব ডেসপটেটের হাতে ছিল এবং অটোমানদের জন্য মধ্য ইউরোপের দরজার তালা ছিল। এই হস্তান্তর বেলগ্রেডকে একশো বছর অটোমান অগ্রগতির সামনে সবচেয়ে কঠিন বাধা করল: 1440 ও 1456 সালের অবরোধ ব্যর্থ হবে, দুর্গ কেবল 1521 সালে পড়বে।", "ee1ad2d8"]},
"OLAYLAR_EK5:1432-01-01:0":{"b": ["মারদিন কারাকোয়ুনলু রক্ষী থেকে আক্কোয়ুনলু কারায়ুলুক ওসমান বের হাতে গেল", "d82bc97f"], "d": ["কারা ইউসুফ 1409 সালে দখল করা মারদিন কারাকোয়ুনলুরা গভর্নরদের দিয়ে শাসন করল; রক্ষী হিসেবে রেখে যাওয়া আমির নাসির শহরটি 835 (1432) সালে আক্কোয়ুনলু কারায়ুলুক ওসমান বের কাছে সমর্পণ করলেন। আক্কোয়ুনলু শাসন ষোড়শ শতাব্দীর শুরু পর্যন্ত চলল।", "407382cb"]},
"OLAYLAR_EK5:1435-01-01:0":{"b": ["কারামানওগুল্লার দুলকাদিরলিদের কাছ থেকে কায়সেরি দখল করল", "2b09e8e8"], "d": ["কারামানের বে দুলকাদিরলিদের বিরুদ্ধে অর্জিত বিজয়ে কায়সেরি, উরগুপ, দেভেলি কারাহিসার ও উচহিসার নিজ দেশে যুক্ত করলেন।", "39a543cc"]},
"OLAYLAR_EK5:1446-05-05:0":{"b": ["বুচুকতেপে ঘটনা — প্রথম জ্যানিসারি বিদ্রোহ এবং দ্বিতীয় মুরাদের সিংহাসনে প্রত্যাবর্তন", "6388dda1"], "d": ["এডির্নে ফেটে পড়া এবং ইতিহাসের জানা প্রথম জ্যানিসারি বিদ্রোহ বুচুকতেপে ঘটনা, বেতন (উলুফে) আধা আকচে বাড়ানোর দাবিতে শুরু হয়ে তরুণ দ্বিতীয় মেহমেদের সিংহাসনচ্যুতিতে শেষ হলো। দ্বিতীয় মুরাদ 8 সাফার 850-এ মানিসা থেকে দ্রুত রওনা হয়ে তাঁর দ্বিতীয় রাজত্ব শুরু করলেন। ঘটনাটি কাপিকুলু বাহিনী এখন সিংহাসনের ওপর কথা বলার মতো শক্তিতে পরিণত হয়েছে তার প্রথম ইঙ্গিত হলো এবং মেহমেদের জ্যানিসারিদের প্রতি আজীবন স্থায়ী সতর্কতা গড়ে তুলল।", "c03ef4f8"]},
"OLAYLAR_EK5:1449-01-01:0":{"b": ["এপিরাস উপকূলের অন্তর্ভুক্তি: আর্তা ও প্রেভেজা", "796f7ecf"], "d": ["1430 সালে ইয়ানিনার আত্মসমর্পণের উনিশ বছর পর এপিরাস ডেসপটেটের উপকূলীয় অংশের আর্তা ও প্রেভেজাও অটোমান শাসনের অধীনে এল। এভাবে আয়োনীয় সাগরে উন্মুক্ত আম্ব্রাসিয়া উপসাগর নিয়ন্ত্রণে এল এবং ইয়ানিনার সমুদ্রসংযোগ সম্পূর্ণ হলো। প্রেভেজা এমন এক উপসাগরের মূল ঘাঁটি, যা নব্বই বছর পর বারবারোসার ঐতিহাসিক বিজয়ের নাম বহন করবে।", "b5e95ae5"]},
"OLAYLAR_EK5:1451-02-18:0":{"b": ["দ্বিতীয় মুরাদের মৃত্যু এবং দ্বিতীয় মেহমেদের দ্বিতীয়বার সিংহাসনারোহণ", "8f8256ad"], "d": ["ছেলের বিয়ের পর অসুস্থ হয়ে পড়া দ্বিতীয় মুরাদ 1 মুহাররম 855-এ (3 ফেব্রুয়ারি 1451) এডির্নে মারা গেলেন। উনিশ বছর বয়সী দ্বিতীয় মেহমেদ 16 মুহাররম 855-এ (18 ফেব্রুয়ারি 1451) দ্বিতীয়বারের মতো অটোমান সিংহাসনে আরোহণ করলেন — এবার স্থায়ীভাবে। পাঁচ বছর আগে বুচুকতেপেতে সিংহাসনচ্যুত তরুণ শাসকের প্রত্যাবর্তন দুই বছর পর কনস্টান্টিনোপল বিজয়ে মুকুটপ্রাপ্ত হবে এবং অটোমান বেগলিককে বিশ্বসাম্রাজ্যে রূপান্তরিত করা রাজত্বের সূচনা।", "5363b0f7"]},
"OLAYLAR_EK5:1454-07-14:0":{"b": ["অটোমান-ক্রিমীয় যৌথ বাহিনীর প্রথম কাফা অবরোধ", "e346d163"], "d": ["1454 সালের জুনে সুলতান দ্বিতীয় মেহমেদের সঙ্গে চুক্তি করা ক্রিমিয়ার খান হাজি গিরাই 7000 অশ্বারোহী নিয়ে স্থলপথে কাফা অবরোধ করলেন; পঞ্চাশ-ষাটটি গ্যালির একটি অটোমান নৌবহরও উপকূলের কাছে অবস্থান নিল। জেনোয়ার কাফা কর দিয়ে অবরোধ উঠিয়ে নিল এবং চূড়ান্ত বিজয় একুশ বছর পর 1475 সালে হলো। এই প্রথম যৌথ অভিযান অটোমান-ক্রিমীয় সামরিক সহযোগিতার প্রথম দৃষ্টান্ত, যা পরে কাফার চূড়ান্ত বিজয়ে পুনরাবৃত্ত হবে।", "bf590b3e"]},
"OLAYLAR_EK5:1455-01-01:0":{"b": ["উত্তর এজিয়ান দ্বীপপুঞ্জ দখল: বজ্জাআদা, ইমরোজ ও থাসোস", "76575895"], "d": ["কনস্টান্টিনোপল বিজয়ের ঠিক পরেই সুলতান দ্বিতীয় মেহমেদ নতুন রাজধানীর সমুদ্রপথ সুরক্ষিত করতে চানাক্কালে প্রণালীর এজিয়ান মুখের দ্বীপগুলোর দিকে এগোলেন; বজ্জাআদা ও ইমরোজ বাইজেন্টাইনদের কাছ থেকে, থাসোস জেনোয়া বংশোদ্ভূত গাত্তিলুসিও পরিবারের কাছ থেকে নেওয়া হলো। প্রণালীর দুই তীর আটকে দেওয়া এই দ্বীপগুলো এর পর ইস্তানবুলের রসদ ও প্রতিরক্ষা রেখার প্রথম কড়া হলো। পোপতন্ত্র ও ভেনিসের নৌবহরের হস্তক্ষেপে কর্তৃত্ব কিছুকাল হাত বদলাল এবং কেবল 1459 সালে চূড়ান্ত হলো।", "9a34e8f0"]},
"OLAYLAR_EK5:1455-06-01:0":{"b": ["কসোভো বিজয়: প্রিশটিনা ও ইয়েনিপাজার দখল", "d7ed2345"], "d": ["সার্বিয়ান ডেসপটেটের বিরুদ্ধে অগ্রসর অটোমান সেনাবাহিনী কসোভো সমভূমির প্রিশটিনা এবং রাশকা অঞ্চলের কেন্দ্র ইয়েনিপাজার দখল করল; একই অভিযানে রুপার খনির জন্য বিখ্যাত নোভো ব্রদোও নেওয়া হলো। এভাবে সার্বিয়ার দক্ষিণ অর্ধেক সরাসরি অটোমান শাসনে যুক্ত হলো এবং সেমেন্দিরেতে ডেসপটের কেন্দ্র তার ভূমি থেকে বিচ্ছিন্ন হলো। এই বিজয় চার বছর পর সার্বিয়ার সম্পূর্ণ সংযুক্তির পথে নির্ধারক পদক্ষেপ ছিল।", "b2c7fcce"]},
"OLAYLAR_EK5:1456-01-01:0":{"b": ["ইপেক (পেচ) অটোমান শাসনে প্রবেশ করল — দুকাকিন সানজাকের কেন্দ্রগুলোর একটি", "19511588"], "d": ["1455 সালে সুলতান দ্বিতীয় মেহমেদের সার্বিয়া অভিযানের ঠিক পরে সার্বিয়ান প্যাট্রিয়ার্কেটের কেন্দ্র ইপেক অটোমান শাসনে গেল; অটোমান সূত্রে এই হস্তান্তর সম্পর্কে কোনো নথি নেই। শহরটি কালক্রমে ছোট একটি মুসলিম শহরে পরিণত হলো এবং দুকাকিন সানজাকে সানজাক বের বাসস্থানগুলোর একটি হলো।", "4d7160f6"]},
"OLAYLAR_EK5:1456-01-24:0":{"b": ["এনেজ ও সামোথ্রেস বিজয় — পশ্চিম থ্রেস উপকূলের সম্পূর্ণতা", "106e723b"], "d": ["মেরিচ নদী সাগরে মেশার স্থানে অবস্থিত এনেজ আশি বছর ধরে এটি ধরে রাখা জেনোয়া বংশোদ্ভূত গাত্তিলুসিও পরিবারের কাছ থেকে নেওয়া হলো; এর সঙ্গে যুক্ত সামোথ্রেস দ্বীপও একই অভিযানে দখল করা হলো। এনেজের পতনে পশ্চিম থ্রেস উপকূলরেখা থেসালোনিকি থেকে গালিপোলি পর্যন্ত অবিচ্ছিন্ন অটোমান ভূমিতে পরিণত হলো। গাত্তিলুসিও পরিবারের হাতে কেবল মিডিলি রইল; তাও ছয় বছর পর নেওয়া হবে।", "327297a0"]},
"OLAYLAR_EK5:1456-07-22:0":{"b": ["বেলগ্রেড অবরোধের ব্যর্থতা", "3d53a604"], "d": ["সুলতান দ্বিতীয় মেহমেদ কনস্টান্টিনোপল বিজয়ের পর মধ্য ইউরোপের তালা গণ্য বেলগ্রেড অবরোধ করলেন; কিন্তু ইয়ান হুনিয়াদির দানিয়ুব থেকে আনা সাহায্য এবং ক্রুসেডার ধর্মপ্রচারক কাপিস্ত্রানোর সংগৃহীত স্বেচ্ছাসেবকরা দুর্গের পতন ঠেকাল। সুলতান অবরোধের সামনে ব্যক্তিগত বীরত্ব দেখালেও আহত হয়ে পিছু হটতে বাধ্য হলেন। এই ব্যর্থতা পঁয়ষট্টি বছর হাঙ্গেরীয় সীমান্ত অটোমান অগ্রগতির জন্য বন্ধ রাখবে; বেলগ্রেড কেবল 1521 সালে কানুনি দখল করতে পারবেন।", "036836cb"]},
"OLAYLAR_EK5:1458-05-01:0":{"b": ["উত্তর মোরিয়া বিজয়: পাত্রাস", "c08a8509"], "d": ["সার্বিয়া সংযুক্ত হওয়ার একই বছরগুলোতে মোরিয়া ডেসপটেটের দিকে অভিযানকারী সুলতান দ্বিতীয় মেহমেদের বাহিনী উপদ্বীপের উত্তর-পশ্চিমের পাত্রাস দখল করল। করিন্থ উপসাগরের মুখ নিয়ন্ত্রণকারী এই বন্দর মোরিয়ায় স্থলপথে প্রবেশের চাবিকাঠি; এর দখল দুই বছর পরের চূড়ান্ত বিজয়ের ভিত্তি প্রস্তুত করল। শহরটি ছিল বাইজেন্টাইন ডেসপটদের ল্যাটিন বিশ্বের সঙ্গে যোগাযোগের শেষ বড় ঘাট।", "4490cc14"]},
"OLAYLAR_EK5:1459-06-20:0":{"b": ["পশ্চিম কৃষ্ণ সাগর উপকূল দখল: আমাসরা", "f43608fc"], "d": ["পশ্চিম কৃষ্ণ সাগরে জেনোয়ার সুরক্ষিত উপনিবেশ আমাসরা সুলতান দ্বিতীয় মেহমেদের নৌবহর ও স্থলবাহিনীর যৌথ চাপে প্রতিরোধ ছাড়াই আত্মসমর্পণ করল। বার্তিন-জঙ্গুলদাক উপকূলের এই বন্দর চান্দারওগুল্লার ও অটোমান ভূমির মাঝখানে ল্যাটিনদের একটি ছোট ঘাঁটি হয়ে দাঁড়িয়েছিল; দখলের ফলে উপকূল অখণ্ড হলো। আমাসরার পতন দুই বছর পর (1461) সিনোপ ও ত্রাবজোনের দিকে পরিচালিত বড় কৃষ্ণ সাগর অভিযানের প্রথম ধাপ।", "b8b9f4f0"]},
"OLAYLAR_EK5:1462-09-17:0":{"b": ["মিডিলি দ্বীপ বিজয়", "fe17aeba"], "d": ["সুলতান দ্বিতীয় মেহমেদের নেতৃত্বাধীন অটোমান সেনাবাহিনী জিলহজ্জ 866-এ মিডিলিকে সংক্ষিপ্ত কিন্তু তীব্র অবরোধের পর জেনোয়া বংশোদ্ভূত গাত্তিলুসিও পরিবারের হাত থেকে নিয়ে সংযুক্ত করল। উত্তর এজিয়ানের বৃহত্তম দ্বীপের পতন জেনোয়াবাসীদের অঞ্চলে শেষ গুরুত্বপূর্ণ ঘাঁটিও মুছে দিল। দ্বীপ আনাতোলিয়া উপকূলের নিকটতার কারণে এর পর অটোমান নৌবহরের অগ্রবর্তী চৌকির কাজ করবে এবং বারবারোস ভাইদের বেড়ে ওঠার স্থান হিসেবে নৌইতিহাসে স্থান পাবে।", "453088e2"]},
"OLAYLAR_EK5:1463-07-28:0":{"b": ["ষোলো বছরের অটোমান-ভেনিস যুদ্ধের সূচনা", "563ddb68"], "d": ["ভেনিসীয়রা অটোমানদের মোরিয়া ও এজিয়ানে অগ্রগতি থামাতে কারামান ও আক্কোয়ুনলু শাসকদের সঙ্গে জোট বেঁধে 1463 সালে যুদ্ধ শুরু করল। পূর্বে উজুন হাসান, পশ্চিমে ভেনিস এবং মাঝখানে কারামানের সঙ্গে গড়া এই বেষ্টনী কৌশল দ্বিতীয় মেহমেদকে একই সময়ে একাধিক ফ্রন্টে লড়তে বাধ্য করল। ষোলো বছর স্থায়ী এই সংগ্রাম ওতলুকবেলি থেকে আলবেনিয়া অভিযান পর্যন্ত সেই সময়ের সব বড় অভিযান অন্তর্ভুক্ত করবে এবং কেবল 1479 সালের ইস্তানবুল চুক্তিতে শেষ হবে।", "e70079e9"]},
"OLAYLAR_EK5:1466-01-01:0":{"b": ["হারজেগোভিনার বড় অংশ বিজয়: ত্রেবিনিয়ে ও মোস্তার", "f54c0100"], "d": ["বসনিয়া থেকে আলাদা প্রশাসন গড়া হারজেগোভিনার ডিউক স্তেপান ভুকচিচ-কোসাচার ভূমি বসনিয়া রাজ্যের পতনের তিন বছর পর বহুলাংশে অটোমান শাসনে গেল: দক্ষিণে ত্রেবিনিয়ে 1466 সালে 'প্রায় সমগ্র হারজেগোভিনা অঞ্চলসহ' দখল করা হলো। নেরেতভা সেতুর দুটি ছোট দুর্গকে ঘিরে গড়ে ওঠা মোস্তারও হারজেগোভিনার কেন্দ্র ব্লাগাইয়ের 1466-1468 সালের বিজয়ের অল্প আগে দখল হয়ে থাকবে; 1468-1469 সালের বসনিয়া সংক্ষিপ্ত জরিপে 'কোপ্রুলু হিসার' নামে নথিভুক্ত আছে। ডিউকত্বের অবশিষ্ট দুর্গসহ হারজেগোভিনা বিজয় 1483 সালে সম্পন্ন হলো।", "a7f22be7"]},
"OLAYLAR_EK5:1466-06-01:0":{"b": ["দ্বিতীয় আলবেনিয়া অভিযান — স্কান্দারবেগের বিরুদ্ধে সুলতানের স্বয়ং অভিযান", "9cdd2bfa"], "d": ["স্কান্দারবেগের সিকি শতাব্দীর বেশি সময়ের প্রতিরোধ ভাঙতে সুলতান দ্বিতীয় মেহমেদ 1466-1467 সালে নিজে নেতৃত্ব দিয়ে বড় অভিযান সংগঠিত করলেন। অটোমান সেনাবাহিনী আকচাহিসার (ক্রুয়ে) অবরোধ করল এবং অঞ্চল নিয়ন্ত্রণে আনতে ইলবাসান (এলবাসান) দুর্গ নির্মাণ করল। অভিযান আলবেনীয় প্রতিরোধের মেরুদণ্ড ভাঙলেও দুর্গ ফেলতে পারল না; অঞ্চলের পূর্ণ অধীনতা স্কান্দারবেগের মৃত্যুর পর দশ বছর লাগল।", "00e75aca"]},
"OLAYLAR_EK5:1467-10-01:0":{"b": ["আককোয়ুনলু অগ্রবাহিনী বিংগোল দুর্গ কারাকোয়ুনলুদের কাছ থেকে নিল", "51b94cbc"], "d": ["জিহান শাহের উজুন হাসানের বিরুদ্ধে অভিযানের শেষ সপ্তাহগুলোতে আককোয়ুনলু অগ্রবাহিনী বিংগোল দুর্গ দখল করে; 10 নভেম্বর 1467 জিহান শাহ নিহত হলে অঞ্চলে কারাকোয়ুনলু কর্তৃত্বের অবসান ঘটে।", "c150063d"]},
"OLAYLAR_EK5:1467-11-10:0":{"b": ["কারাকোয়ুনলু রাষ্ট্রের পতন: জিহান শাহের হত্যা", "30bc6358"], "d": ["উজুন হাসানের বিরুদ্ধে অভিযানে বের হয়ে শীতের চাপে ফেরার পথে আক্রান্ত হওয়া কারাকোয়ুনলু শাসক জিহান শাহ বিঙ্গোল ও কিগির মাঝখানে পালানোর সময় নিহত হলেন। এই আঘাতের পর রাষ্ট্র আর সামলে উঠতে পারেনি; শেষ শাসক হাসান আলি 1469 সালে উজুন হাসানের ছেলে উগুরলু মেহমেদের হাতে বন্দি হয়ে নিহত হলেন। পূর্ব আনাতোলিয়া, আজারবাইজান ও ইরাকে প্রায় এক শতাব্দী শাসনকারী কারাকোয়ুনলু কর্তৃত্ব এভাবে আক্কোয়ুনলুদের হাতে গেল।", "5a5288e7"]},
"OLAYLAR_EK5:1468-01-17:0":{"b": ["স্কান্দারবেগের মৃত্যু — আলবেনীয় প্রতিরোধের নিভে যাওয়া", "9158c35f"], "d": ["অটোমান প্রাসাদে বেড়ে ওঠা অথচ 1444 সালে ইজলাদি পরাজয়ের পর বিদ্রোহ করে সিকি শতাব্দীর বেশি সময় আলবেনিয়ায় প্রতিরোধ করা স্কান্দারবেগ আশ্রয় নেওয়া লেজেতে মারা গেলেন। দ্বিতীয় মুরাদ ও দ্বিতীয় মেহমেদের আমলে অটোমান সেনাবাহিনীকে বারবার ব্যস্ত রাখা এই প্রতিরোধ তাঁর মৃত্যুতে কেন্দ্রীয় নেতৃত্ব হারাল। পোপতন্ত্র ও ভেনিসের লালিত আলবেনীয় ফ্রন্টের পতনে অটোমানরা দশ বছরের মধ্যে আকচাহিসার ও ইশকোদ্রা দখল করে অঞ্চলটি চূড়ান্তভাবে নিজেদের ভূমিতে যুক্ত করল।", "5c7cffad"]},
"OLAYLAR_EK5:1474-01-01:0":{"b": ["কায়সেরিতে অটোমান শাসন প্রতিষ্ঠিত: গেদিক আহমেদ পাশা কারামানোগুল্লারিকে শেষ করলেন", "33cf35fc"], "d": ["গেদিক আহমেদ পাশার 1474 সালে কারামানোগুল্লারি বংশের অবসানের ফলে কায়সেরি অটোমান শাসনে আসে; শহরটি পঞ্চদশ শতক জুড়ে দুলকাদিরোগুল্লারি, রামাজানোগুল্লারি ও কারামানোগুল্লারির মধ্যে হাত বদল হয়েছিল। অটোমান শাসনে কায়সেরি কারামান বেইলারবেইলিকের সানজাক কেন্দ্র হয়।", "5d1db169"]},
"OLAYLAR_EK5:1475-01-01:0":{"b": ["সামোস পরিত্যক্ত: জেনোয়ীয় (মাওনা) মালিকানার অবসান", "5bdc380c"], "d": ["টিডিভি অনুযায়ী দ্বীপটি 1475-এর পর পরিত্যক্ত হয়; 1479 সালে বিজেতা সুলতান মেহমেদ দ্বীপ জয় করে দুর্গ নির্মাণ করান।", "4e48c423"]},
"OLAYLAR_EK5:1475-01-10:0":{"b": ["মলদোভায় রাকোভা (ভাসলুই) পরাজয়", "a1a74bf7"], "d": ["মলদোভার ভয়েভোদা স্তেফান চেল মারে রুমেলি বেইলারবেই হাদিম সুলায়মান পাশার নেতৃত্বাধীন অটোমান বাহিনীকে জলাভূমিতে টেনে এনে ভারী পরাজয় ঘটালেন। দ্বিতীয় মেহমেদের আমলের সবচেয়ে ভারী স্থলযুদ্ধের পরাজয়গুলোর একটি এই বিপর্যয় ইউরোপে বড় সাড়া জাগাল এবং স্তেফানকে ক্রুসেডার জগতে খ্যাতি এনে দিল। সুলতান পরের বছর প্রতিশোধ নিতে নিজেই অভিযানে বের হবেন।", "3247c9fe"]},
"OLAYLAR_EK5:1476-07-26:0":{"b": ["আকদেরে (ভালিয়া আলবা) বিজয় — মলদোভা অভিযান", "45a66791"], "d": ["এক বছর আগের রাকোভা পরাজয়ের প্রতিশোধ নিতে নিজেই অভিযানে বের হওয়া সুলতান দ্বিতীয় মেহমেদ অটোমান সেনাবাহিনী দিয়ে মলদোভা বাহিনীকে আকদেরে স্থানে বড় পরাজয়ে ফেললেন এবং বেগলিকের কেন্দ্র সুচেভায় প্রবেশ করলেন। তবে দুর্গগুলো দখল করা গেল না; রসদ সংকট, জ্যানিসারিদের মধ্যে দেখা দেওয়া প্লেগ ও হাঙ্গেরীয় প্রস্তুতির কারণে সেনাবাহিনীকে পিছু হটতে হলো। মলদোভার চূড়ান্ত আনুগত্য কেবল পরবর্তী বছরগুলোতে এবং 1484 সালে কিলিয়া ও আক্কিরমান দখলের মাধ্যমে নিশ্চিত হবে।", "27b9dd1c"]},
"OLAYLAR_EK5:1478-06-15:0":{"b": ["আকচাহিসার (ক্রুয়ে) বিজয় এবং আলবেনিয়া বিজয়ের সমাপ্তি", "559a79b4"], "d": ["স্কান্দারবেগের মৃত্যুর দশ বছর পর 1478 সালে আকচাহিসার, দ্রিভাস্তো, লেজে ও জাবিয়াক দখলের মাধ্যমে আলবেনিয়া বিজয় বহুলাংশে সম্পন্ন হলো। বছরের পর বছর অটোমান বাহিনীকে প্রতিরোধ করা এবং স্কান্দারবেগ প্রতিরোধের প্রতীক ক্রুয়ে দুর্গের পতন অঞ্চলে ভেনিস-আলবেনীয় জোটের অবসান বোঝাল। অবশিষ্ট ইশকোদ্রা পরের বছর স্বাক্ষরিত ইস্তানবুল চুক্তির মাধ্যমে অটোমানদের হাতে ছেড়ে দেওয়া হবে।", "4f6059e8"]},
"OLAYLAR_EK5:1479-01-01:0":{"b": ["তামান উপদ্বীপের অন্তর্ভুক্তি", "4ef917b8"], "d": ["1475 সালে কাফা ও কের্চ দখলের পর সুলতান দ্বিতীয় মেহমেদ ককেশাস উপকূলে যে নৌবহর পাঠালেন, তা আনাপা ও কোপার সঙ্গে তামান উপদ্বীপের জেনোয়ার ঘাঁটি মাত্রেগা (তামাতারহান) দখল করল। এভাবে প্রণালীর দুই তীরই নিয়ন্ত্রণে এল এবং আজভ সাগরে প্রবেশ সম্পূর্ণ নিয়ন্ত্রিত হলো। উত্তর ককেশাসের দ্বার হিসেবে তামান কাফা সানজাকের সঙ্গে যুক্ত হলো।", "74a0de9f"]},
"OLAYLAR_EK5:1479-01-01:1":{"b": ["সামোসের অটোমান শাসনে প্রবেশ (বিজেতা মেহমেদ)", "c877bc14"], "d": ["বিজেতা সুলতান মেহমেদ সামোস জয় করেন, একটি দুর্গ নির্মাণ করান এবং জনগণনা নতুনভাবে সাজান; দুর্গটি দ্বিতীয় বায়েজিদ 1483 সালে রাজনৈতিক কারণে ভেঙে ফেলান।", "2965b1d9"]},
"OLAYLAR_EK5:1480-07-28:0":{"b": ["রোডস অবরোধের ব্যর্থতা", "35a85c28"], "d": ["সুলতান দ্বিতীয় মেহমেদের আদেশে মেসিহ পাশার নেতৃত্বাধীন 160 জাহাজের নৌবহর 885 (1480) সালের বসন্তে রোডস অবরোধ করল এবং দ্বীপ তিন মাস অবরুদ্ধ রইল। গ্র্যান্ড মাস্টার পিয়ের দ'অবুসনের নেতৃত্বাধীন সেন্ট জন নাইটরা ভারী ক্ষতি সত্ত্বেও তীব্র প্রতিরোধ করলেন; 20 জুমাদাল-উলা 885-এ সংঘটিত শেষ বড় আক্রমণও প্রতিহত হলে নৌবহর 3 আগস্ট সরে গেল। এই ব্যর্থতার পর শহরের প্রাচীর নতুন করে নির্মাণ করে ইউরোপের সবচেয়ে শক্তিশালী দুর্গে পরিণত করা হলো এবং দ্বীপ কেবল 1522 সালে কানুনি দখল করতে পারলেন।", "23334bd0"]},
"OLAYLAR_EK5:1481-01-01:0":{"b": ["ইকারিয়া (নিকারিয়া) রোডসের সেন্ট জন নাইটদের শাসনে এল", "5cbc2669"], "d": ["সামোস ও খিওসের মধ্যবর্তী ইকারিয়া 1481 থেকে 1521 পর্যন্ত রোডসের সেন্ট জন নাইটদের শাসনে ছিল।", "9d387479"]},
"OLAYLAR_EK5:1481-06-22:0":{"b": ["ইয়েনিশেহির যুদ্ধ — জেম সুলতানের পরাজয়", "c35abee2"], "d": ["দ্বিতীয় মেহমেদের মৃত্যুর পর সিংহাসনের জন্য অগ্রসর দুই ভাই ইয়েনিশেহির সমভূমিতে মুখোমুখি হলেন এবং জেম সুলতান চূড়ান্তভাবে পরাজিত হলেন। বুরসায় আঠারো দিন শাসন করে নিজের নামে খুতবা পাঠ করানো এই শাহজাদা পরাজয়ের পর প্রথমে কনিয়ায়, সেখান থেকে মামলুক ভূমিতে আশ্রয় নিতে বাধ্য হলেন। ইয়েনিশেহির অটোমান ইতিহাসের সবচেয়ে দীর্ঘস্থায়ী রাজবংশীয় সংকট শুরু করল: জেম সমস্যা চৌদ্দ বছর অটোমান পররাষ্ট্রনীতিকে ইউরোপের বিপরীতে অচল করে রাখবে।", "9d30204e"]},
"OLAYLAR_EK5:1482-01-01:0":{"b": ["হারজেগোভিনার সংযুক্তি", "bf247891"], "d": ["1463 সালে বসনিয়া বিজয়ের পর টিকে থাকা হারজেগোভিনা ডিউকত্বের ভূমি ধাপে ধাপে অটোমান শাসনে গেল: ত্রেবিনিয়ে ও মোস্তার 1466 সালে নেওয়া হয়েছিল, হারজেগোভিনা সানজাক 1470 সালে গঠিত হয়েছিল, ডিউকত্বের আদ্রিয়াটিক উপকূলের শেষ ভূমিও হেরসেকনভি (হেরসেগ নভি) সহ 1482 সালের শুরুতে বিজিত হয়ে সানজাকের সঙ্গে যুক্ত হলো। এভাবে আদ্রিয়াটিকের পেছনের পার্বত্য অঞ্চল সম্পূর্ণ অটোমানদের হলো এবং বসনিয়া ও হারজেগোভিনা একক প্রশাসনিক ভূগোলে পরিণত হলো। শেষ ডিউকের অটোমান প্রাসাদে প্রবেশ করা ছেলে ভবিষ্যতে সদরে আজম পদ পর্যন্ত উঠবেন সেই হেরসেকজাদে আহমেদ পাশা।", "0522e47f"]},
"OLAYLAR_EK5:1482-01-01:1":{"b": ["জাকিন্থোসের বার্ষিক করের বিনিময়ে ভেনিসকে ছেড়ে দেওয়া", "268a691a"], "d": ["দ্বিতীয় মেহমেদের আমলের শেষে তোক্কো পরিবারের কাছ থেকে নেওয়া আয়োনীয় দ্বীপপুঞ্জের জাকিন্থোস জেম সুলতান সমস্যায় জড়ানো নতুন সুলতানের পশ্চিমে শান্তি খোঁজার মধ্যে ভেনিসকে ছেড়ে দেওয়া হলো। দ্বীপ অটোমান সার্বভৌমত্ব স্বীকারকারী এবং বার্ষিক পাঁচ শত ডুকাট কর প্রদানকারী ভেনিসীয় শাসনের হাতে অর্পিত হলো। এভাবে আয়োনীয় সাগরে অটোমান সরাসরি শাসন কেবল আয়ামাভ্রায় রইল।", "0773761c"]},
"OLAYLAR_EK5:1482-07-29:0":{"b": ["জেম সুলতানের রোডসে আশ্রয়", "2228d6da"], "d": ["কনিয়া অবরোধের চেষ্টাও ব্যর্থ হওয়া জেম সুলতান ত্রিশজনের মতো অনুচর নিয়ে আনাতোলিয়া থেকে পালিয়ে রোডসে পৌঁছালেন এবং সেন্ট জন নাইটরা তাঁকে আনুষ্ঠানিকভাবে বরণ করলেন। কিন্তু অতিথেয়তা শিগগিরই বন্দিত্বে পরিণত হলো; শাহজাদাকে প্রথমে ফ্রান্সে, পরে পোপতন্ত্রের কাছে হস্তান্তর করা হলো এবং তিনি ইউরোপীয় রাজনীতির হাতে একটি তাসে পরিণত হলেন। দ্বিতীয় বায়েজিদ ভাইকে আটক রাখার বিনিময়ে বার্ষিক অর্থ দিতে বাধ্য হলেন এবং অটোমানদের পশ্চিমমুখী সামরিক পদক্ষেপ জেমের মৃত্যু পর্যন্ত স্থগিত রইল।", "05ca0dd6"]},
"OLAYLAR_EK5:1485-01-01:0":{"b": ["অটোমান-মামলুক যুদ্ধের সূচনা (চুকুরোভা ফ্রন্ট)", "3fe3f0c7"], "d": ["দুলকাদিরওগুল্লারের ওপর প্রভাব বিস্তারের সংগ্রাম এবং জেম সুলতানের মামলুক ভূমিতে আশ্রয় নেওয়ার রেখে যাওয়া শত্রুতা 1485 সালে দুই সুন্নি বড় শক্তির মধ্যে ছয় বছর স্থায়ী যুদ্ধ শুরু করল। চুকুরোভায় আদানা ও তারসুসের আশপাশে সংঘটিত সংঘর্ষে পক্ষগুলো একে অপরের ওপর প্রাধান্য পেল না; অটোমান সেনাবাহিনী কয়েকটি ভারী আঘাত পেল। এই যুদ্ধ অটোমান-মামলুক সম্পর্কের ভাঙনের প্রথম পর্ব এবং ত্রিশ বছর পর ইয়াভুজের মার্জ দাবিক ও রিদানিয়া অভিযানে সমাপ্ত হওয়া প্রক্রিয়ার সূচনা।", "08141630"]},
"OLAYLAR_EK5:1491-05-01:0":{"b": ["অটোমান-মামলুক শান্তি — তিউনিসের মধ্যস্থতা", "60dd6719"], "d": ["1485 সালে শুরু হওয়া অটোমান-মামলুক যুদ্ধে পক্ষগুলো নিশ্চিত বিজয় অর্জন করতে পারল না; তিউনিসের শাসক ওসমান হাফসির মধ্যস্থতায় 1491 সালে সমঝোতা হলো। চুক্তি সীমানা বহুলাংশে যুদ্ধের আগের অবস্থায় ফিরিয়ে দিল এবং দুই ইসলামি রাষ্ট্রের হিসাব-নিকাশ এক প্রজন্ম পিছিয়ে গেল। ছয় বছরের ক্ষয়কারী সংগ্রাম দ্বিতীয় বায়েজিদের সতর্ক পররাষ্ট্রনীতি এবং পূর্বে অগ্রসর না হয়ে অভ্যন্তরীণ সংস্কারে গুরুত্ব দেওয়ার প্রধান কারণগুলোর একটি।", "406d3b78"]},
"OLAYLAR_EK5:1492-08-01:0":{"b": ["স্পেন থেকে বিতাড়িত সেফারদি ইহুদিদের অটোমানদের গ্রহণ", "5c2b5c24"], "d": ["গ্রানাডার পতনের পর স্পেনে ইনকুইজিশনের নিপীড়ন থেকে পালানো ইহুদিদের একাংশ অটোমান ভূমিতে আশ্রয় নিয়ে বিভিন্ন শহরে বসতি পেল। অটোমান শাসনে এই সেফারদি সম্প্রদায়গুলো যেখানে খুশি বসবাস, নিজেদের বিশ্বাস পালন, শিক্ষাপ্রতিষ্ঠান খোলা এবং নতুন সিনাগগ নির্মাণের মতো আগে না দেখা স্বাধীনতা পেল। সঙ্গে আনা মুদ্রণ, চিকিৎসা ও অর্থবিজ্ঞানের জ্ঞানে থেসালোনিকি ও ইস্তানবুলের অর্থনৈতিক জীবন বদলে দেওয়া এই অভিবাসন অটোমান সহনশীলতা ব্যবস্থার ইউরোপে সবচেয়ে আলোচিত দৃষ্টান্ত হলো।", "b5b4a53b"]},
"OLAYLAR_EK5:1495-02-25:0":{"b": ["জেম সুলতানের মৃত্যু — চৌদ্দ বছরের জিম্মিত্বের অবসান", "f6588b70"], "d": ["পোপতন্ত্র থেকে ফ্রান্সের রাজা অষ্টম চার্লসের কাছে হস্তান্তরিত জেম সুলতান 27 জানুয়ারি 1495 সালে রোম থেকে রওনা হওয়ার পর কাস্তেল কাপুয়ানা নামের স্থানে মারা গেলেন; সূত্রগুলো পোপীয় মহলের হাতে বিষপ্রয়োগের সম্ভাবনার কথা লিখেছে। চৌদ্দ বছর ইউরোপীয় রাষ্ট্রগুলোর হাতে অটোমানদের বিরুদ্ধে হুমকির তাস হিসেবে রাখা শাহজাদার মৃত্যু দ্বিতীয় বায়েজিদের হাত অবশেষে মুক্ত করল। বস্তুত সুলতান এর পর ভেনিসের বিরুদ্ধে যুদ্ধ ঘোষণা করবেন এবং নৌবহরকে প্রথম বড় বিজয়ে নিয়ে যাবেন।", "8f2579d5"]},
"OLAYLAR_EK5:1499-08-28:0":{"b": ["সাপিয়েঞ্জা (জোনকিও) নৌবিজয় — ভূমধ্যসাগরে প্রথম বড় নৌবহর সাফল্য", "9754aaef"], "d": ["জেম সমস্যা শেষ হওয়ায় হাত মুক্ত পাওয়া দ্বিতীয় বায়েজিদ 1499 সালে ভেনিসের বিরুদ্ধে যুদ্ধ ঘোষণা করলেন; অটোমান নৌবহর সাপিয়েঞ্জা (জোনকিও) উপকূলে ভেনিসীয় বহরকে পরাজিত করে ভূমধ্যসাগরে প্রথম বড় নৌবিজয় অর্জন করল। এই বিজয়ে নৌবহর ঘোষণা করল যে এখন সে সমুদ্রে ভেনিসের মোকাবিলা করতে পারে।", "5fa6989c"]},
"OLAYLAR_EK5:1500-12-24:0":{"b": ["কেফালোনিয়া ও ইথাকার হারানো", "60f0f687"], "d": ["মোদন ও করন দখলে নাড়া খাওয়া ভেনিস স্পেনের সঙ্গে মিলে পাল্টা আক্রমণে গিয়ে 1479 সাল থেকে অটোমান হাতে থাকা কেফালোনিয়া অবরোধ করল। সাতচল্লিশ দিনের প্রতিরোধের পর দুর্গ পড়ল, দ্বীপ ইথাকাসহ ভেনিসের হাতে গেল এবং তিন শতাব্দী অটোমান শাসনে ফিরল না। এই ক্ষতি মোরিয়ায় অর্জিত লাভ আয়োনীয়তে ফিরিয়ে দেওয়া ভারসাম্য সৃষ্টি করল।", "a61731e0"]},
"OLAYLAR_EK5:1502-03-01:0":{"b": ["স্বর্ণ ঘোড়া খানাতের পতন এবং ক্রিমিয়ার উত্থান", "0d1dc515"], "d": ["শেষ শাসক শেখ আহমেদ খান (1481-1502) নিজের দেশকে পড়ে যাওয়া সংকট থেকে রক্ষা করতে পারলেন না এবং স্বর্ণ ঘোড়া খানাত 1502 সালে ক্রিমিয়ার খান মেংলি গিরাইয়ের আঘাতে ইতিহাসে বিলীন হলো। সিংহাসন-দ্বন্দ্ব ও বিভক্তির ফলে প্রাক্তন স্বর্ণ ঘোড়ার ভূমিতে ক্রিমিয়া, কাজান, নোগাই, আস্ত্রাখান ও সিবির খানাত উদ্ভূত হলো। অটোমান আশ্রয়ে থাকা ক্রিমিয়ার এই বিজয় কৃষ্ণ সাগরের উত্তরে অটোমান প্রভাবকে প্রশ্নাতীত করল, আর অঞ্চলে সৃষ্ট শূন্যতা পরবর্তী শতাব্দীতে মস্কো পূরণ করবে।", "9314f239"]},
"OLAYLAR_EK5:1502-12-14:0":{"b": ["অটোমান-ভেনিস যুদ্ধের সমাপ্তি ও শান্তি", "125b1526"], "d": ["1499 সালে শুরু হওয়া এবং সাপিয়েঞ্জা, লেপান্তো, মোদন ও করোনের হারানোয় ভেনিসকে নাড়িয়ে দেওয়া যুদ্ধ 1502 সালে শান্তিতে শেষ হলো। ভেনিস মোরিয়ার সবচেয়ে গুরুত্বপূর্ণ ঘাঁটিগুলো হারিয়ে পূর্ব ভূমধ্যসাগরে বাণিজ্যিক সুবিধা রক্ষার বিনিময়ে অটোমান শ্রেষ্ঠত্ব মেনে নিতে বাধ্য হলো। দ্বিতীয় বায়েজিদের সতর্ক গণ্য রাজত্ব এই যুদ্ধের মাধ্যমে অটোমানদের ভূমধ্যসাগরে প্রথমবারের মতো গুরুতর নৌশক্তির অবস্থানে উন্নীত করেছিল।", "3d102f53"]},
"OLAYLAR_EK5:1511-07-02:0":{"b": ["শাহকুলু বিদ্রোহ — তেকে অঞ্চল থেকে সিভাস পর্যন্ত বিস্তৃত কিজিলবাশ অভ্যুত্থান", "3beadca7"], "d": ["সাফাভি প্রচারণার আনাতোলিয়ায় প্রভাবে 1510 সালে বিদ্রোহ প্রকাশ করা শাহকুলু বাবা তেকেলি 1511 সালের মার্চে আন্তালিয়া বাজারে হামলা করেছিলেন এবং এপ্রিলে কুতাহিয়া ও আশপাশে অটোমান বাহিনীকে পরাজিত করেছিলেন। সিভাসের কাছে সদরে আজম হাদিম আলি পাশার সঙ্গে শেষ সংঘর্ষে দুই পক্ষই ভারী ক্ষতির মুখে পড়ল; সদরে আজম ও বিদ্রোহের নেতা দুজনেই প্রাণ হারালেন। রাষ্ট্রের আনাতোলিয়ায় কর্তৃত্ব নাড়িয়ে দেওয়া এই অভ্যুত্থান দ্বিতীয় বায়েজিদের শেষ বছরগুলোর ক্ষমতার শূন্যতা প্রকাশ করল এবং শাহজাদা সেলিমের সিংহাসনের দিকে অগ্রযাত্রার সবচেয়ে শক্তিশালী যুক্তি হলো।", "846180f5"]},
"OLAYLAR_EK5:1512-04-24:0":{"b": ["দ্বিতীয় বায়েজিদের সিংহাসন ত্যাগ এবং ইয়াভুজ সুলতান সেলিমের সিংহাসনারোহণ", "c4cfab69"], "d": ["ভাইদের সঙ্গে সিংহাসন-সংগ্রামে জ্যানিসারিদের সমর্থন পাওয়া শাহজাদা সেলিমের চাপে দ্বিতীয় বায়েজিদ 24 এপ্রিল 1512 সালে সিংহাসন ত্যাগ করলেন এবং প্রথম সেলিম একই দিনে নবম অটোমান শাসক হিসেবে সিংহাসনে বসলেন। বৃদ্ধ সুলতান জন্মস্থান ডিমেতোকায় যাওয়ার পথে চোরলুর কাছের আবালার গ্রামে 25 রাবিউল-আউয়াল 918-এ (10 জুন 1512) মারা গেলেন। একত্রিশ বছরের সতর্ক ও অন্তর্মুখী রাজত্বের জায়গা নিল আট বছরে সাম্রাজ্যের সীমানা দ্বিগুণ করা ইয়াভুজ যুগ।", "7194b8c2"]},
"OLAYLAR_EK5:1513-01-01:0":{"b": ["সিন (সিন্জ) দুর্গ বিজয়", "83271ea5"], "d": ["বসনিয়া সীমান্তের অটোমান আকিনজি বাহিনী দালমাটিয়ার অভ্যন্তরে প্রসারিত সিন (সিন্জ) দুর্গ হাঙ্গেরীয় রাজ্য থেকে নিল। এটি নয় বছর পর গাজি হুসরেভ বের কনিন ও আশপাশ বিজয়ে প্রসারিত হওয়া দালমাটিয়া সীমান্ত রেখার প্রাথমিক কড়া ছিল; দুর্গ 1686 সালে ভেনিসের কাছে হারাবে।", "28c20426"]},
"OLAYLAR_EK5:1513-04-01:0":{"b": ["ইয়েনিশেহির যুদ্ধ এবং শাহজাদা আহমেদের অপসারণ", "e2ed15dd"], "d": ["ইয়াভুজ সুলতান সেলিম সিংহাসনের সবচেয়ে শক্তিশালী প্রতিদ্বন্দ্বী বড় ভাই শাহজাদা আহমেদকে বুরসার কাছের ইয়েনিশেহির সমভূমিতে পরাজিত করে বন্দি করে সরিয়ে দিলেন। এভাবে 1511 সাল থেকে চলা ভাইয়ে ভাইয়ে দ্বন্দ্বের সমাপ্তি হলো, আনাতোলিয়ার অভ্যন্তরীণ বিভাজন শেষ হলো। সেলিম পেছন নিরাপদ করে সাফাভি প্রশ্নের দিকে মনোযোগ দেওয়ার স্বাধীনতা পেলেন।", "ed5f5ec0"]},
"OLAYLAR_EK5:1514-09-06:0":{"b": ["ইয়াভুজ সুলতান সেলিমের তাবরিজে প্রবেশ", "dad2e227"], "d": ["চালদিরান বিজয়ের পর অটোমান সেনাবাহিনী সাফাভি রাজধানী তাবরিজে প্রবেশ করল এবং শহরে খুতবা সুলতানের নামে পাঠ করা হলো। সেলিম এখানে এক সপ্তাহ থেকে তাবরিজের শিল্পী ও আলিমদের একাংশকে ইস্তানবুলে স্থানান্তরিত করালেন; এই স্থানান্তর অটোমান রাজদরবারের শিল্পকে গভীরভাবে প্রভাবিত করবে। শীত ঘনিয়ে আসা ও জ্যানিসারিদের অসন্তোষে শহর ত্যাগ করা হলেও পূর্বে সাফাভি শ্রেষ্ঠত্ব ভেঙে গিয়েছিল। মানচিত্রে এই দিনে অটোমানদের হাতে যাওয়া স্থানগুলো পরস্পর সংলগ্ন নয় এবং এটাই সঠিক: তাবরিজ নয় দিনের সেনা দখল; এরজিনজান সমভূমি অভিযানকালে বিনা যুদ্ধে আত্মসমর্পণ করেছিল, তার মাঝখানের কেমাহ দুর্গ 19 মে 1515 পর্যন্ত সাফাভিদের হাতে প্রতিরোধ করেছিল; সিইর্ত তাবরিজে শাহ ইসমাইলের কারাগার থেকে মুক্তি পাওয়া হাসানকেইফের মালিক খলিল বে অটোমানদের আনুগত্য করে সাফাভিদের কাছ থেকে ফিরিয়ে নিয়েছিলেন — এর আশপাশের দিয়ারবাকির 1515 সাল পর্যন্ত, হাসানকেইফ 1517 সাল পর্যন্ত সাফাভিদের ছিল।", "3f65211e"]},
"OLAYLAR_EK5:1515-02-25:0":{"b": ["মুশ ও বিংগোল (চাপাকচুর) সাফাভিদের কাছ থেকে অটোমান শাসনে গেল", "b0a53b5a"], "d": ["চালদিরানের পর পূর্ব আনাতোলিয়া সাফাভিদের কাছ থেকে নেওয়ার ফলে মুশ 921/1515 সালে অটোমান শাসনে আসে; পার্শ্ববর্তী চাপাকচুর (বিংগোল) একই প্রক্রিয়ায় অটোমানদের সঙ্গে যুক্ত হয়।", "9c979b3f"]},
"OLAYLAR_EK5:1515-05-19:0":{"b": ["সাফাভিদের কাছ থেকে কেমাহ দুর্গ বিজয়", "73fd8671"], "d": ["চালদিরান থেকে ফেরার পথে শীত আমাসিয়ায় কাটানো ইয়াভুজ সুলতান সেলিম ফুরাতের পারাপার স্থল ধরে রাখা সুরক্ষিত কেমাহ দুর্গ বিজয়ের দায়িত্ব বিয়িকলি মেহমেদ পাশাকে দিলেন। সুলতানের নিজে অংশ নেওয়া অবরোধের শেষে দুর্গ সাফাভিদের হাত থেকে নেওয়া হলো এবং পূর্ব আনাতোলিয়ার দ্বার খুলে গেল। এই বিজয় চালদিরান বিজয়কে স্থায়ী ভূমিলাভে রূপান্তরের প্রথম বাস্তব পদক্ষেপ।", "9e896ebe"]},
"OLAYLAR_EK5:1515-06-13:0":{"b": ["তুরনাদাগ বিজয় — দুলকাদির বেগলিক অটোমানদের অধীন হলো", "fd879145"], "d": ["অটোমান বাহিনী চালদিরান অভিযানকালে দ্বিধাগ্রস্ত অবস্থান নেওয়া দুলকাদির বে আলাউদ্দৌলা বোজকুর্তকে গোকসুন ও আন্দিরিনের মাঝখানের ওরদেকলি স্থানে পরাজিত করল; আলাউদ্দৌলা এই যুদ্ধে নিহত হলেন। বেগলিক এই তারিখে সংযুক্ত হয়নি: আলাউদ্দৌলার পর দুলকাদিরওগুল্লার বেগলিকের প্রধান হিসেবে ইয়াভুজ সুলতান সেলিম কর্তৃক শেহসুয়ারওগলু আলি বে বসানো হলো এবং মারাশ-এলবিস্তান কেন্দ্রিক দেশ অটোমানদের অধীন বেগলিক হিসেবে চলল। মামলুক সীমান্তের বাফার এভাবে অটোমান নিয়ন্ত্রণে এল এবং দুই বছর পরের মিসর অভিযানের পথ খুলল; সংযুক্তি আলি বের হত্যার পর ঘটবে।", "cf9c7460"]},
"OLAYLAR_EK5:1515-09-19:0":{"b": ["আমিদ (দিয়ারবাকির) বিজয় এবং দিয়ারবাকির বেইলারবেইত্বের প্রতিষ্ঠা", "a6867d5b"], "d": ["ইদ্রিস-ই বিতলিসির অঞ্চলের সুন্নি কুর্দি বেদের অটোমানদের পক্ষে আনার পর সাফাভি বাহিনী দীর্ঘ অবরোধ সহ্য করতে পারল না এবং আমিদের চাবি বিয়িকলি মেহমেদ পাশার কাছে সমর্পণ করা হলো। শহরকে নবগঠিত দিয়ারবাকির বেইলারবেইত্বের কেন্দ্র করা হলো। এভাবে উচ্চ মেসোপটেমিয়ার প্রশাসনিক কেন্দ্র অটোমানদের হাতে এল।", "70169bcc"]},
"OLAYLAR_EK5:1516-03-26:0":{"b": ["হারপুত বিজয় — দিয়ারবাকিরের পথ খোলা", "564eb269"], "d": ["চালদিরানের পর দখল করা দিয়ারবাকিরকে সাফাভি অবরোধ থেকে রক্ষা করতে রওনা হওয়া কারামান বেইলারবেই হুসরেভ পাশা আশপাশ আগেই চেরকেজ হুসেইন বে দখল করে নেওয়া হারপুত দুর্গ তিন দিনের অবরোধের শেষে নিলেন। ফুরাতের পূর্বে দিয়ারবাকির পর্যন্ত পথ এভাবে নিরাপদ হলো।", "eb738178"]},
"OLAYLAR_EK5:1516-05-01:0":{"b": ["কোচহিসার (কিজিলতেপে) যুদ্ধ — কারা খানের পরাজয়", "9ea9e843"], "d": ["বিয়িকলি মেহমেদ পাশার নেতৃত্বাধীন অটোমান সেনাবাহিনী কোচহিসারের কাছে দেদে গারকিন প্রান্তরের কোরুক স্থানে সাফাভি গভর্নর কারা খানকে সারা দিনব্যাপী এক খোলা যুদ্ধে পরাজিত করল; কারা খানের কাটা মাথা সুলতানের শিবিরে পাঠানো হলো। এর পর অটোমান বাহিনী মারদিন শহরে প্রবেশ করলেও কয়েক দিন থেকে চলে গেল; সাফাভি রক্ষীদের ধরে রাখা মারদিন দুর্গ কেবল এক বছর পর হস্তগত করা গেল। এই বিজয় ইয়াভুজের দক্ষিণ সীমান্ত নিরাপদ করে তাঁকে মিসর অভিযানের দিকে এগোনো সম্ভব করল। একই তারিখে যুক্ত হওয়া অন্যান্য স্থান: পালু, চেমিশগেজেক, সিভেরেক।", "6bc19ce1"]},
"OLAYLAR_EK5:1516-06-05:0":{"b": ["ইয়াভুজ সুলতান সেলিমের মিসর অভিযানের জন্য ইস্তানবুল থেকে যাত্রা", "ac258b4b"], "d": ["ইয়াভুজ সুলতান সেলিম বাহ্যত সাফাভিদের বিরুদ্ধে নতুন পূর্ব অভিযানের প্রস্তুতি নিয়ে ইস্তানবুল থেকে রওনা হলেন এবং আকশেহির হয়ে দক্ষিণে ঘুরলেন। মামলুক সুলতান কানসুহ গাউরির শাহ ইসমাইলের সঙ্গে যোগাযোগ স্থাপন এবং অটোমানদের পূর্ব পার্শ্বকে হুমকি দেওয়া লক্ষ্য শিগগিরই বদলে যাওয়ার কারণ হবে। এই অভিযান দুই বছর স্থায়ী হবে এবং অটোমানদের মধ্যপ্রাচ্যের সাম্রাজ্যে রূপান্তরিত করা বড় অভিযানের সূচনা।", "6b27f782"]},
"OLAYLAR_EK5:1516-06-20:0":{"b": ["জাবিদ দখল: অটোমান নাবিকদের লোহিত সাগরে প্রথম প্রবেশ", "38740e0c"], "d": ["ভারত মহাসাগরে পর্তুগালের চাপের মুখে মামলুক সুলতান কানসুহ গাউরির অনুরোধে লোহিত সাগরে পাঠানো অটোমান বংশোদ্ভূত নাবিক হুসেইন বে ও সালমান রাইস তাঁদের নৌবহর নিয়ে জাবিদ দখল করলেন। তখনো মামলুক সেবায় পরিচালিত এই অভিযান অটোমান নৌবাহিনীর লোহিত সাগর-ভারত রেখায় প্রথম বাস্তব উপস্থিতি। এক বছর পর মিসর অটোমানদের হাতে গেলে একই নৌবহর সরাসরি ইস্তানবুলের সঙ্গে যুক্ত হবে।", "f715b0aa"]},
"OLAYLAR_EK5:1516-07-30:0":{"b": ["অভিযানের লক্ষ্য মামলুক ও আলেপ্পো বলে আনুষ্ঠানিক ঘোষণা", "689e310d"], "d": ["কানসুহ গাউরি সাফাভিদের সঙ্গে চুক্তি করে সেনাবাহিনীকে আলেপ্পোর দিকে চালনা করায় ইয়াভুজ সুলতান সেলিম অভিযানের লক্ষ্য স্পষ্টভাবে মামলুক সুলতান ও আলেপ্পো বলে ঘোষণা করলেন। এভাবে দুই সুন্নি রাষ্ট্রের মধ্যে বছরের পর বছর চলা গোপন প্রতিদ্বন্দ্বিতা প্রকাশ্য যুদ্ধে পরিণত হলো। এই ঘোষণা মার্জ দাবিক পর্যন্ত চার সপ্তাহের উল্টো গণনা শুরু করল।", "f2a137f3"]},
"OLAYLAR_EK5:1516-08-02:0":{"b": ["আদেন অবরোধের ব্যর্থতা: পর্তুগালের বিরুদ্ধে প্রথম লোহিত সাগর প্রচেষ্টা", "8ffd46f2"], "d": ["সালমান রাইস ও হুসেইন বে লোহিত সাগরের ভারত মহাসাগরে উন্মুক্ত দ্বার আদেন দখলের জন্য আট দিনের অবরোধ চালালেন, কিন্তু শহরের শক্তিশালী দুর্গের সামনে পিছু হটতে বাধ্য হলেন। আদেন দখল না হওয়া পর্তুগালের বিরুদ্ধে পরিচালিত দক্ষিণ কৌশলকে বহু বছর ব্যাহত করবে। এই প্রচেষ্টা অটোমানদের মহাসাগর নীতিতে প্রথম পরীক্ষা।", "8b584b76"]},
"OLAYLAR_EK5:1516-08-24:0":{"b": ["রামাজানওগুল্লার বেগলিকের অটোমানদের সঙ্গে সংযুক্তি", "cfaa3754"], "d": ["মার্জ দাবিক বিজয়ের পর প্রদত্ত নিয়োগের সময় আদানাকেন্দ্রিক রামাজানওগুল্লার বেগলিক মাহমুদ বেকে দেওয়া হয়ে অটোমান কর্তৃত্বের অধীনে এল। মামলুক আনুগত্য থেকে বেরিয়ে আসা বেগলিকটিকে বিলুপ্ত না করে 'ওজাকলিক' মর্যাদায় পরিবারের হাতে রাখা হলো; রামাজানওগুল্লার চুকুরোভার শাসন অটোমান সানজাক বে হিসেবে চালিয়ে গেল। এই বিশেষ ব্যবস্থা পির মানসুরের বেগলিক ছেড়ে দেওয়া 1608 সাল পর্যন্ত চলল। একই তারিখে যুক্ত হওয়া অন্যান্য স্থান: মালাত্যা, তারসুস, মোসুল, আন্তেপ।", "af7c4758"]},
"OLAYLAR_EK5:1516-08-28:0":{"b": ["আলেপ্পো, রাক্কা ও দেইরুজ-জোর অটোমান কর্তৃত্বে প্রবেশ", "2088eb6a"], "d": ["মার্জ দাবিকের চার দিন পর ইয়াভুজ সুলতান সেলিম প্রতিরোধের মুখোমুখি না হয়ে আলেপ্পোয় প্রবেশ করলেন এবং শহরের মসজিদগুলোতে খুতবা তাঁর নামে পাঠ করা হলো। সিরিয়ার বাণিজ্যিক ও প্রশাসনিক রাজধানী গণ্য আলেপ্পোর এত দ্রুত পতন অঞ্চলে মামলুক কর্তৃত্ব ভেঙে পড়েছে তা দেখায়। শহর দখল দামেস্ক ও সেখান থেকে মিসর পর্যন্ত পথ এক মুহূর্তে খুলে দিল। একই তারিখে যুক্ত হওয়া অন্যান্য স্থান: আন্তাকিয়া, রাক্কা, দেইরুজ-জোর।", "6055ffc7"]},
"OLAYLAR_EK5:1516-08-29:0":{"b": ["আলেপ্পোর গোকমেইদানে আব্বাসীয় খলিফা তৃতীয় মুতাওয়াক্কিলের সঙ্গে সাক্ষাৎ", "22979f42"], "d": ["মার্জ দাবিকে মামলুক সেনাবাহিনীর সঙ্গে বন্দি হওয়া কায়রোর আব্বাসীয় খলিফা তৃতীয় মুতাওয়াক্কিলকে আলেপ্পোর গোকমেইদানে সুলতানের সামনে হাজির করা হলো এবং ইয়াভুজ সুলতান সেলিম তাঁকে অত্যন্ত সম্মান দেখালেন। 1261 সাল থেকে মামলুক সুলতানদের ছায়ায় প্রতীকী পদ হয়ে থাকা কায়রো খিলাফত এই সাক্ষাতে কার্যত অটোমান আশ্রয়ে গেল। খলিফাকে পরে সুলতানের সঙ্গে ইস্তানবুলে নিয়ে যাওয়া হবে।", "b1490892"]},
"OLAYLAR_EK5:1516-09-26:0":{"b": ["ত্রিপোলি ও হামার অটোমান শাসনে প্রবেশ", "a1e19a79"], "d": ["আলেপ্পো ও হামার পর সিরিয়া উপকূলের ত্রিপোলিও প্রতিরোধ ছাড়াই অটোমান শাসনের অধীনে গেল। পূর্ব ভূমধ্যসাগরের সবচেয়ে ব্যস্ত বন্দরগুলোর একটি এই শহর দামেস্কের সমুদ্রমুখী দরজা এবং রেশম ও চিনি বাণিজ্যের কেন্দ্র ছিল। এর দখলের ফলে বিলাদ আশ-শামের উপকূলরেখা পুরোপুরি হাতবদল হলো।", "57168655"]},
"OLAYLAR_EK5:1516-09-27:0":{"b": ["দামেস্কের (দিমাশক) অটোমান কর্তৃত্বে প্রবেশ", "2b844d91"], "d": ["আলেপ্পোর পর হামা ও হোমস আত্মসমর্পণ করায় পথ খোলা পাওয়া ইয়াভুজ সুলতান সেলিম 27 সেপ্টেম্বর দামেস্কের সামনে পৌঁছালেন; শহরে সঙ্গে সঙ্গে না ঢুকে বাইরে মাস্তাবা স্থানে তাঁবু ফেললেন এবং আগমনের বারো দিনের দিন বড় অনুষ্ঠানে ভেতরে প্রবেশ করলেন। দামেস্কে অনেকদিন থেকে সিরিয়ার প্রশাসনিক ব্যবস্থা গড়লেন এবং মুহিউদ্দিন ইবনুল-আরাবির সমাধি নির্মাণ করালেন। এভাবে বিলাদ আশ-শামের সবটাই মামলুক শাসন থেকে বেরিয়ে এল। একই তারিখে যুক্ত হওয়া অন্যান্য স্থান: বৈরুত।", "7cd1cd2b"]},
"OLAYLAR_EK5:1516-10-10:0":{"b": ["কায়রোতে তুমানবের মামলুক সুলতান ঘোষণা", "6020d90d"], "d": ["মার্জ দাবিকে নিহত কানসুহ গাউরির পর মামলুক আমিররা রাষ্ট্রের শেষ সুলতান হতে যাওয়া তুমানবেকে সিংহাসনে বসালেন। চেরকেস বংশোদ্ভূত নতুন সুলতান সিরিয়া হারানো, কোষাগার শূন্য এবং আগ্নেয়াস্ত্রহীন একটি রাষ্ট্র উত্তরাধিকার হিসেবে পেলেন। তবুও কায়রোর সামনে প্রতিরক্ষা রেখা গড়ে অটোমান অগ্রগতির বিরুদ্ধে শেষ প্রতিরোধ সংগঠিত করবেন।", "c55b45e9"]},
"OLAYLAR_EK5:1516-12-21:0":{"b": ["গাজা (হান ইউনুস) যুদ্ধ: কানবিরদি গাজালির পরাজয়", "9f1eb8cb"], "d": ["ইয়াভুজ সুলতান সেলিম চার হাজার সৈন্যের অগ্রবর্তী বাহিনীসহ সদরে আজম হাদিম সিনান পাশাকে গাজায় পাঠালেন। তুমানবে দ্বারা দামেস্কের নায়েব করা কানবিরদি গাজালি অটোমান অগ্রবর্তী দলকে গাজা-হান ইউনুস রেখায় থামাতে চাইলেও ভারী পরাজয়ের মুখে পড়লেন এবং মিসরে পালালেন। ফিলিস্তিনে শেষ মামলুক বাফার বাহিনী ছত্রভঙ্গ হওয়ায় সিনাই মরুভূমির পথ সম্পূর্ণ খুলে গেল।", "042a934e"]},
"OLAYLAR_EK5:1516-12-28:0":{"b": ["জর্ডানের পূর্বে: আম্মানের অটোমান শাসনে প্রবেশ", "9db62667"], "d": ["গাজা যুদ্ধের পর মিসর অভিযানের প্রস্তুতি নেওয়া অটোমান বাহিনী দক্ষিণে নামার সময় জর্ডান নদীর পূর্বের আম্মানও অটোমান শাসনের অধীনে এল। ফিলিস্তিনের উপকূলীয় ও অভ্যন্তরীণ শহরগুলো (জাফা, নাবলুস, সিডন, আক্কা, জেরুজালেম) অবশ্য মার্জ দাবিক যুদ্ধের পর 1516 সালের শরতেই হাতবদল হয়েছিল। এই শহরগুলো চার শতাব্দী ধরে দামেস্ক প্রদেশের সানজাক হিসেবে শাসিত হলো।", "fac75355"]},
"OLAYLAR_EK5:1516-12-29:0":{"b": ["ইয়াভুজ সুলতান সেলিমের জেরুজালেমে আগমন", "66d7bfad"], "d": ["মার্জ দাবিকের পর প্রতিরোধ ছাড়াই অটোমান শাসনে যাওয়া জেরুজালেমে গাজা যুদ্ধের পর ইয়াভুজ সুলতান সেলিম রাষ্ট্রের গণ্যমান্য ব্যক্তি ও সৈন্যসহ এলেন। সুলতান কুব্বাতুস-সাখরা ও মসজিদুল আকসা পরিদর্শন করে শহরের পবিত্র মর্যাদা নিশ্চিত করলেন। জেরুজালেম এই তারিখ থেকে ডিসেম্বর 1917 পর্যন্ত পুরো চার শতাব্দী অটোমান শাসনে থাকবে।", "42cf2ec1"]},
"OLAYLAR_EK5:1517-01-02:0":{"b": ["ইয়াভুজ সুলতান সেলিমের গাজায় প্রবেশ এবং সিনাই মরুভূমির দিকে যাত্রা", "2106bfc7"], "d": ["হান ইউনুসে কানবিরদি গাজালির পরাজয়ের (21 ডিসেম্বর 1516) পর গাজা অগ্রবর্তী বাহিনীর হাতে ছিল। সুলতান 2 জানুয়ারি 1517 সালে গাজায় প্রবেশ করে এখানে অগ্রবর্তী বাহিনীর প্রধান সিনান পাশার সঙ্গে মিলিত হলেন এবং সেনাবাহিনী মিসরে পারাপারের শেষ প্রস্তুতি নিল। গাজা থেকে সালিহিয়া পর্যন্ত বিস্তৃত পানিহীন কাতিয়া (সিনাই) মরুভূমিতে আট মঞ্জিল হাঁটতে হবে, উটে করে পানি বহন করতে হবে। এই পারাপার অভিযানের সবচেয়ে ঝুঁকিপূর্ণ ও রসদের দিক থেকে সবচেয়ে কঠিন পর্ব।", "5c3d7bc1"]},
"OLAYLAR_EK5:1517-01-24:0":{"b": ["সুয়েজ দখল — লোহিত সাগরের দ্বার", "05f3324e"], "d": ["রিদানিয়ার বিজয়ের পর অটোমান বাহিনী কায়রোয় প্রবেশ করায় লোহিত সাগরের উত্তর প্রান্তের সুয়েজও অটোমান শাসনে গেল। মামলুকরা ভারত মহাসাগরে নৌবহর পাঠাত এই নৌঘাঁটি-বন্দর পর্তুগালের বিরুদ্ধে পরিচালিত দক্ষিণ নীতির ঘাঁটিতে পরিণত হলো। সুয়েজ তিন শতাব্দী পর খাল খোলা হবে যে রেখায়, তার উত্তর মুখ।", "501facb1"]},
"OLAYLAR_EK5:1517-01-24:1":{"b": ["অটোমান বাহিনীর কায়রোয় প্রথম প্রবেশ", "0a3f4f4d"], "d": ["রিদানিয়া বিজয়ের পরদিন অটোমান সেনাবাহিনীকে কায়রোয় প্রবেশের অনুমতি দেওয়া হলো এবং 24 জানুয়ারি বাহিনী শহরে অবস্থান নিল। তবে এই প্রবেশ শহরের পূর্ণ নিয়ন্ত্রণ বোঝাত না; তুমানবে উচ্চ মিসরে সরে গিয়েছিলেন, মামলুক প্রতিরোধ তখনো ভাঙেনি। কায়রো বিজয় একদিনে নয়, সপ্তাহব্যাপী রক্তাক্ত প্রক্রিয়ায় সম্পন্ন হবে।", "32d9401c"]},
"OLAYLAR_EK5:1517-01-27:0":{"b": ["তুমানবের কায়রো আক্রমণ এবং তিন দিনের রাস্তার যুদ্ধ", "b83b6ce6"], "d": ["উচ্চ মিসরে সরে যাওয়া তুমানবে সঙ্গে থাকা প্রায় সাত হাজার জনকে নিয়ে 27-28 জানুয়ারির রাতে হঠাৎ কায়রোয় প্রবেশ করে শহরের ভেতরে প্রতিরোধ শুরু করলেন এবং অটোমান বাহিনীকে অত্যন্ত কঠিন অবস্থায় ফেললেন। তিন দিনের তীব্র রাস্তার সংঘর্ষে মামলুকরা শহরের বড় অংশ সাময়িকভাবে নিজেদের হাতে রাখল। প্রতিরোধ কেবল অটোমান কামান বাহিনী ও সাহায্যকারী বাহিনীর অংশগ্রহণে ভাঙা গেল।", "98838d21"]},
"OLAYLAR_EK5:1517-02-08:0":{"b": ["কানবিরদি গাজালির অটোমান সেবায় যোগদান", "a94ea459"], "d": ["রিদানিয়ার পর সালিহিয়ায় সরে যাওয়া প্রাক্তন মামলুক আমির কানবিরদি গাজালি সুলতানের কাছে আবেদন করে নিরাপত্তা চাইলেন। ইয়াভুজ সুলতান সেলিম মিসর ও সিরিয়ায় শৃঙ্খলা প্রতিষ্ঠায় উপকারী হবেন ভেবে তাঁকে নিজের সেবায় গ্রহণ করলেন। এই পছন্দ অটোমানদের মামলুক কর্মকর্তাদের উচ্ছেদ না করে ব্যবস্থায় অন্তর্ভুক্ত করার নীতির প্রথম বড় দৃষ্টান্ত।", "847c1e81"]},
"OLAYLAR_EK5:1517-02-15:0":{"b": ["ইয়াভুজ সুলতান সেলিমের কায়রোয় আনুষ্ঠানিক প্রবেশ এবং খুতবা পাঠ", "6d98080c"], "d": ["রাস্তার সংঘর্ষ দমনের পর সুলতান 15 ফেব্রুয়ারি 1517 সালে অত্যন্ত জাঁকজমকপূর্ণ অনুষ্ঠানে কায়রোয় প্রবেশ করলেন এবং মসজিদগুলোতে তাঁর নামে খুতবা পাঠ করা হলো। কায়রোয় অটোমান সুলতানের নামে খুতবা পাঠ 1250 সাল থেকে চলা মামলুক কর্তৃত্ব আইনত শেষ হওয়ার ঘোষণা। এই তারিখ মিসরের প্রকৃত বিজয়ের প্রতীকী সমাপ্তির মুহূর্ত গণ্য হয়।", "3f8589a3"]},
"OLAYLAR_EK5:1517-03-30:0":{"b": ["শেষ মামলুক সুলতান তুমানবের তাররুজে বন্দি হওয়া", "7058e6ad"], "d": ["কায়রো ত্যাগের পর নীল ব-দ্বীপে লুকিয়ে থাকা তুমানবে আশ্রয়দাতা বেদুইনদের দ্বারা ধরিয়ে দেওয়া হয়ে তাররুজ অঞ্চলে বন্দি হলেন। তাঁর বন্দিত্ব মামলুক প্রতিরোধের সংগঠিত কেন্দ্র মুছে দিল। শেষ সুলতান এর পর চৌদ্দ দিন অটোমান হাতে আটক থাকবেন।", "5fc98f13"]},
"OLAYLAR_EK5:1517-04-13:0":{"b": ["তুমানবের বাবুজ-জুওয়াইলায় মৃত্যুদণ্ড এবং মামলুক রাষ্ট্রের অবসান", "ad9820be"], "d": ["বন্দি হওয়ার চৌদ্দ দিন পর তুমানবে কায়রোর বিখ্যাত দরজা বাবুজ-জুওয়াইলায় ফাঁসিতে ঝোলানো হলো; মরদেহ পরে চাচার নির্মিত মাদ্রাসায় সমাহিত করা হলো। এভাবে 1250 সাল থেকে মিসর ও সিরিয়ায় শাসনকারী মামলুক রাষ্ট্র আনুষ্ঠানিকভাবে ইতিহাসে বিলীন হলো। প্রতিরোধ ভাঙার ফলে উচ্চ মিসরের (সাইদ) আসইউত ও আসওয়ানের মতো শহরগুলোও অটোমান শাসনের সঙ্গে যুক্ত হলো।", "96555946"]},
"OLAYLAR_EK5:1517-04-18:0":{"b": ["পর্তুগিজ নৌবহরের জেদ্দায় আক্রমণ এবং সালমান রাইসের প্রতিরক্ষা", "52322cf5"], "d": ["ত্রিশটির মতো গ্যালি ও গ্যালিয়নের পর্তুগিজ নৌবহর জেদ্দায় হামলা করল; সালমান রাইস শহরের প্রতিরক্ষা পরিচালনা করে শত্রুর স্থলে নামা ঠেকালেন এবং কয়েকটি পর্তুগিজ জাহাজ ডুবিয়ে দিলেন। এই প্রতিরক্ষা মক্কার বন্দর এবং ফলে হজের পথ খ্রিস্টান রাষ্ট্রের হাতে যাওয়া রোধ করল। জেদ্দা কয়েক মাস পর হিজাজের আনুগত্যের মাধ্যমে আনুষ্ঠানিকভাবে অটোমান শাসনের অন্তর্ভুক্ত হবে।", "a480f1f5"]},
"OLAYLAR_EK5:1517-05-19:0":{"b": ["নৌবহরের মাধ্যমে আলেকজান্দ্রিয়া হস্তগত — মিসর বিজয়ের সমাপ্তি", "386878fe"], "d": ["রিদানিয়ার ঠিক চার মাস পর, তুমানবের মৃত্যুদণ্ডের ছত্রিশ দিন পর, জাফর বের নেতৃত্বাধীন অটোমান নৌবহর বন্দরে পৌঁছালে আলেকজান্দ্রিয়া অটোমান শাসনে গেল; রশিদ ও দামিয়েত্তার মতো ব-দ্বীপের বন্দরগুলোও একই প্রক্রিয়ায় যুক্ত হলো। মিসরের ভূমধ্যসাগরে উন্মুক্ত এই বড় বন্দর কায়রোর পতনের কয়েক মাস পর এবং স্থলপথে নয়, সমুদ্রপথে হস্তগত হওয়া প্রমাণ করে যে বিজয় একটি যুদ্ধে নয়, অঞ্চলভেদে সম্পন্ন হয়েছিল। আলেকজান্দ্রিয়া এর পর ইস্তানবুল ও কায়রোকে যুক্ত করা প্রাণবন্ত বন্দরে পরিণত হবে। একই তারিখে যুক্ত হওয়া অন্যান্য স্থান: রশিদ (রোজেত্তা)।", "52187c14"]},
"OLAYLAR_EK5:1517-07-06:0":{"b": ["হিজাজের বিনা যুদ্ধে অন্তর্ভুক্তি: মক্কার শরিফের ছেলে আবু নুমাইয়ের আনুগত্য", "c13b98c7"], "d": ["ইয়াভুজ সুলতান সেলিম প্রথমে মক্কা ও আশপাশ দখলের জন্য সৈন্য পাঠানোর কথা ভেবেছিলেন, কিন্তু মক্কার আমির শরিফ বারাকাত আনুগত্য জানালে তা থেকে বিরত হলেন। বারাকাতের বারো বছর বয়সী ছেলে আবু নুমাই পিতার উপহার ও মক্কার চাবিসহ কায়রোয় এসে সুলতানের সামনে গৃহীত হলেন। এভাবে হিজাজ রিদানিয়ার স্বয়ংক্রিয় ফল হিসেবে নয়, সাড়ে পাঁচ মাস পর এবং একটি গুলিও না ছুড়ে, সন্ধি ও আনুগত্যের মাধ্যমে অটোমানদের সঙ্গে যুক্ত হলো। একই তারিখে যুক্ত হওয়া অন্যান্য স্থান: তায়েফ।", "636183e3"]},
"OLAYLAR_EK5:1517-07-12:0":{"b": ["খাদিমুল হারামাইন উপাধি গ্রহণ এবং মদিনায় খুতবা", "63b32b59"], "d": ["মক্কার প্রতিনিধিদলের দ্বিতীয় সাক্ষাতের পর ইয়াভুজ সুলতান সেলিম আনুষ্ঠানিকভাবে হারামাইনের সুরক্ষার দায়িত্ব নিলেন এবং 'খাদিমুল হারামাইনিশ-শরিফাইন' উপাধি ব্যবহার শুরু করলেন। শরিফ বারাকাত তাঁকে পাঠানো সম্মানসূচক পোশাক পরে সুলতানের নামে খুতবা পাঠ করালেন; মদিনার প্রতিনিধিদলও ইস্তানবুলে গেলে বারাকাতের আমিরত্ব বেরাত (ফরমান) দ্বারা অনুমোদিত হলো। সুলতান হারামাইনবাসীদের কাছে দুই লক্ষ স্বর্ণমুদ্রা ও প্রচুর রসদ পাঠিয়ে প্রতি বছর পুনরাবৃত্ত হবে এমন সুররা প্রথা শুরু করলেন। একই তারিখে যুক্ত হওয়া অন্যান্য স্থান: ইয়ানবু, তাবুক।", "3b3bfd8f"]},
"OLAYLAR_EK5:1517-08-28:0":{"b": ["সালমান রাইসের অটোমান সেবায় যোগদান এবং লোহিত সাগর নীতির হস্তান্তর", "771da99a"], "d": ["পর্তুগিজদের বিরুদ্ধে জেদ্দা রক্ষাকারী সালমান রাইস কায়রোয় এসে ইয়াভুজ সুলতান সেলিমের সামনে হাজির হলেন; কিছুকাল আটক থাকলেও 1519 সালে ইস্তানবুলে ডাকা হলেন এবং পর্তুগিজ হুমকির বিরুদ্ধে ত্রিশটির মতো গ্যালি ও কয়েকটি গ্যালিয়ন প্রস্তুত করার অঙ্গীকার করলেন। এই সাক্ষাৎ লোহিত সাগর ও ভারত মহাসাগর নীতি মামলুক উত্তরাধিকার থেকে নিয়ে সরাসরি ইস্তানবুলের সঙ্গে যুক্ত করার সূচনা। অটোমানরা এখন কেবল ভূমধ্যসাগরীয় রাষ্ট্র নয়, মহাসাগর নীতিও অনুসরণকারী শক্তি।", "c87580bd"]},
"OLAYLAR_EK5:1517-09-10:0":{"b": ["ইয়াভুজ সুলতান সেলিমের কায়রো ত্যাগ এবং হায়ির বের বেইলারবেইত্ব", "8cd4fb23"], "d": ["মিসরে প্রায় আট মাস থেকে প্রশাসনিক, আর্থিক ও সামরিক ব্যবস্থা গড়ে তোলা ইয়াভুজ সুলতান সেলিম কায়রো ত্যাগ করলেন; মার্জ দাবিকে বাম পার্শ্ব সরিয়ে নিয়ে মামলুক পরাজয় ত্বরান্বিত করা প্রাক্তন আলেপ্পোর নায়েব হায়ির বে মিসরের প্রথম অটোমান বেইলারবেই হিসেবে কালআতুল জাবাল থেকে প্রশাসন শুরু করলেন। মামলুক বংশোদ্ভূত একজন গভর্নর বাছাই নতুন প্রশাসন স্থানীয়দের কাছে অপরিচিত না ঠেকে তা নিশ্চিত করার সচেতন উত্তরণ নীতি ছিল। সুলতান ফেরার পথে সঙ্গে শেষ আব্বাসীয় খলিফা তৃতীয় মুতাওয়াক্কিল এবং মিসরের বিশিষ্ট শিল্পী ও আলিমদেরও ইস্তানবুলে নিয়ে গেলেন।", "c2b3bc7e"]},
"OLAYLAR_EK5:1517-09-11:0":{"b": ["কায়রো আব্বাসীয় খিলাফতের অবসান — 'হস্তান্তর অনুষ্ঠান' কাহিনি", "1d357640"], "d": ["ইয়াভুজ সুলতান সেলিম মিসর দখল করে মার্জ দাবিকে বন্দি হওয়া শেষ খলিফা তৃতীয় মুতাওয়াক্কিল আলাল্লাহকে সঙ্গে ইস্তানবুলে আনলেন; 1261 সাল থেকে মামলুক সুলতানদের ছায়ায় ক্ষমতাহীনভাবে চলে আসা কায়রো আব্বাসীয় খিলাফত এভাবে শেষ হলো। অন্যদিকে খিলাফত আয়াসোফিয়ায় আনুষ্ঠানিক অনুষ্ঠানে ইয়াভুজের কাছে হস্তান্তরিত হওয়ার বিখ্যাত কাহিনি প্রথম অষ্টাদশ শতাব্দীর শেষে দ'ওসনের রচনায় আসে এবং ইয়াভুজ যুগের কোনো সূত্রে নেই। TDV ইসলাম বিশ্বকোষ অনুষ্ঠান প্রমাণকারী মূল সূত্র না থাকায় কাহিনিটিকে বানোয়াট গণ্য করে; তবে খিলাফতের হস্তান্তরের জন্য শরিয়তের দিক থেকে এমন কোনো হস্তান্তর অনুষ্ঠানের প্রয়োজন ছিল না বলেও লিপিবদ্ধ করে।", "86efdf28"]},
"OLAYLAR_EK5:1518-01-01:0":{"b": ["এরজুরুম অটোমান শাসনে যুক্ত হলো — পূর্ব আনাতোলিয়ায় সাফাভি প্রভাব ভাঙল", "78d1be02"], "d": ["চালদিরান বিজয়ের (1514) পর অঞ্চলে অটোমান প্রভাব বাড়লেও এরজুরুমের পূর্ণ দখল ইরানি প্রভাব ভাঙা পর্যন্ত বিলম্বিত হলো; শহর কেবল মিসর অভিযানের পর 1518-19 সালে অটোমান শাসনে যুক্ত হলো। এরজুরুম 1502 সালে শাহ ইসমাইলের আক্কোয়ুনলু বেগলিকের অবসান ঘটানোয় সাফাভি কর্তৃত্বে এসেছিল; ষোলো বছরের এই যুগ এভাবে শেষ হলো। 1534 সালে ইরাকাইন অভিযানকালে এরজুরুম বেইলারবেইত্ব প্রতিষ্ঠিত হবে। 1518-1519 সালের মধ্যে এরজুরুম অঞ্চলের সঙ্গে আশকালেও অটোমান শাসনে যুক্ত হলো (দিন অনিশ্চিত)।", "41e2822f"]},
"OLAYLAR_EK5:1519-03-01:0":{"b": ["জালালি বিদ্রোহের সূচনা: বোজোকলু শেখ জালালের অভ্যুত্থান", "99bd8a99"], "d": ["বোজোক অঞ্চলে শেখ জালাল নামের এক ব্যক্তি নিজেকে মাহদি ঘোষণা করে তোকাত অঞ্চলে বিদ্রোহ করলেন; বিদ্রোহ দমন করা হলেও তাঁর নাম এক শতাব্দী ধরে আনাতোলিয়ার সব দস্যু ও বিদ্রোহ আন্দোলনের নাম হয়ে রইল। জালালিত্ব ষোড়শ শতাব্দীর শেষে তিমার ব্যবস্থার ভাঙন ও জনসংখ্যার চাপের সঙ্গে মিলে সাম্রাজ্যের সবচেয়ে দীর্ঘস্থায়ী অভ্যন্তরীণ নিরাপত্তা সমস্যায় পরিণত হলো। অভ্যুত্থানগুলো আনাতোলিয়ায় 'বড় পলায়ন' নামের ব্যাপক অভিবাসন ঘটাল।", "ec33f73b"]},
"OLAYLAR_EK5:1519-09-01:0":{"b": ["আলজিয়ার্সের অটোমান রাষ্ট্রের সঙ্গে সংযুক্তি", "b8eba4c1"], "d": ["উত্তর আফ্রিকায় স্পেনীয় চাপের বিরুদ্ধে প্রতিরোধ করা খাইরুদ্দিন রাইস টিকে থাকতে ইস্তানবুলে আবেদন করে আলজিয়ার্স সুলতানের কাছে নিবেদন করলেন এবং খুতবা ইয়াভুজ সুলতান সেলিমের নামে পাঠ করা হলো। এভাবে আলজিয়ার্স আনুষ্ঠানিকভাবে অটোমান ভূমিতে যুক্ত হলো, খাইরুদ্দিনকে বেইলারবেই উপাধিসহ সৈন্য ও কামান পাঠানো হলো। এই সংযুক্তি অটোমানদের পশ্চিম ভূমধ্যসাগরে শতাব্দীব্যাপী নৌ আধিপত্যের ভিত্তি স্থাপন করল। একই তারিখে যুক্ত হওয়া অন্যান্য স্থান: কনস্তান্তিন, শেরশেল (Cherchell), মেদেয়া (তিত্তেরি), সেতিফ।", "42dac5d2"]},
"OLAYLAR_EK5:1520-09-21:0":{"b": ["ইয়াভুজ সুলতান সেলিমের চোরলুতে মৃত্যু", "9fe83744"], "d": ["আট বছরে রাষ্ট্রের ভূমি দ্বিগুণেরও বেশি বাড়ানো প্রথম সেলিম 18 জুলাই 1520 সালে নতুন অভিযানের জন্য ইস্তানবুল থেকে বের হলেন; পিঠে দেখা দেওয়া একটি বড় টিউমারের কারণে চোরলুর বেশি এগোতে পারলেন না। চিকিৎসকদের হস্তক্ষেপ সত্ত্বেও রোগ বেড়ে গেল এবং দুই মাসের আশাহীন চিকিৎসার পর 8-9 শাওয়াল 926-এ (21-22 সেপ্টেম্বর 1520) এখানে মারা গেলেন। চালদিরান, মার্জ দাবিক ও রিদানিয়ার মাধ্যমে ইরানকে থামিয়ে মামলুক রাষ্ট্রের অবসান ঘটিয়েছিলেন, খিলাফত ও হারামাইনের অভিভাবকত্ব অটোমানদের এনে দিয়েছিলেন। তিনি একমাত্র পুত্রসন্তান রেখে গেলেন: সুলায়মান।", "39cccc63"]},
"OLAYLAR_EK5:1521-01-01:0":{"b": ["নিকারিয়া (ইকারিয়া) দ্বীপের অটোমান শাসনে প্রবেশ", "6afa972b"], "d": ["সামোস ও খিওসের মাঝের নিকারিয়া 1481 থেকে 1521 পর্যন্ত রোডসের সেন্ট জন নাইটদের শাসনে ছিল; দ্বীপে প্রথম অটোমান যুগ 1522 সালে শুরু হয়ে 1822 সাল পর্যন্ত চলল। এই সময়ে কর সংগ্রহ ও পরিশোধের দায়িত্বে ছিলেন কায়মাকাম; অন্য এজিয়ান দ্বীপগুলোর মতো স্থানীয় প্রবীণ পরিষদ (দেমোগেরোনতিয়া)-ও টিকে রইল এবং মাঝে মাঝে অটোমান প্রশাসনের সঙ্গে সংঘাতে জড়াল।", "7c6cc486"]},
"OLAYLAR_EK5:1522-01-01:0":{"b": ["দুলকাদির ভূমির সংযুক্তি — মারাশকেন্দ্রিক দুলকাদির প্রদেশ", "595c3c30"], "d": ["1515 সালের তুরনাদাগ পরাজয়ের পর অটোমানদের অনুগত বেগলিক হিসেবে চলা দুলকাদির ভূমি শেহসুয়ারওগলু আলি বে আর্তুকোভায় সন্তানসহ নিহত হওয়ার পর সরাসরি অটোমান ভূমিতে যুক্ত হলো এবং মারাশকে কেন্দ্র করে প্রদেশে পরিণত করা হলো। বেগলিকের বোজোক অঞ্চল আলাদা সানজাক হিসেবে অটোমান শাসনের সঙ্গে যুক্ত হলো। এভাবে মারাশ, এলবিস্তান, গোকসুন, গুরুন, জামান্তি ও দারেন্দের প্রায় দুই শতাব্দীর দুলকাদির যুগ শেষ হলো; মামলুক সীমান্তের বাফার বেগলিক সম্পূর্ণ বিলুপ্ত হলো।", "9b819db9"]},
"OLAYLAR_EK5:1522-05-29:0":{"b": ["কনিন বিজয়", "a46d3117"], "d": ["বসনিয়ার সানজাক বে গাজি হুসরেভ বের 927-928 (1521-1522) সালের আকিনজি অভিযানে কনিন, স্কারাদিন ও অস্ত্রোভিৎসাসহ একটি ভেনিসীয় দুর্গ-সারি অটোমান শাসনে গেল; সীমান্ত দ্বিতীয় পর্বতশ্রেণির ওপারে ঠেলে দেওয়া হলো। এই বিজয় শৃঙ্খল পনেরো বছর পর ক্লিস দখলে সম্পূর্ণ হওয়া দালমাটিয়া সানজাকের ভিত্তি স্থাপন করল।", "21f9fbd5"]},
"OLAYLAR_EK5:1523-01-05:0":{"b": ["নাইটদের সরে যাওয়া: বোদরুম, ইস্তানকোয় ও বারো দ্বীপপুঞ্জের হস্তান্তর", "ea01666e"], "d": ["রোডসের আত্মসমর্পণ শর্তে সেন্ট জন নাইটরা কেবল দ্বীপ কেন্দ্র নয়, দুই শতাব্দী ধরে ধরে রাখা সব অবস্থান খালি করল। আনাতোলিয়া উপকূলের বোদরুম (সেন্ট পিটার) দুর্গ এবং ইস্তানকোয়, কেলেমেজ ও ইলেরিয়োজ দ্বীপ এভাবে সংঘর্ষ ছাড়াই অটোমান শাসনে গেল। রোডসের পতনের দুই সপ্তাহ পর সম্পন্ন এই হস্তান্তরে এজিয়ানের দক্ষিণ-পূর্ব কোণে ল্যাটিন উপস্থিতি সম্পূর্ণ শেষ হলো।", "bcbe8fa8"]},
"OLAYLAR_EK5:1524-01-01:0":{"b": ["মিসরে বিশ্বাসঘাতক আহমেদ পাশার বিদ্রোহ", "b18bb805"], "d": ["সদরে আজম পদের অপেক্ষায় থেকে মিসরের গভর্নর হিসেবে পাঠানো আহমেদ পাশা কায়রোয় নিজেকে 'আল-মালিক আল-মানসুর সুলতান আহমেদ' ঘোষণা করে স্বাধীনতা জানালেন। বিদ্রোহ অল্প সময়ে দমন করা হলো এবং পাশা নিহত হলেন, তবে ঘটনা সাম্রাজ্যের সবচেয়ে ধনী প্রদেশে কেন্দ্রীয় নিয়ন্ত্রণের ভঙ্গুরতা দেখাল। এর ফলে ইব্রাহিম পাশা মিসরে গিয়ে প্রদেশের প্রশাসন পুনর্গঠনকারী বিখ্যাত মিসর কানুননামা প্রস্তুত করালেন।", "35eb542c"]},
"OLAYLAR_EK5:1528-01-01:0":{"b": ["উত্তর বসনিয়ার সংযুক্তি: ইয়ায়চে ও বানা লুকা", "8ec86cfa"], "d": ["মোহাচের পর হাঙ্গেরীয় প্রতিরক্ষা রেখা ভেঙে পড়লে বসনিয়ার সানজাক বে গাজি হুসরেভ বে ভ্রবাস উপত্যকার দিকে অগ্রসর হয়ে হাঙ্গেরীয় রাজ্যের হাতে থাকা শেষ বসনীয় দুর্গগুলো নিলেন। ইয়ায়চে ও বানা লুকার পতনে বসনিয়া প্রদেশ উত্তরে সাভা নদী পর্যন্ত পৌঁছাল এবং ক্রোয়েশিয়া ফ্রন্ট জন্ম নিল। বানা লুকা অল্প সময়ে প্রদেশের দ্বিতীয় কেন্দ্র হয়ে উঠল।", "1f634005"]},
"OLAYLAR_EK5:1529-09-08:0":{"b": ["বুদার দখল এবং জাপোলিয়াকে প্রদান", "fba4f89b"], "d": ["ভিয়েনা অভিযানের পথে অটোমান সেনাবাহিনী ফের্দিনান্দের হাতে গেছে এমন বুদা অবরোধ করে ফিরিয়ে নিল এবং শহর অটোমান আশ্রয়ে থাকা হাঙ্গেরীয় রাজা ইয়ানোশ জাপোলিয়াইয়ের হাতে সমর্পণ করল। এভাবে হাঙ্গেরির ওপর হাবসবুর্গ-অটোমান প্রতিদ্বন্দ্বিতায় বাফার অনুগত রাজ্যের একটি মডেল গড়ে উঠল। এই ব্যবস্থা 1541 সাল পর্যন্ত চলবে, জাপোলিয়ার মৃত্যুর পর বুদা সরাসরি অটোমান প্রদেশে পরিণত হবে।", "6777eb1d"]},
"OLAYLAR_EK5:1532-04-25:0":{"b": ["কানুনি জার্মান অভিযানে বের হলেন — পঞ্চম চার্লসকে চ্যালেঞ্জ", "7c3d7055"], "d": ["ভিয়েনা অবরোধ অমীমাংসিত থাকা এবং ফের্দিনান্দের বুদা পুনরায় অবরোধের পর সুলতান এবার সরাসরি সম্রাট পঞ্চম চার্লসকে খোলা যুদ্ধে টেনে আনতে ইস্তানবুল থেকে যাত্রা করলেন। সেনাবাহিনী আগস্টে ছোট গুন্স দুর্গের প্রতিরোধে আটকে থাকবে, সম্রাট যুদ্ধে না এলে অভিযান আকিনজি হামলায় সীমিত থাকবে। অভিযান পরের বছর হাবসবুর্গদের সঙ্গে প্রথম শান্তির ভিত্তি প্রস্তুত করল।", "c3e6e378"]},
"OLAYLAR_EK5:1532-08-05:0":{"b": ["জার্মান অভিযান এবং গুন্স (কোসেগ) অবরোধ", "8aec937a"], "d": ["কানুনি পঞ্চম চার্লসকে খোলা যুদ্ধে বাধ্য করার উদ্দেশ্যে সেনাবাহিনী নিয়ে অস্ট্রিয়ার ওপর অভিযান করলেন; ছোট গুন্স দুর্গ পঁচিশ দিন প্রতিরোধ করে সেনাবাহিনীর অগ্রগতি বিলম্বিত করল। সম্রাট যুদ্ধে না আসায় আকিনজিরা ভিয়েনার আশপাশে আঘাত হানল এবং ঋতু এগিয়ে যাওয়ায় ফেরা হলো। অভিযান ভূমি-লাভ আনল না, তবে হাবসবুর্গদের আলোচনার টেবিলে বসিয়ে পরের বছরের শান্তির ভিত্তি প্রস্তুত করল।", "792fc40e"]},
"OLAYLAR_EK5:1533-01-01:0":{"b": ["ইস্তানবুল চুক্তি — হাবসবুর্গদের সঙ্গে প্রথম শান্তি", "b085767a"], "d": ["ফের্দিনান্দের দূত কর্নেলিয়াসকে গ্রহণ করা সুলতান যুদ্ধবিরতিতে সম্মতি দিলেন এবং অটোমান ও অস্ট্রিয়ার মধ্যে প্রথম আনুষ্ঠানিক শান্তির পাঠ তৈরি হলো। চুক্তি অনুযায়ী ফের্দিনান্দ হাতে থাকা হাঙ্গেরীয় ভূমির জন্য বার্ষিক কর দিতে সম্মত হলেন, অস্ট্রিয়ার আর্চডিউক প্রটোকলে সদরে আজমের সমান গণ্য হলেন। এই অসম মর্যাদা ষোড়শ শতাব্দীতে অটোমান কূটনীতির শ্রেষ্ঠত্বের দাবির স্পষ্ট প্রকাশ ছিল।", "e51c434d"]},
"OLAYLAR_EK5:1534-06-01:0":{"b": ["কার্স দখল এবং উত্তর-পূর্ব সীমান্ত উন্মুক্ত", "742e3101"], "d": ["ইরাকাইন অভিযানের অগ্রবর্তী শাখা এরজুরুম থেকে পূর্বে অগ্রসর হওয়ার সময় জর্জীয় আতাবেগত্বের হাতে থাকা এবং তৈমুরের সময় থেকে ধ্বংসপ্রাপ্ত কার্স দুর্গ প্রতিরোধ ছাড়াই হস্তগত হলো। শহর আরাস বাঁক ও চিলদিরের মধ্যবর্তী গিরিপথ ধরে রাখায় ইরানে উন্মুক্ত উত্তর দ্বারের চাবি গণ্য হতো। এই লাভ ত্রিশ বছর পর গঠিত কার্স বেইলারবেইত্ব এবং ককেশাস রেখার প্রথম কড়া হলো।", "b3a27cc8"]},
"OLAYLAR_EK5:1534-07-13:0":{"b": ["তাবরিজে প্রথম প্রবেশ — ইরাকাইন অভিযানের সূচনা", "cf7ed4e3"], "d": ["সেরদার-ই একরেম হিসেবে আগে রওনা হওয়া ইব্রাহিম পাশা শাহ তাহমাস্প খোলা যুদ্ধ এড়িয়ে অভ্যন্তরে সরে যাওয়ায় সাফাভি রাজধানী তাবরিজে প্রতিরোধ ছাড়াই প্রবেশ করলেন। কানুনিও সেপ্টেম্বরে শহরে পৌঁছালেন; তবে শীত ঘনিয়ে আসা ও রসদ লাইন অত্যন্ত দীর্ঘ হওয়ায় সেনাবাহিনী বাগদাদের দিকে ঘুরল এবং তাবরিজ দীর্ঘকাল ধরে রাখা গেল না। চালদিরানের পর দ্বিতীয়বার দখল করা শহর অটোমানরা পূর্বে দখল সহজ, ধরে রাখা কঠিন তা শেখা স্থান হলো।", "a303a9e4"]},
"OLAYLAR_EK5:1534-09-22:0":{"b": ["বারবারোসার তিউনিস বিজয়", "d8754216"], "d": ["কাপুদান-ই দরিয়া বারবারোস খাইরুদ্দিন পাশা নৌবহর নিয়ে ইতালীয় উপকূলে আঘাত করার পর তিউনিসের দিকে অগ্রসর হয়ে হাফসি শাসক মওলাই হাসানকে পালাতে বাধ্য করে শহরে প্রবেশ করলেন। সিসিলি প্রণালী নিয়ন্ত্রণকারী অবস্থানের কারণে তিউনিস দখল পশ্চিম ভূমধ্যসাগরের শক্তিভারসাম্য মুহূর্তে অটোমানদের পক্ষে ঘুরিয়ে দিল। তবে এই আধিপত্য বেশি দিন স্থায়ী হবে না, পঞ্চম চার্লস পরের বছর বিশাল নৌবহর নিয়ে জবাব দেবেন।", "b0aeb30e"]},
"OLAYLAR_EK5:1535-07-21:0":{"b": ["তিউনিসের পঞ্চম চার্লসের কাছে হারানো", "a691f0f8"], "d": ["পঞ্চম চার্লস জেনোয়া ও পোপতন্ত্রের নৌবহর দ্বারা সমর্থিত বড় অভিযানে হালকুলওয়াদের পতন ঘটিয়ে তিউনিস দখল করলেন এবং মওলাই হাসানকে স্পেনীয় আশ্রয়ে সিংহাসনে ফিরিয়ে দিলেন। শহরে একটি স্পেনীয় গ্যারিসন বসিয়ে অটোমানদের মধ্য ভূমধ্যসাগরে অগ্রগতি সাময়িকভাবে থামিয়ে দেওয়া হলো। তিউনিসের চূড়ান্ত বিজয় কেবল চল্লিশ বছর পর, 1574 সালে সম্ভব হবে।", "cbb995cd"]},
"OLAYLAR_EK5:1536-01-01:0":{"b": ["গাজি হুসরেভ বের সাভা তীর অভিযান: বসনিয়া ব্রোদ ও ইয়াসেনোভাচ", "3740ec83"], "d": ["1528 সালে ইয়ায়চে ও বানা লুকা নেওয়ার পর সাভা নদী বরাবর দুর্গগুলো আরও কিছুকাল হাবসবুর্গ মুকুটের অধীন ক্রোয়েট-স্লাভোনীয় সীমান্তে ছিল। 1536 সালে তৃতীয়বার বসনিয়ার সানজাক বে হওয়া গাজি হুসরেভ বে একই বছর পোজেগা ও আশপাশ নেওয়ার সময় সাভা তীরের ব্রোদ ও ইয়াসেনোভাচ দুর্গও অটোমান শাসনে যুক্ত করলেন। এভাবে বসনিয়ার উত্তর সীমান্ত সাভায় পৌঁছাল; অঞ্চল দুই বছর পর দুবিৎসা দখলে সম্পূর্ণ হলো।", "415f0592"]},
"OLAYLAR_EK5:1536-03-15:0":{"b": ["মাকবুল ইব্রাহিম পাশার মৃত্যুদণ্ড", "348aa7b8"], "d": ["তেরো বছর সদরে আজম থাকা, কানুনির ঘনিষ্ঠতম বন্ধু এবং রাষ্ট্রের প্রকৃত দ্বিতীয় ব্যক্তি ইব্রাহিম পাশা ইফতারে আমন্ত্রিত প্রাসাদে কোনো কারণ না দেখিয়ে শ্বাসরোধে হত্যা করে মৃত্যুদণ্ড কার্যকর করা হলো। ইরাকাইন অভিযানে তাঁর অবস্থান, 'সেরাস্কার সুলতান' উপাধি ব্যবহার এবং প্রাসাদের অভ্যন্তরীণ ভারসাম্য তাঁর মৃত্যুতে প্রভাবক গণ্য হয়। মৃত্যুদণ্ড অটোমান কেন্দ্রীয় প্রশাসনে উজির-ই-আজমদের নিরঙ্কুশ নিরাপত্তা না থাকার প্রমাণকারী মোড়।", "a780f3de"]},
"OLAYLAR_EK5:1537-03-12:0":{"b": ["ক্লিস দুর্গ বিজয় এবং দালমাটিয়া সানজাকের প্রতিষ্ঠা", "6ffd4ebf"], "d": ["গাজি হুসরেভ বের কেথুদা ক্রোয়েট বংশোদ্ভূত নওমুসলিম মুরাদ বে স্প্লিটের ঠিক উত্তরের কৌশলগত ক্লিস দুর্গ ভেনিসের কাছ থেকে নিলেন। বিজয়ের ঠিক পরে ক্লিসকে আশপাশ অন্তর্ভুক্ত করা নতুন সানজাক ও কাজার কেন্দ্র করা হলো; এই সানজাকের সীমানা বহুলাংশে অটোমান ক্রোয়েশিয়ার কাঠামো এঁকে দিল। কনিন থেকে পনেরো বছর পর আসা এই বিজয় দালমাটিয়ার অভ্যন্তরের প্রশাসনিক কাঠামো সম্পূর্ণ করল।", "8338f8aa"]},
"OLAYLAR_EK5:1537-08-25:0":{"b": ["কর্ফু অবরোধ এবং ভেনিসের সঙ্গে যুদ্ধ", "11af95bd"], "d": ["পুলিয়া (আপুলিয়া) অভিযানের পর অটোমান সেনাবাহিনী কর্ফুতে সৈন্য নামাল এবং দ্বীপের শক্তিশালী ভেনিসীয় দুর্গ অবরোধ করল। দুর্গের খাড়া গঠন, ভারী ক্ষতি ও ঋতুর পরিস্থিতির কারণে 6 সেপ্টেম্বর অবরোধ তুলে পিছু হটা হলো। অবরোধ ব্যর্থ হলেও ভেনিসের সঙ্গে শুরু হওয়া যুদ্ধ এজিয়ান ও আদ্রিয়াটিকে বহু দ্বীপের অটোমানদের সঙ্গে যুক্ত হওয়া এবং পরের বছর প্রেভেজা বিজয়ে পরিণতি পেল।", "f023c2b9"]},
"OLAYLAR_EK5:1537-10-01:0":{"b": ["বারবারোসার এজিয়ান অভিযান: ভেনিসের সরাসরি শাসিত দ্বীপ দখল", "1b32ed96"], "d": ["কর্ফু অবরোধ থেকে ফেরা নৌবহর ভেনিসের বিরুদ্ধে যুদ্ধ ঘোষিত থাকার সুযোগে এজিয়ানে ডিউকত্বের নয়, সরাসরি ভেনিসের অধীন দ্বীপগুলো একে একে হস্তগত করল। এজিনা তীব্র প্রতিরোধের পর দখল হলো, কুয়েরিনি পরিবারের হাতে থাকা আস্তিপালিয়া এবং কার্পাথোস ও কাসোস আত্মসমর্পণ করল, মঠ-শাসিত পাতমোসও অটোমান আশ্রয় স্বীকার করল। নাক্সোস ডিউকত্ব অবশ্য করের অধীন করে জায়গায় রাখা হলো; এর সংযুক্তি 1566 সালের অপেক্ষায় ছিল।", "632f4747"]},
"OLAYLAR_EK5:1538-08-01:0":{"b": ["বারবারোসার উত্তর এজিয়ান অভিযান: স্কিরোস ও উত্তর স্পোরাডেস দখল", "20ab688e"], "d": ["প্রেভেজার পথে নৌবহর কনস্টান্টিনোপল বিজয়ের পর ভেনিসে আশ্রয় নেওয়া উত্তর এজিয়ান দ্বীপগুলো একে একে হস্তগত করল। ইউবোয়ার উত্তরের স্কিরোস এবং থেসালোনিকি উপসাগরের মুখ ধরে রাখা স্কিয়াথোস, স্কোপেলোস ও আলোনিসোস এভাবে অটোমান শাসনে এল। এই দ্বীপগুলো ইউবোয়া 1470 সালে নেওয়া হলেও আরও আটষট্টি বছর ভেনিসের হাতে থাকা শেষ উত্তর এজিয়ান ফাঁক পূরণ করল।", "2a9ea08f"]},
"OLAYLAR_EK5:1538-08-03:0":{"b": ["আদেন দখল এবং ইয়েমেন উপকূল সংযুক্তি", "e7d46d8f"], "d": ["ভারত অভিযানের জন্য সুয়েজ থেকে রওনা হওয়া নৌবহর লোহিত সাগর নিরাপদ না করে মহাসাগরে যাওয়া সম্ভব নয় বলে প্রথমে ইয়েমেন উপকূলের দিকে অগ্রসর হলো। হাদিম সুলায়মান পাশা 3 আগস্ট 1538 সালে আদেন বন্দরে প্রবেশ করলেন; পর্তুগিজদের দিকে ঝোঁকা তাহিরি শাসক আমির ইবনে দাউদকে জাহাজের দরজায় এনে মৃত্যুদণ্ড দেওয়া হলো এবং শহরে 500 জনের রক্ষী রেখে যাওয়া হলো। একই অভিযানে মোখা এবং প্রণালী নিয়ন্ত্রণকারী কামারান ও ফারাসান দ্বীপও হস্তগত হলো এবং ইয়েমেন বেইলারবেইত্বের ভিত্তি স্থাপিত হলো। এভাবে অটোমান রাষ্ট্র প্রথমবার বাব আল-মান্দাবের উত্তর উপকূলের সবটার মালিক হলো; সানা ও অভ্যন্তরীণ অঞ্চলকে আরও নয় বছর অপেক্ষা করতে হবে।", "495e1991"]},
"OLAYLAR_EK5:1538-09-01:0":{"b": ["মলদোভা অভিযান এবং বুজাক (বেন্দের) অঞ্চলের সংযুক্তি", "90a88a56"], "d": ["অটোমান দায়িত্ব পালন না করা মলদোভার ভয়েভোদা পেত্রু রারেশের বিরুদ্ধে অভিযানে সুচেভা দখল করা হলো, ইয়াশ শহর ক্রিমিয়ার খান সাহিব গিরাই লুট করলেন। সুলতান চেকির্গে স্তেফানকে ভয়েভোদা পদে বসালেন এবং বেন্দেরের সঙ্গে বুজাক (দক্ষিণ বেসারাবিয়া) অঞ্চল সরাসরি অটোমান ভূমিতে যুক্ত করলেন। এই সংযুক্তি কৃষ্ণ সাগরের উত্তর-পশ্চিম উপকূলকে অটোমান অভ্যন্তরীণ সাগরে পরিণত করা কড়াগুলোর একটি হলো। মলদোভা আগে থেকেই অটোমানদের অনুগত ভয়েভোদাত্ব ছিল; এই অভিযান ভূমি কোনো বিদেশি রাষ্ট্রের কাছ থেকে নেয়নি, কেবল বেন্দের ও বুজাকের অভ্যন্তরীণ প্রশাসন ভয়েভোদার কাছ থেকে নিয়ে সরাসরি সুলতানের সঙ্গে যুক্ত করেছিল; ভয়েভোদাত্বের বাকি অংশ অনুগত মর্যাদা বজায় রাখল। একই কাঠামো 1484 সালে কিলিয়া ও আক্কিরমানে, 1713 সালে খোতিনেও পুনরাবৃত্ত হবে: সীমান্ত দুর্গ সরাসরি, অভ্যন্তরীণ ভূমি অনুগত।", "96376de1"]},
"OLAYLAR_EK5:1540-11-01:0":{"b": ["আনাবোলু (নাফপ্লিও) চুক্তির মাধ্যমে হস্তান্তর", "104d0937"], "d": ["প্রেভেজার পর তিন বছর স্থায়ী ভেনিস যুদ্ধ প্রজাতন্ত্রের মোরিয়ায় শেষ দুটি দুর্গ ছেড়ে দিতে সম্মত হওয়ায় শেষ হলো। অবরোধে নেওয়া না যাওয়া আনাবোলু ও বেনেফশে তিন লক্ষ ডুকাট যুদ্ধক্ষতিপূরণের পাশাপাশি টেবিলে অটোমানদের হাতে ছাড়া হলো। মোরিয়া উপদ্বীপ এভাবে ভেনিসের একটিও পদচিহ্ন না রেখে অখণ্ড হলো।", "4a26ee03"]},
"OLAYLAR_EK5:1543-01-01:0":{"b": ["সেগেদের অটোমান শাসনে প্রবেশ এবং সেগেদ লিভার গঠন", "019aa000"], "d": ["বুদায় অটোমান শাসন 1541 সালে পূর্ণভাবে প্রতিষ্ঠার পর সেগেদের নেতারা প্রথম ফের্দিনান্দের কর্তৃত্ব গ্রহণ করে সশস্ত্র প্রতিরক্ষার জন্য প্রস্তুত হলেন। বুদার বেইলারবেই কুচুক বালি পাশা 1543 সালের শুরুতে শহরের শাসকদের ডেকে এনে বিশ্বাসঘাতকতার অভিযোগে মৃত্যুদণ্ড দিলেন, এর পর শহর দখলে বাহিনী পাঠালেন। এই সময়ে সেগেদ লিভা গঠিত হয়ে প্রথম সানজাক বে হিসেবে বালি পাশার ছেলে দারবিশ বে নিযুক্ত হলেন; লিভা শুরুতে দানিয়ুব-তিসার মধ্যে প্রসারিত ছিল।", "8293a839"]},
"OLAYLAR_EK5:1543-07-21:0":{"b": ["ভালপো, সিকলোশ ও পেচুই বিজয়", "2ca030a3"], "d": ["বুদা সংযুক্তির দুই বছর পর শুরু হওয়া হাঙ্গেরি অভিযানের প্রথম লক্ষ্য ছিল নতুন প্রদেশের দ্রাভা ও দানিয়ুবের মধ্যবর্তী দক্ষিণ পার্শ্ব নিরাপদ করা। ভালপো ও সিকলোশ দুর্গ নেওয়ার পর বারানিয়ার কেন্দ্র পেচুই আত্মসমর্পণ করল। শহর অটোমান হাঙ্গেরির সবচেয়ে জনবহুল ও সবচেয়ে উন্নত কেন্দ্র হয়ে উঠবে, ঐতিহাসিক ইব্রাহিম পেচুইলু নাম এখান থেকে নেবেন।", "aacf43d3"]},
"OLAYLAR_EK5:1543-08-10:0":{"b": ["এসতেরগন ও ইস্তলনি বেলগ্রেড (সেকেশফেহেরভার) বিজয়", "efca9e05"], "d": ["কানুনির নিজে যাওয়া হাঙ্গেরি অভিযানে আড়াই সপ্তাহের অবরোধের পর হাঙ্গেরীয় রাজ্যের ধর্মীয় কেন্দ্র ও আর্চবিশপ শহর এসতেরগন অটোমান শাসনে এল। এরপর হাঙ্গেরীয় রাজাদের অভিষেকের শহর ইস্তলনি বেলগ্রেডও নেওয়া হয়ে বুদা প্রদেশের প্রতিরক্ষা বলয় সম্পূর্ণ হলো। এসতেরগন 1595 সাল পর্যন্ত দানিয়ুব রেখার মূল দুর্গ হিসেবে অটোমান হাতে থাকবে।", "93577806"]},
"OLAYLAR_EK5:1544-09-01:0":{"b": ["বুদার উত্তর ও পশ্চিম প্রতিরক্ষা বলয়: ভাচ, হাটভান ও শিমনতোর্না", "733ee5ce"], "d": ["এসতেরগন ও ইস্তলনি বেলগ্রেড নেওয়ার পর বুদার বেইলারবেই রাজধানী ঘিরে দুর্গ-বলয় সম্পূর্ণ করতে সুলতানের অভিযান ছাড়াই অগ্রসর হলেন। দানিয়ুব বাঁকের ভাচ, আলফোল্ডের দরজা হাটভান এবং শিও রেখার শিমনতোর্না একে একে হস্তগত হলো। এই নীরব বছরের অর্জন বুদাকে সীমান্ত শহর থেকে একশো চল্লিশ বছর টিকে থাকা প্রদেশ কেন্দ্রে রূপান্তর করল।", "0ca98fa3"]},
"OLAYLAR_EK5:1545-12-26:0":{"b": ["বসরার সংযুক্তি এবং বসরা উপসাগরে প্রবেশ", "02f87c11"], "d": ["বাগদাদ বিজয়ের সময় (1534) বসরার শাসক রাশিদ ইবনে মাগামিস কানুনির আনুগত্য জানিয়েছিলেন, 1538 সালে শহরের চাবি পাঠিয়েছিলেন। স্থলাভিষিক্ত শেখ ইয়াহিয়া অটোমানদের বিরুদ্ধে অবস্থান নিলে বাগদাদের বেইলারবেই আয়াস পাশা স্থলপথে, মোসুলের সানজাক বে 120 জাহাজ নিয়ে ফুরাত হয়ে অগ্রসর হলেন; আয়াস পাশা 26 ডিসেম্বর 1545 সালে বসরায় প্রবেশ করলেন এবং শহর বেইলারবেইত্বের কেন্দ্র হলো। শাত আল-আরবের মুখের এই বন্দর পর্তুগালের হরমুজ থেকে নিয়ন্ত্রিত উপসাগরে অটোমানদের খোলা দরজা ছিল; 1555 সালের আমাসিয়া চুক্তিতে ইরানও এই অবস্থা স্বীকার করল।", "8905782c"]},
"OLAYLAR_EK5:1547-01-01:0":{"b": ["সানা ও ইয়েমেনের অভ্যন্তর বিজয়", "d31ded85"], "d": ["তাইজের পর সানাও নেওয়া হয়ে দেশের সবটা বেইলারবেইত্বের সঙ্গে যুক্ত হলো। তবে দুর্গম ভূগোল ও মাজহাবগত পার্থক্যের কারণে এই কর্তৃত্ব কখনো স্বস্তিদায়ক ছিল না; ইয়েমেন অটোমানদের জন্য ক্রমাগত সৈন্য গিলে ফেলা ফ্রন্টে পরিণত হলো।", "66968d6d"]},
"OLAYLAR_EK5:1547-02-01:0":{"b": ["তাইজ বিজয়", "d4509df9"], "d": ["নয় বছর আগে কেবল উপকূলীয় ফালিতে সন্তুষ্ট থাকা ইয়েমেনে জায়দি ইমামদের পার্বত্য অভ্যন্তরে ক্রমশ শক্তি বাড়ায় ওজদেমির পাশার বাহিনী উচ্চভূমিতে উঠে তাইজ দখল করল।", "46b811eb"]},
"OLAYLAR_EK5:1547-06-19:0":{"b": ["ইস্তানবুল চুক্তি — হাবসবুর্গদের সঙ্গে পাঁচ বছরের শান্তি", "41f81773"], "d": ["অটোমান ও হাবসবুর্গদের মধ্যে পাঁচ বছর মেয়াদি শান্তি স্বাক্ষরিত হলো; ফের্দিনান্দ হাতে থাকা হাঙ্গেরীয় ভূমির জন্য বার্ষিক 30.000 ডুকাট দিতে সম্মত হলেন। চুক্তি হাঙ্গেরির তিনভাগে বিভক্ত প্রকৃত অবস্থাকে আইনত নিবন্ধিত করল। পশ্চিম ফ্রন্ট এভাবে নিরাপদ হওয়ায় কানুনি ইরানের বিরুদ্ধে নতুন অভিযান সংগঠনের সুযোগ পেলেন।", "36cfadaa"]},
"OLAYLAR_EK5:1548-07-27:0":{"b": ["দ্বিতীয় ইরান অভিযান এবং তাবরিজের পুনর্দখল", "e82365df"], "d": ["শাহ তাহমাস্পের বিরুদ্ধে বিদ্রোহ করে ইস্তানবুলে আশ্রয় নেওয়া ভাই আলকাস মির্জার উৎসাহে বের হওয়া অভিযানে সেনাবাহিনী দ্বিতীয়বার তাবরিজে প্রবেশ করল। সাফাভিরা আবারও খোলা যুদ্ধে না গিয়ে ভূমি পুড়িয়ে সরে যাওয়ায় শহরে কেবল কয়েক সপ্তাহ থাকা গেল। অভিযান তাবরিজ ধরে রাখা যাবে না তা নিশ্চিত করল এবং অটোমান কৌশলকে স্থায়ী সীমান্ত রেখা গড়ার, অর্থাৎ ভান সুরক্ষিত করার দিকে ঘোরাল।", "bb2a7ceb"]},
"OLAYLAR_EK5:1548-08-24:0":{"b": ["ভান বিজয় এবং পূর্ব সীমান্ত স্থির", "fc8f930b"], "d": ["তাবরিজ থেকে ফেরার পথে অবরুদ্ধ ভান দুর্গ হ্রদের পূর্ব তীরের পাথুরে চূড়ায় উঁচু অবস্থানের কারণে অঞ্চলের প্রশ্নাতীত তালা ছিল এবং সংক্ষিপ্ত অবরোধের পর আত্মসমর্পণ করল। শহর সঙ্গে সঙ্গে বেইলারবেইত্বের কেন্দ্র করা হলো; এরচিশ, আদিলজেভাজ ও হাক্কারি সানজাক এর সঙ্গে যুক্ত করা হলো। তাবরিজের বিপরীতে ভান ধরে রাখা গেল এবং চারশো বছর অটোমানদের পূর্বে সবচেয়ে অগ্রবর্তী স্থায়ী অবস্থান হয়ে রইল।", "3ca861b4"]},
"OLAYLAR_EK5:1550-01-01:0":{"b": ["আল-হাসা ও কাতিফের সংযুক্তি — উপসাগরের আরব উপকূল", "f6701e60"], "d": ["বসরা দখলের পর উপসাগরের পশ্চিম তীরে পর্তুগালের অগ্রবর্তী চৌকি হয়ে ওঠা কাতিফ হস্তগত হলো এবং অভ্যন্তরের আল-হাসা মরূদ্যানসহ নতুন বেইলারবেইত্ব গঠিত হলো। বাহরাইন ও হরমুজের দিকে অভিযানের সূচনাস্থল ছিল এটি। অটোমান রাষ্ট্র এভাবে আরব উপদ্বীপের লোহিত সাগর ও বসরা উপসাগর উভয় উপকূলে একসঙ্গে কর্তৃত্বের অধিকারী হলো।", "240c0b43"]},
"OLAYLAR_EK5:1550-01-01:1":{"b": ["শেহরিজোরের হাতছাড়া — আর্দালান বে শুহরাব সাফাভিদের দিকে ঝুঁকল", "5600efc9"], "d": ["ইরাকাইন অভিযানের সময় (1535) অটোমান শাসন স্বীকার করা শেহরিজোর অঞ্চল জালম দুর্গে বসবাসকারী আর্দালান আমির বিগে বের শাসনাধীন ছিল। বিগে বের 1550 সালে মৃত্যুতে জালম দুর্গ দখল করে বেগলিকে কর্তৃত্ব নেওয়া ভাই শুহরাব সাফাভিদের দিকে ঝুঁকে অটোমান আনুগত্য ছাড়লেন; শেহরিজোর অঞ্চল এভাবে অটোমান প্রভাব থেকে বেরিয়ে গেল। অঞ্চল কেবল নাখচিভান অভিযানের সময়, 1554 সালে জালম দুর্গ অবরোধ করে নেওয়ার মাধ্যমে ফিরে পাওয়া গেল।", "62ddad8a"]},
"OLAYLAR_EK5:1551-01-01:0":{"b": ["আর্দাহান ও চিলদির অববাহিকা দখল", "14c9eb76"], "d": ["এরজুরুমের বেইলারবেই সাফাভিদের সঙ্গে চলা যুদ্ধের সময় জর্জীয় আতাবেগদের কুরা বাঁকের ভূমির দিকে অগ্রসর হয়ে আর্দাহান ও চিলদির আশপাশ অটোমান শাসনের সঙ্গে যুক্ত করলেন। কার্স-আর্দাহান রেখা এভাবে অখণ্ড হলো এবং উত্তর-পূর্বে জর্জিয়ায় উন্মুক্ত উচ্চভূমি নিয়ন্ত্রণে এল। অঞ্চলের চূড়ান্ত প্রশাসনিক ব্যবস্থা সাতাশ বছর পর গঠিত চিলদির প্রদেশে সম্পূর্ণ হবে।", "2f8d92cc"]},
"OLAYLAR_EK5:1551-09-07:0":{"b": ["সোকোল্লু মেহমেদ পাশা দানিয়ুব পার হলেন — ট্রান্সিলভানিয়া যুদ্ধের সূচনা", "38fde931"], "d": ["ট্রান্সিলভানিয়ার রাজা ছোট ইয়ানোশ জিগমন্ডের অভিভাবক সন্ন্যাসী মার্তিনুজ্জির সৃষ্ট বিশৃঙ্খলা এবং ট্রান্সিলভানিয়ার বানাতের দুর্গ ফের্দিনান্দের কাছে ছেড়ে দেওয়ায় নতুন অভিযান প্রয়োজনীয় গণ্য হলো; নেতৃত্ব রুমেলির বেইলারবেই সোকোল্লু মেহমেদ পাশাকে দেওয়া হলো। সেনাবাহিনী মার্তিনুজ্জির কালক্ষেপণ চেষ্টা সত্ত্বেও দানিয়ুব পার হলো, বেচে, বেচকেরেক, চানাদ ও লিপ্পা নিল; তবে তেমেশভার অবরোধ 16 নভেম্বর শীতের কারণে তুলে নেওয়া হলো। এভাবে হাঙ্গেরিতে নতুন অটোমান-হাবসবুর্গ যুদ্ধ শুরু হলো।", "85071c5e"]},
"OLAYLAR_EK5:1551-11-06:0":{"b": ["লিপভা (লিপ্পা) শহর কাস্তালদোর অস্ট্রীয় বাহিনীর হাতে গেল — দুর্গ 5 ডিসেম্বর আত্মসমর্পণ করল", "a0e1ff0d"], "d": ["সোকোল্লু মেহমেদ পাশার অক্টোবর 1551 সালে দখল করা লিপভাকে জেনারেল কাস্তালদোর বাহিনী 4 নভেম্বর অবরোধ করে; দুই দিন পর শহর অস্ট্রীয়দের হাতে যায়। উলামা পাশা 5.000 জনের রক্ষীদল নিয়ে আরও নয় দিন দুর্গ রক্ষা করেন এবং 5 ডিসেম্বর 1551 চুক্তির মাধ্যমে বেরিয়ে আসেন। 1552 সালে তেমেশভারের পতন পর্যন্ত লিপভা হাবসবুর্গের হাতে থাকে।", "22c85b1c"]},
"OLAYLAR_EK5:1552-07-27:0":{"b": ["তেমেশভার থেকে পাঠানো বাহিনীর দক্ষিণ বানাতের পালাঙ্কাগুলো ধরে রাখা — ভেরসেক, হারাম, কেভে", "edca0921"], "d": ["তেমেশভার অটোমান সেনাবাহিনীর কাছে আত্মসমর্পণের পর অবরোধ বাহিনী থেকে আলাদা হওয়া দলগুলো বানাতের ছোট পালাঙ্কাগুলোর দিকে অগ্রসর হলো; Bánlaky-র বর্ণনা অনুযায়ী Versec, Facset, Mehádia, Csákóvár, Haramvár ও Keve পালাঙ্কাগুলো এই বাহিনীর দ্বারা ধরা হলো। এভাবে দানিয়ুব তীরের হারামও অটোমানদের হাতে গেল।", "a5906d21"]},
"OLAYLAR_EK5:1552-09-04:0":{"b": ["সলনোক বিজয় এবং এগরি অবরোধের ব্যর্থতা", "a7156e8f"], "d": ["তেমেশভার দখলের পর মিলিত দুই অটোমান সেনাবাহিনী তিসার ওপর সলনোক ভাড়াটে রক্ষীদের দুর্গ ত্যাগ করায় প্রায় সংঘর্ষহীনভাবে হস্তগত করল। এর পর অবরুদ্ধ এগরি দুর্গ ইস্তভান দোবোর নেতৃত্বাধীন দুই হাজারের গ্যারিসনের আটত্রিশ দিনের প্রতিরোধের সামনে নেওয়া গেল না এবং শীত ঘনিয়ে এলে সেনাবাহিনী সরে গেল। একই অভিযানে একটি দুর্গ সহজে পড়া এবং অপরটি টিকে যাওয়া হাঙ্গেরিতে সীমান্ত আর অটোমানদের পক্ষে স্বয়ংক্রিয়ভাবে এগোয় না তার প্রথম স্পষ্ট ইঙ্গিত ছিল।", "354ed31f"]},
"OLAYLAR_EK5:1553-02-01:0":{"b": ["অটোমান-ফরাসি মৈত্রী — ফরাসি নৌবহরের অটোমান আদেশাধীন হওয়া", "a8e01b22"], "d": ["1 ফেব্রুয়ারি 1553 তারিখের চুক্তিতে ফ্রান্সের নৌবহর অটোমান নৌবহরের আদেশাধীন করা হলো; স্পেনের বিরুদ্ধে পশ্চিম ভূমধ্যসাগরে যৌথ অভিযান পরিকল্পিত হলো। চুক্তির পর তুরগুত রাইস 15 জুন 1553 সালে পঁয়তাল্লিশটি গ্যালি নিয়ে ফ্রান্সকে সমর্থন দিতে অভিযানে বের হলেন। এটি 1536 সালের ক্যাপিটুলেশনের বাণিজ্যিক ভিত্তিকে সামরিক সহযোগিতায় নিয়ে যাওয়া প্রথম আনুষ্ঠানিক মৈত্রী চুক্তি।", "bfa2fc2d"]},
"OLAYLAR_EK5:1553-10-05:0":{"b": ["শাহজাদা মুস্তাফার কোনিয়া এরেগলিতে মৃত্যুদণ্ড", "dec36858"], "d": ["নাখচিভান অভিযানের জন্য সমবেত সেনাবাহিনীতে যোগ দিতে পিতার তাঁবুতে প্রবেশ করা শাহজাদা মুস্তাফা সামনে হাজির হওয়ার সময় ঘাতকদের মুখোমুখি হলেন এবং শ্বাসরোধে নিহত হলেন। সেনাবাহিনীতে অত্যন্ত প্রিয় সিংহাসনের উত্তরাধিকারী প্রার্থীর হত্যা জ্যানিসারিদের মধ্যে গভীর ক্ষোভ সৃষ্টি করল, রুস্তেম পাশাকে সদরে আজমের পদ থেকে সরানো হলো। ঘটনা অটোমান শাহজাদা-রাজনীতির সবচেয়ে বিতর্কিত ভাঙনগুলোর একটি হিসেবে সাহিত্য ও লোকস্মৃতিতে স্থান পেল।", "ce2742ae"]},
"OLAYLAR_EK5:1555-01-01:0":{"b": ["ইব্রিম ও নুবিয়া সীমান্তের দক্ষিণে সরে যাওয়া", "c57d5d77"], "d": ["মিসর বেইলারবেইত্বের দক্ষিণ সীমান্ত নীল নদের ওপর পাথুরে অন্তরীপের চূড়ায় উঁচু ইব্রিম দুর্গ ওজদেমির বের হাতে সুরক্ষিত হয়ে এবং নিম্ন নুবিয়া অটোমান মিসরে পূর্ণভাবে যুক্ত হয়ে দ্বিতীয় জলপ্রপাতের ওপারে সরে গেল। (ইব্রিমে অটোমান প্রশাসনিক সংগঠন মিসর বিজয়ের পর গঠিত হয়েছিল; মানচিত্রে ইব্রিম 1517 থেকে অটোমান দেখানো হয়। এই বছর আনুমানিক, সূত্র বছর দেয় না।) দুর্গ নুবিয়া থেকে আসা হামলার বিরুদ্ধে বাঁধ ছিল এবং সেন্নারে যাওয়া স্বর্ণ ও দাসের পথের নিয়ন্ত্রণ বিন্দুও ছিল। এখানে বসানো বসনীয় রক্ষী বাহিনী এত স্থায়ী হলো যে তাদের বংশধররা তিন শতাব্দী পরও দুর্গে ছিল। সূত্রগুলো ইব্রিমের অটোমান শাসনে আসার সময় সম্পর্কে দুটি আলাদা বর্ণনা দেয়: TDV-র সুদান নিবন্ধ নিম্ন নুবিয়ার অটোমান মিসরের সঙ্গে যুক্ত হওয়া ষোড়শ শতাব্দীর মাঝামাঝি ওজদেমির পাশার অভিযানের সঙ্গে যুক্ত করে, অন্যদিকে নুবে নিবন্ধ হালফা উপত্যকা পর্যন্ত অঞ্চল ও ইব্রিমের প্রশাসনিক সংগঠন 1517 বিজয়ের ঠিক পরে গঠিত বলে লেখে। ইব্রিম সানজাক 26 জুলাই 1573 সালে হাবেশ প্রদেশের সঙ্গে যুক্ত হলো।", "cd2c7ae9"]},
"OLAYLAR_EK5:1555-09-27:0":{"b": ["বিজায়ার (বুজি) স্পেনীয়দের কাছ থেকে দখল", "49691cda"], "d": ["তেতাল্লিশ বছর ধরে স্পেনের হাতে থাকা এবং আলজিয়ার্স ও কনস্তান্তিনের মধ্যবর্তী উপকূলকে দুই ভাগ করা বিজায়া স্থল ও সমুদ্রপথে অবরোধের পর আত্মসমর্পণ করল। দুর্গের পতনে আলজিয়ার্স ওজাকের উপকূল ওরান পর্যন্ত অবিচ্ছিন্ন হলো। স্পেনে এই ক্ষতি এত বড় ক্ষোভ জাগাল যে দুর্গ সমর্পণকারী সেনাপতি আলোনসো দে পেরাল্তা নিজ দেশে মৃত্যুদণ্ডপ্রাপ্ত হলেন।", "a030d882"]},
"OLAYLAR_EK5:1559-01-01:0":{"b": ["জেইলার হাবেশ প্রদেশের সঙ্গে যুক্ত হওয়া", "7bbf369a"], "d": ["হাবেশ প্রদেশের দক্ষিণ প্রান্তে, আদেন উপসাগরের আফ্রিকা উপকূলের জেইলা বন্দর অটোমান শাসনের সঙ্গে যুক্ত হলো। আদাল সালতানাতের সমুদ্রে উন্মুক্ত দ্বার এই শহর বাব আল-মান্দাবের বাইরে যাওয়া জাহাজের জন্য শেষ রসদ বিন্দু ছিল। জেইলার যুক্ত হওয়ায় অটোমান রাষ্ট্রের আফ্রিকায় সীমান্ত সবচেয়ে দক্ষিণ বিন্দুতে পৌঁছাল।", "fe4597b7"]},
"OLAYLAR_EK5:1559-05-30:0":{"b": ["কোনিয়া শাহজাদাদের যুদ্ধ", "1c8de387"], "d": ["সিংহাসন-সংগ্রামে নামা শাহজাদা বায়েজিদ প্রায় 30.000 জনের বাহিনী নিয়ে কোনিয়ার সামনে এলেন এবং দুই দিনের সংঘর্ষে ভাই শাহজাদা সেলিমের কাছে পরাজিত হলেন। পরাজিত বায়েজিদ আমাসিয়া হয়ে ইরানে, শাহ তাহমাস্পের কাছে আশ্রয় নিলেন। যুদ্ধ কানুনির শেষ বছরগুলোতে সিংহাসনের উত্তরাধিকার সংকটকে পররাষ্ট্রনীতির সমস্যায় রূপান্তর করল।", "d466cfc5"]},
"OLAYLAR_EK5:1560-05-14:0":{"b": ["জেরবা নৌবিজয়", "c7b905c1"], "d": ["পিয়ালে পাশার নেতৃত্বাধীন অটোমান নৌবহর ত্রিপোলি পুনরুদ্ধারে সমবেত স্পেনীয়-জেনোয়া-মাল্টা মিত্র নৌবহরকে জেরবার সামনে দুই ভাগে বিভক্ত হওয়ার কৌশলে ছত্রভঙ্গ করল। মিত্ররা নৌবহরের বড় অংশ হারাল, দ্বীপের দুর্গও অল্প সময়ে পড়ল। জেরবা প্রেভেজার পর অটোমানদের ভূমধ্যসাগরে শ্রেষ্ঠত্ব পাকাপোক্ত করা দ্বিতীয় বড় নৌবিজয় গণ্য হয়।", "e987b794"]},
"OLAYLAR_EK5:1562-07-23:0":{"b": ["শাহজাদা বায়েজিদের কাজভিনে মৃত্যুদণ্ড", "a759de14"], "d": ["ইরানে আশ্রয় নেওয়া শাহজাদা বায়েজিদ দীর্ঘ দর কষাকষির পর শাহ তাহমাস্প কর্তৃক অটোমান প্রতিনিধিদলের কাছে সমর্পিত হলেন এবং চার ছেলেসহ শ্বাসরোধে হত্যা করা হলো। সমর্পণের বিনিময়ে সাফাভিরা উল্লেখযোগ্য আর্থিক ছাড় ও সীমান্ত নিশ্চয়তা পেল। এই মৃত্যুদণ্ডে দ্বিতীয় সেলিমের সিংহাসনারোহণের সামনের শেষ বাধা সরে গেল এবং আমাসিয়া চুক্তির শান্তি ব্যবস্থা রক্ষা পেল।", "cf625eb3"]},
"OLAYLAR_EK5:1566-04-14:0":{"b": ["খিওসের জেনোয়াবাসীদের কাছ থেকে দখল", "a4559b96"], "d": ["দুই শতাব্দী ধরে জেনোয়ার জুস্তিনিয়ানি পরিবারের বাণিজ্যিক উপনিবেশ হিসেবে শাসিত এবং অটোমানদের কর দেওয়া খিওস কর দিতে বিলম্ব এবং শত্রু জাহাজকে বন্দর দেওয়ার অজুহাতে পিয়ালে পাশা একটিও গুলি না ছুড়ে হস্তগত করলেন। খিওস ও ইপসারার সঙ্গে এজিয়ানের পূর্ব উপকূলের শেষ জেনোয়া উপস্থিতিও মুছে গেল। খিওসবাসীদের মাস্তিক উৎপাদন ও সুবিধা অক্ষুণ্ণ রেখে দ্বীপ সেজাইর-ই বাহর-ই সেফিদ প্রদেশের সঙ্গে যুক্ত করা হলো।", "a5ec4417"]},
"OLAYLAR_EK5:1566-04-15:0":{"b": ["নাক্সোস ডিউকত্বের সংযুক্তি — সমগ্র সাইক্লেডিস দ্বীপপুঞ্জ", "68f0ec0b"], "d": ["1207 সাল থেকে চলা এবং 1537 সাল থেকে অটোমানদের কর দেওয়া ল্যাটিন নাক্সোস ডিউকত্ব শেষ ডিউক জিয়াকোমো ক্রিস্পোর জনগণকে নিপীড়নের অভিযোগে আসা অভিযোগের অজুহাতে বিলুপ্ত হলো। নাক্সোস, পারোস, দেগিরমেনলিক, আন্দ্রোস, সিরোস, মাইকোনোস, ইওস, আনাফি ও আশপাশের সমগ্র সাইক্লেডিস দ্বীপপুঞ্জ একটি সিদ্ধান্তে সরাসরি অটোমান শাসনে নেওয়া হলো। কানুনি দ্বীপগুলোর শাসন কিছুকাল ইয়াসেফ নাসিকে দিলেন; সাড়ে তিন শতাব্দীর ল্যাটিন কর্তৃত্ব এভাবে এজিয়ানের মাঝখানে শেষ হলো।", "d4d7a143"]},
"OLAYLAR_EK5:1567-04-01:0":{"b": ["ইয়েমেন বিদ্রোহ এবং কোজা সিনান পাশার ইয়েমেন অভিযান", "c8218d8e"], "d": ["জায়েদি ইমাম মুতাহহার জোর করে কর আদায়ের অভিযোগে বিদ্রোহ করে ইয়েমেনের বড় অংশ থেকে অটোমান শাসন উৎখাত করলেন। ইস্তানবুল থেকে পাঠানো কোজা সিনান পাশা 1568-1570 সালের মধ্যে পরিচালিত অভিযানে কাওকাবান দীর্ঘ অবরোধের পর দখল করে অঞ্চলে অটোমান কর্তৃত্ব পুনঃপ্রতিষ্ঠা করলেন। অভিযান লোহিত সাগরের দক্ষিণ দ্বার ও ভারত মহাসাগর বাণিজ্যপথের নিয়ন্ত্রণ রক্ষার দিক থেকে অত্যাবশ্যক ছিল।", "d4771f85"]},
"OLAYLAR_EK5:1567-10-01:0":{"b": ["আচেহ সালতানাতের সঙ্গে প্রতিরক্ষা মৈত্রী এবং ভারত মহাসাগরে সাহায্য", "8e835f24"], "d": ["পর্তুগিজ আক্রমণের বিপরীতে কানুনির কাছে সাহায্য চাওয়া আচেহ দূতরা সুলতানের জিগেতভারে মৃত্যুর পর আনুগত্য দ্বিতীয় সেলিমের কাছে নিবেদন করলেন এবং তাঁর সঙ্গে প্রতিরক্ষা চুক্তি স্বাক্ষরিত হলো। সুলতান আলেকজান্দ্রিয়া থেকে কামান, বন্দুক, গোলাবারুদ ও কারিগর পাঠানোর আদেশ দিলেন; ভারত মহাসাগরে পাঠানোর জন্য সতেরোটি যুদ্ধজাহাজ প্রস্তুত করা হলো। ইয়েমেন বিদ্রোহ বড় হওয়ায় নৌবহরের যাত্রা আটকে গেল, তবে আচেহে পৌঁছানো অটোমান কামানবিদ ও কারিগররা অঞ্চলে স্থায়ী ছাপ রাখলেন।", "65c41562"]},
"OLAYLAR_EK5:1570-07-02:0":{"b": ["সাইপ্রাস অবতরণ: লিমাসল দখল", "9074ccc9"], "d": ["দ্বীপে নামা অটোমান সেনাবাহিনী বেশি প্রতিরোধের মুখোমুখি না হয়ে লিমাসল হস্তগত করল এবং পরদিন লার্নাকার দিকে অগ্রসর হলো। স্থানীয় জনগণের ভেনিসীয় শাসনে অসন্তুষ্ট হওয়া ও অটোমান বাহিনীকে সাহায্য করার সুবাদে লার্নাকায়ও গুরুতর প্রতিরোধ পাওয়া গেল না; তুজলা ঘাট সৈন্য ও সরঞ্জাম নামানোর ঘাঁটি করা হলো। ভেনিস প্রতিরক্ষা নিকোসিয়া ও ফামাগুস্তায় সংকুচিত করেছিল; পাফোসের গভর্নর কেবল নিকোসিয়া পড়ার পর সেরদারের প্রতি আনুগত্য জানালেন।", "6bbd2fee"]},
"OLAYLAR_EK5:1570-09-09:0":{"b": ["নিকোসিয়া বিজয়", "413d866b"], "d": ["25 জুলাই 1570 সালে শুরু হওয়া এবং পঁয়তাল্লিশ দিন স্থায়ী অবরোধের পর সাইপ্রাসের ভেনিসীয় শাসনাধীন রাজধানী নিকোসিয়া অটোমান সেনাবাহিনীর কাছে আত্মসমর্পণ করল। দ্বীপের কেন্দ্রের পতন ভেনিসীয় প্রতিরোধকে ফামাগুস্তা দুর্গে সংকুচিত করল। বিজয় পশ্চিমে বড় সাড়া জাগাল এবং পোপের নেতৃত্বে পবিত্র মৈত্রীর নৌবহর গঠনের প্রক্রিয়াকে ত্বরান্বিত করল।", "1ef832d4"]},
"OLAYLAR_EK5:1570-09-17:0":{"b": ["কিরেনিয়ার আত্মসমর্পণ — সাইপ্রাসের উত্তর উপকূল", "39fdeea5"], "d": ["নিকোসিয়ার 9 সেপ্টেম্বর তরবারির আঘাতে পতন সাইপ্রাসের উত্তরে প্রতিরোধ ভাঙল। পাঁচ আঙুল পর্বতের পেছনের কিরেনিয়া দুর্গ রাজধানীর পরিণতি জেনে আট দিন পর শর্তসাপেক্ষে আত্মসমর্পণ করল এবং গ্যারিসনকে দ্বীপ থেকে বের হতে দিয়ে পাঠানো হলো। দ্বীপে ভেনিসের পতাকা কেবল ফামাগুস্তায় রইল; তাও আরও এগারো মাস টিকবে।", "ecf762c9"]},
"OLAYLAR_EK5:1572-06-01:0":{"b": ["লেপান্তোর পর নৌবহরের পুনর্নির্মাণ", "db51fe44"], "d": ["লেপান্তোর বিপর্যয়ের পর কাপুদান-ই দরিয়া পদে আনা কিলিচ আলি পাশার প্রথম কাজ হলো ভারী ক্ষতিগ্রস্ত নৌবহর পুনর্নির্মাণ; নৌঘাঁটিগুলো 1571-1572 শীতজুড়ে অবিরাম কাজ করল। 1572 সালের জুনে প্রায় 250টি গ্যালি এবং 300টি স্বেচ্ছাসেবক রাইসের গ্যালি নিয়ে গঠিত নতুন বহর ভূমধ্যসাগরে বের হলো। এই দ্রুত পুনরুদ্ধার দেখাল যে লেপান্তো অটোমান নৌশক্তিকে স্থায়ীভাবে ভাঙতে পারেনি।", "324f2d99"]},
"OLAYLAR_EK5:1573-03-07:0":{"b": ["ভেনিসের সঙ্গে ইস্তানবুল চুক্তি — সাইপ্রাসের স্বীকৃতি", "4d08ef50"], "d": ["পবিত্র মৈত্রী ভেঙে যাওয়ায় একা পড়া ভেনিস অটোমানদের সঙ্গে আলাদা শান্তি করে সাইপ্রাস অটোমানদের বলে আনুষ্ঠানিকভাবে মেনে নিল এবং যুদ্ধক্ষতিপূরণ দিতে সম্মত হলো। চুক্তি স্পষ্ট করল যে লেপান্তো বিজয় খ্রিস্টান বিশ্বকে রাজনৈতিক লাভ দেয়নি। ভেনিস এর পর সত্তর বছর অটোমানদের সঙ্গে সরাসরি যুদ্ধে জড়ানো এড়াবে।", "de6151ba"]},
"OLAYLAR_EK5:1574-12-13:0":{"b": ["দ্বিতীয় সেলিমের মৃত্যু", "c289f5ee"], "d": ["দ্বিতীয় সেলিম পড়ে যাওয়ার পর প্রায় দুই মাস দিওয়ানে আসতে পারলেন না এবং মারা গেলেন। তাঁর মৃত্যু মানিসার বড় ছেলে মুরাদ ইস্তানবুলে আসা পর্যন্ত বারো দিন প্রাসাদে গোপন রাখা হলো। মৃত্যুর দিনে সূত্রগুলো ভিন্ন: সেলানিকি 15 ডিসেম্বর বলেন; গেরলাখ, মেহমেদ বিন মেহমেদ ও জেনাবি 13 ডিসেম্বর বলেন।", "e9e279ab"]},
"OLAYLAR_EK5:1574-12-22:0":{"b": ["দ্বিতীয় সেলিমের মৃত্যু ঘোষণা এবং তৃতীয় মুরাদের সিংহাসনারোহণ", "84334d70"], "d": ["দ্বিতীয় সেলিমের মৃত্যু এবং মানিসা থেকে আনা তৃতীয় মুরাদের সিংহাসনারোহণ 22 ডিসেম্বর 1574 সালে আনুষ্ঠানিকভাবে ঘোষিত হলো। নতুন সুলতান একুশ বছর সিংহাসনে থাকবেন, তাঁর রাজত্ব পূর্বে দীর্ঘ ইরান যুদ্ধ, পশ্চিমে দীর্ঘ যুদ্ধের প্রাক্কালে এবং অভ্যন্তরে মুদ্রার মান কমানোর জন্য স্মরণীয় হবে। সোকোল্লু মেহমেদ পাশার 1579 সালের মৃত্যু পর্যন্ত রাষ্ট্র পরিচালনায় পুরোনো ব্যবস্থা চলল।", "3e1ec091"]},
"OLAYLAR_EK5:1578-08-04:0":{"b": ["ওয়াদিস-সায়ল (আল-কাসর আল-কবির) যুদ্ধ — অটোমান সমর্থিত আবদুল মালিক পর্তুগিজ সেনাবাহিনী ধ্বংস করলেন", "21280dac"], "d": ["অটোমান সমর্থনে মরক্কোর সিংহাসনে বসা আবদুল মালিক পর্তুগালের রাজা সেবাস্তিয়ানের বিশাল সেনাবাহিনীকে ওয়াদিস-সায়লে ধ্বংস করলেন; যুদ্ধে তিন শাসক একসঙ্গে মারা যাওয়ায় পশ্চিমা সূত্রে 'তিন রাজার যুদ্ধ' নামে পরিচিত। পর্তুগালের সামরিক শক্তি ভেঙে পড়ল এবং দেশ অল্পকাল পরে স্পেনের হাতে গেল। আবদুল মালিকও যুদ্ধে মারা গেলেন; স্থলাভিষিক্ত ভাই আহমেদ আল-মানসুর বিজয় একটি প্রতিনিধিদলের মাধ্যমে ইস্তানবুলে জানালেন। দুই রাষ্ট্রের সম্পর্ক কর বা অধীনতা নয়, দূত ও উপহার বিনিময়ের স্তরে রইল এবং অল্পকাল পরে উপহার প্রশ্নে উত্তেজনাপূর্ণ হলো।", "0ddf3962"]},
"OLAYLAR_EK5:1578-10-05:0":{"b": ["দের্বেন্দের জনগণের লালা মুস্তাফা পাশার প্রতি আনুগত্য প্রকাশ — দেমিরকাপি অটোমান শাসনে", "9c55aeff"], "d": ["শিরভান অভিযানের সময় দের্বেন্দের জনগণের সাতজনের প্রতিনিধিদল এরেশে অবস্থানরত সেরদার লালা মুস্তাফা পাশার কাছে গিয়ে আনুগত্য নিবেদন করল। ককেশাস প্রাচীর ও কাস্পিয়ান সাগরের মাঝের সংকীর্ণ গিরিপথ বন্ধ করা দের্বেন্দ (দেমিরকাপি) উত্তর থেকে আসা স্থলপথের বাধ্যতামূলক গিরিপথ হিসেবে শিরভান ধরে রাখায় মূল ভূমিকা রাখল। অটোমান কর্তৃত্ব এখানে 1607 সাল পর্যন্ত চলল।", "9776382c"]},
"OLAYLAR_EK5:1578-11-01:0":{"b": ["শিরভান বিজয়: শামাখি দখল", "9afae4c1"], "d": ["চিলদির বিজয়ের পর ককেশাসে খোলা সেনাবাহিনী সাফাভিদের কাস্পিয়ান উপকূলের সবচেয়ে ধনী প্রদেশ শিরভানে প্রবেশ করে কেন্দ্র শহর শামাখি নিল। ওজদেমিরওগলু ওসমান পাশাকে এখানে বেইলারবেই নিযুক্ত করে রেশম পথের উত্তর শাখা অটোমান নিয়ন্ত্রণে আনা হলো। শিরভান বারো বছর স্থায়ী পূর্ব যুদ্ধের সবচেয়ে বেশি হাতবদল হওয়া এবং সবচেয়ে ব্যয়বহুল ফ্রন্ট হয়ে উঠবে।", "9955f6f2"]},
"OLAYLAR_EK5:1583-08-01:0":{"b": ["বাকু দখল — কাস্পিয়ান উপকূলে প্রবেশ", "eb5adab8"], "d": ["শিরভান অভিযানের শেষ কড়া হিসেবে কাস্পিয়ান সাগরের পশ্চিম উপকূলের বাকু বন্দর নেওয়া হলো। শহরের আশপাশের নেফত কূপ সেই সময়েও পরিচিত আয়ের উৎস ছিল এবং বন্দর কাস্পিয়ান হয়ে আসা ইরানি রেশমের নির্গমন বিন্দু ছিল। অটোমান রাষ্ট্র এভাবে ইতিহাসে প্রথম ও একমাত্রবার কাস্পিয়ান সাগরে উপকূলের মালিক হলো।", "ffafa858"]},
"OLAYLAR_EK5:1583-09-13:0":{"b": ["ইরেভান বিজয় এবং দুর্গ নির্মাণ", "7f623b7b"], "d": ["কার্সে ইরেভানে গিয়ে সেখানে দুর্গ নির্মাণের আদেশ পাওয়া ফারহাদ পাশা ইরেভানের দিকে অগ্রসর হলেন এবং শহর 991 রমজানের শুরুতে (সেপ্টেম্বর 1583-এর মাঝামাঝি) অটোমান নিয়ন্ত্রণে নেওয়া হলো। আরাস উপত্যকার উত্তর দ্বার ধরে রাখা ইরেভানে নতুন ও বড় দুর্গ নির্মিত হলো; শহর বেইলারবেইত্বের কেন্দ্র করা হলো। কার্স ও তাবরিজের মধ্যবর্তী সেনাপথের মাঝখানে দাঁড়ানো ইরেভান পূর্ব ফ্রন্টের রসদ মেরুদণ্ড ছিল। দুর্গ এত মজবুত নির্মিত হলো যে পরবর্তী দুই শতাব্দী অটোমান-ইরান যুদ্ধের অপরিবর্তনীয় লক্ষ্য হয়ে রইল।", "f6b3bd6e"]},
"OLAYLAR_EK5:1588-09-01:0":{"b": ["কারাবাখ ও গাঞ্জার সংযুক্তি", "29abaead"], "d": ["দশ বছরের পূর্ব যুদ্ধের শেষ লাভ হিসেবে ফারহাদ পাশা 1588 সালে গাঞ্জার দিকে অগ্রসর হয়ে 1 সেপ্টেম্বর শহরে প্রবেশ করলেন; কুরা ও আরাসের মধ্যবর্তী কারাবাখ অঞ্চল ও তার কেন্দ্র গাঞ্জা অটোমান শাসনে নেওয়া হলো। এভাবে শিরভান, ইরেভান ও কারাবাখ মিলে ককেশাসে অবিচ্ছিন্ন অটোমান রেখা গঠিত হলো। 1590 সালে স্বাক্ষরিত ফারহাদ পাশা চুক্তি এই সীমান্ত নিবন্ধিত করবে, তবে লাভ কেবল বিশ বছর ধরে রাখা যাবে।", "67f1d89d"]},
"OLAYLAR_EK5:1592-06-19:0":{"b": ["বিহাচ বিজয়", "651a7275"], "d": ["বসনিয়ার বেইলারবেই তেল্লি হাসান পাশা 1591 সালের নভেম্বরে বিহাচের সম্মুখ দুর্গ রিপাচ দখলের পর 1592 সালে শহর ও দুর্গও দখল করলেন; দশ দিনের অবরোধের পর সেনাপতি লামবের্গ আত্মসমর্পণ করলেন। এই বিজয় বসনিয়ার সীমান্ত উনা নদী বরাবর এগিয়ে দিল এবং এক বছর পর তেল্লি হাসান পাশার কুলপার সামনে শহিদ হওয়ায় শুরু হওয়া দীর্ঘ যুদ্ধের প্রাক্কালে শেষ বড় অটোমান লাভ হলো।", "b6814991"]},
"OLAYLAR_EK5:1593-07-01:0":{"b": ["অটোমান-অস্ট্রিয়া 'দীর্ঘ যুদ্ধের' সূচনা", "bd22c392"], "d": ["বসনিয়ার বেইলারবেই তেল্লি হাসান পাশা কুলপার (সিসাক) সামনে পরাজিত হয়ে শহিদ হওয়ায় অটোমান রাষ্ট্র অস্ট্রিয়ার বিরুদ্ধে যুদ্ধ ঘোষণা করল এবং তেরো বছর স্থায়ী দীর্ঘ যুদ্ধ শুরু হলো। আগ্নেয়াস্ত্রধারী পদাতিক নির্ধারক হওয়া এই যুদ্ধ অটোমান সেনা ব্যবস্থায় সেকবান ও বন্দুকধারী সৈন্য নিয়োগ ত্বরান্বিত করল, তিমারধারী সিপাহির পতন গভীর করল। যুদ্ধ 1606 সালে জিতভাতোরোক চুক্তিতে শেষ হবে।", "f309a27f"]},
"OLAYLAR_EK5:1593-07-19:0":{"b": ["কোজা সিনান পাশা অস্ট্রিয়া অভিযানে বের হলেন — দীর্ঘ যুদ্ধের প্রথম অভিযান", "d4a2f46d"], "d": ["বসনিয়ার বেইলারবেই হাসান পাশা সিসকার (সিসাক) সামনে পরাজিত হয়ে শহিদ হওয়ার পর সদরে আজম কোজা সিনান পাশা চমকপ্রদ কথা ও প্রতিশ্রুতিতে সুলতানকে যুদ্ধে সম্মত করলেন এবং 12.000 জ্যানিসারি ও অন্যান্য বাহিনী নিয়ে যাত্রা করলেন। এভাবে তেরো বছর স্থায়ী অটোমান-অস্ট্রিয়া যুদ্ধের প্রথম অভিযান শুরু হলো।", "0f217276"]},
"OLAYLAR_EK5:1594-09-27:0":{"b": ["ইয়ানিককালে (জিওর) বিজয়", "14b75207"], "d": ["সদরে আজম কোজা সিনান পাশা এক মাসের বেশি অবরোধের পর ভিয়েনার পথের তালা গণ্য ইয়ানিককালে হস্তগত করলেন। দুর্গের পতন ইউরোপে বড় আতঙ্ক সৃষ্টি করল এবং দীর্ঘ যুদ্ধে অটোমানদের সবচেয়ে উজ্জ্বল লাভ হলো। তবে দুর্গ কেবল চার বছর ধরে রাখা যাবে।", "a634af40"]},
"OLAYLAR_EK5:1595-01-17:0":{"b": ["তৃতীয় মুরাদের মৃত্যু", "1b62e886"], "d": ["একুশ বছরের রাজত্বের পর ওয়ালাচিয়া সেনাবাহিনী ইবরাইল পুড়িয়ে সিলিস্ত্রা পর্যন্ত পৌঁছানোর দিনগুলোতে তৃতীয় মুরাদ মারা গেলেন এবং আয়াসোফিয়ার সমাধিস্থলে সমাহিত হলেন। মানিসা থেকে ডাকা ছেলে তৃতীয় মেহমেদ দশ দিন পর ইস্তানবুলে পৌঁছে সিংহাসনে বসলেন (27 জানুয়ারি 1595)।", "1deabc61"]},
"OLAYLAR_EK5:1595-09-02:0":{"b": ["এসতেরগনের অস্ট্রিয়ার কাছে হারানো", "f420d333"], "d": ["কার্ল ফন মান্সফেল্ডের পরিচালিত অবরোধে পর্যাপ্ত সাহায্য না পাওয়া এসতেরগনের রক্ষীরা দুর্গ আর্চডিউক ম্যাথিয়াসের কাছে সমর্পণ করল। বাহান্ন বছরের অটোমান কর্তৃত্বের অবসানে দানিয়ুব রেখার প্রতিরক্ষা শৃঙ্খল ভাঙল এবং বুদা সরাসরি হুমকির মুখে পড়ল। দুর্গ কেবল দশ বছর পর, 1605 সালে ফিরিয়ে নেওয়া যাবে।", "7617d6f2"]},
"OLAYLAR_EK5:1596-10-12:0":{"b": ["এগরি দুর্গ বিজয়", "3e511629"], "d": ["তিন সপ্তাহ স্থায়ী লড়াইয়ের পর অটোমানরা আগে কোনোভাবেই দখল করতে না পারা শক্তিশালী এগরি দুর্গ রক্ষীদের আত্মসমর্পণে পড়ল। সুলতানের নিজে উপস্থিত থাকা এই বিজয় হারানো এসতেরগনের সৃষ্ট মনোবল কিছুটা মেরামত করল এবং এগরি প্রদেশ গঠিত হলো। দুই সপ্তাহ পর অর্জিত মেজোকেরেসতেস বিজয়ের সঙ্গে 1596 দীর্ঘ যুদ্ধের সবচেয়ে সফল অটোমান বছর হলো।", "5dc53fa9"]},
"OLAYLAR_EK5:1598-03-29:0":{"b": ["ইয়ানিককালের (জিওর) হারানো", "b4ccc679"], "d": ["মিক্লোস পালফি ও আডলফ ফন শোয়ার্জেনবের্গের নেতৃত্বাধীন বাহিনী আকস্মিক হামলায় দুর্গের দরজা উড়িয়ে ইয়ানিককালে ফিরিয়ে নিল। চার বছর আগে কোজা সিনান পাশার বড় পরিশ্রমে অর্জিত দুর্গ হারানো অটোমানদের হাঙ্গেরিতে অগ্রবর্তী রেখা ভেঙে দিল। একই বছর বুদা অবরোধকারী শত্রুবাহিনী প্রতিহত হলেও যুদ্ধের ভারসাম্য ক্রমে ক্ষয়ের যুদ্ধে পরিণত হলো।", "80bf88e0"]},
"OLAYLAR_EK5:1599-01-01:0":{"b": ["কারাইয়াজিজি আবদুলহালিমের বিদ্রোহ", "30493b0d"], "d": ["দীর্ঘ যুদ্ধে সেনাবাহিনী থেকে পালানো সেকবান ও লেভেন্দদের সংগঠিত করা কারাইয়াজিজি আবদুলহালিম মধ্য আনাতোলিয়ায় বিস্তৃত অঞ্চল নিয়ন্ত্রণে নিলেন, উরফা দুর্গ দখল করলেন (নভেম্বর 1599) এবং 'হালিম শাহ' উপাধিতে সুলতানত্ব ঘোষণা করে নিজের তুঘরা বহনকারী ফরমান পাঠালেন। বড় জালালি ঢেউয়ের প্রথম নেতা গণ্য কারাইয়াজিজি 1602 সালে মারা গেলেন, তাঁর আন্দোলন ভাই দেলি হাসান চালিয়ে গেলেন। বিদ্রোহ আনাতোলিয়ার কৃষকদের গণহারে ভূমি ত্যাগ করার 'বড় পলায়ন' যুগের সূচনা।", "ceda9161"]},
"OLAYLAR_EK5:1601-09-10:0":{"b": ["তিরিয়াকি হাসান পাশার কানিজসা প্রতিরক্ষা", "d56a5e6a"], "d": ["এক বছর আগে বিজিত কানিজসা ফিরিয়ে নিতে চাওয়া আর্চডিউক ফের্দিনান্দ ও তাঁর মিত্ররা দুর্গ দুই মাসের বেশি অবরোধ করল; তিরিয়াকি হাসান পাশা 9000 জনের বাহিনী নিয়ে প্রতিরোধ করলেন। বাইরের সাহায্য না পেলেও সাধারণ আক্রমণগুলো প্রতিহত করলেন এবং বেরিয়ে আক্রমণের মাধ্যমে শত্রুকে ভারী ক্ষতি করে পিছু হটতে বাধ্য করলেন। এই প্রতিরক্ষা অটোমান ইতিহাসলেখায় মহাকাব্যে পরিণত হয়েছে এবং 'কানিজসা অবরোধ' স্বতন্ত্র সাহিত্যধারায় রূপ নিয়েছে।", "edc6d7b6"]},
"OLAYLAR_EK5:1603-12-20:0":{"b": ["তৃতীয় মেহমেদের মৃত্যু এবং প্রথম আহমেদের সিংহাসনারোহণ", "da735fde"], "d": ["তৃতীয় মেহমেদের 20 ডিসেম্বর মৃত্যুতে চোদ্দ বছর বয়সী ছেলে প্রথম আহমেদ সিংহাসনে বসলেন। শিশু বয়সে এবং সানজাকে না গিয়ে সিংহাসনে বসা প্রথম সুলতান হওয়া শাহজাদাদের প্রদেশে লালন-পালনের রীতি কার্যত শেষ হওয়ার ইঙ্গিত দেয়। প্রথম আহমেদের রাজত্বে ভাইহত্যা ত্যাগ করে 'আকবরিয়াত' (সবচেয়ে বয়স্ক পুরুষ সদস্যের সিংহাসন পাওয়া) নীতিতে যাওয়া হবে।", "a5f7151a"]},
"OLAYLAR_EK5:1605-10-03:0":{"b": ["এসতেরগনের পুনরুদ্ধার", "7330f273"], "d": ["সদরে আজম লালা মেহমেদ পাশা দশ বছর আগে হারানো এসতেরগন অবরোধ করে আবার অটোমান শাসনে যুক্ত করলেন। একই অভিযানে পেশত ও ভাচও উদ্ধার হলো, অটোমানরা হাঙ্গেরিতে তাদের রেখা গুছিয়ে নিল। এই সাফল্য পরের বছর জিতভাতোরোকে তুলনামূলক শক্ত অবস্থানে টেবিলে বসা নিশ্চিত করল; এসতেরগন 1683 সাল পর্যন্ত অটোমান হাতে থাকবে।", "242d3547"]},
"OLAYLAR_EK5:1607-10-24:0":{"b": ["ওরুচ সমভূমির বিজয় এবং জানবোলাতওগলুর বিদ্রোহ দমন", "30f93532"], "d": ["আলেপ্পোয় স্বাধীন বেগলিক গড়ে তোস্কানার সঙ্গে মৈত্রী খুঁজতে নামা জানবোলাতওগলু আলি পাশা সদরে আজম কুয়ুজু মুরাদ পাশা কর্তৃক ওরুচ সমভূমিতে ভারী পরাজয়ে পড়লেন। সিরিয়ায় কেন্দ্রীয় কর্তৃত্ব পুনঃপ্রতিষ্ঠার ফলে জালালি ঢেউয়ের সবচেয়ে বিপজ্জনক শাখা ভাঙল। কুয়ুজু মুরাদ পাশার দুই বছর স্থায়ী নির্মম শুদ্ধি আনাতোলিয়ায় সাময়িকভাবে হলেও শান্তি আনল।", "6e620c57"]},
"OLAYLAR_EK5:1608-08-09:0":{"b": ["আলাচায়ির বিজয় এবং কালেন্দেরওগলুর বিদ্রোহ দমন", "55db0485"], "d": ["মানিসা ও বুরসা অঞ্চল থেকে চাঁদা আদায় করা জালালি নেতা কালেন্দেরওগলু কুয়ুজু মুরাদ পাশা কর্তৃক আলাচায়িরে পরাজিত হলেন এবং ইরানে পালাতে বাধ্য হলেন। এই বিজয়ে আনাতোলিয়ার বড় জালালি বাহিনীগুলোর শেষটি ছত্রভঙ্গ হলো। কুয়ুজু মুরাদ পাশার, নিহত বিদ্রোহীদের খোঁড়ানো কূপে ভরে দেওয়ার কাহিনি প্রচলিত কঠোর শুদ্ধি স্বল্পমেয়াদে শৃঙ্খলা আনলেও আনাতোলিয়ার জনসংখ্যা ও উৎপাদনের ক্ষতি পূরণ করতে পারল না।", "dc332b4b"]},
"OLAYLAR_EK5:1612-07-06:0":{"b": ["নেদারল্যান্ডসকে প্রথম আহদনামা প্রদান", "5d9d117e"], "d": ["ডাচ সংযুক্ত প্রজাতন্ত্রের দূত কর্নেলিস হাগা প্রথম আহমেদের কাছ থেকে ফ্রান্স ও ইংল্যান্ডকে দেওয়া আহদনামার একই পরিধির আহদনামা পেতে সফল হলেন। নেদারল্যান্ডস এভাবে ইস্তানবুলে দূতাবাস, অটোমান বন্দরে কনসুলেট খোলা এবং নিজ পতাকায় বাণিজ্যের অধিকার অর্জন করল। এই আহদনামা ভূমধ্যসাগরীয় বাণিজ্যে ভেনিসের স্থান নেওয়া উত্তরের নৌশক্তিগুলোর অটোমান বাজারে প্রবেশের প্রতীক।", "7991027b"]},
"OLAYLAR_EK5:1617-11-22:0":{"b": ["প্রথম আহমেদের মৃত্যু এবং প্রথম মুস্তাফার সিংহাসনারোহণ — আকবরিয়াত নীতি", "9901c09e"], "d": ["একান্ন দিন স্থায়ী পাকস্থলীর রোগের পর আঠাশ বছর বয়সী প্রথম আহমেদ মারা গেলেন এবং ছেলের জায়গায় ভাই প্রথম মুস্তাফাকে সিংহাসনে বসানো হলো। এভাবে পিতা থেকে পুত্রে উত্তরাধিকারের রীতি ত্যাগ করে রাজবংশের সবচেয়ে বয়স্ক পুরুষ সদস্যের সিংহাসনে বসার 'আকবরিয়াত' ব্যবস্থায় কার্যত যাওয়া হলো। ছিয়ানব্বই দিন স্থায়ী এই প্রথম রাজত্ব শাহজাদাদের 'কাফেসে' বেড়ে ওঠার যুগেরও সূচনা।", "1f866a67"]},
"OLAYLAR_EK5:1618-02-26:0":{"b": ["প্রথম মুস্তাফার অপসারণ এবং তরুণ ওসমানের (দ্বিতীয় ওসমান) সিংহাসনারোহণ", "e0f552f2"], "d": ["মানসিক স্বাস্থ্য ঠিক নেই এই কারণে প্রথম মুস্তাফা ছিয়ানব্বই দিন পর সিংহাসনচ্যুত হলেন এবং প্রথম আহমেদের চোদ্দ বছর বয়সী ছেলে দ্বিতীয় ওসমান সুলতান হলেন। হাসানবেইজাদের ওপর ভিত্তি করা বর্ণনা অনুযায়ী এই অপসারণ সিদ্ধান্তে কিজলার আগাসি মুস্তাফা আগা প্রভাবশালী ছিলেন। তরুণ ওসমান জ্যানিসারি বাহিনী বিলুপ্ত করে নতুন সেনাবাহিনী গড়ার পরিকল্পনা নিয়ে অটোমান সংস্কার বিতর্কের প্রথম র‍্যাডিক্যাল নাম গণ্য হন। এই পরিকল্পনা চার বছর পর তাঁর প্রাণ নেবে।", "4d655aca"]},
"OLAYLAR_EK5:1618-09-26:0":{"b": ["সেরাভ চুক্তি — ইরানের সঙ্গে শান্তি নবায়ন", "e778aca8"], "d": ["পুলি শিকেস্তে পরাজয়ের পর ইরানের সঙ্গে হওয়া সেরাভ চুক্তি 1612 সালের নাসুহ পাশা চুক্তির শর্ত বহুলাংশে নিশ্চিত করল; সাফাভিদের পাঠানো বার্ষিক রেশমের পরিমাণ দুই শত বোঝা থেকে একশো বোঝায় কমানো হলো। এভাবে 1603 সাল থেকে চলা পূর্ব যুদ্ধের দ্বিতীয় পর্ব শেষ হলো। শান্তি দীর্ঘস্থায়ী হবে না, 1623 সালে বাগদাদ হাতছাড়া হওয়ায় যুদ্ধ আবার জ্বলে উঠবে।", "f14d72aa"]},
"OLAYLAR_EK5:1621-10-09:0":{"b": ["খোতিন অভিযান ও খোতিন চুক্তি", "bc4c823c"], "d": ["দ্বিতীয় ওসমানের নিজে নেতৃত্বদানকারী বিশাল সেনাবাহিনীর বিরুদ্ধে খোদকিয়েভিচের খোতিনের সামনে গড়া সুরক্ষিত শিবির অতিক্রম করা গেল না এবং কয়েক মাস স্থায়ী আক্রমণের পরও ফল মিলল না। 9 অক্টোবর স্বাক্ষরিত চুক্তিতে দনিস্টার নদীকে সীমান্ত মানা হলো, পোলরা কসাক হামলা রোধের অঙ্গীকার করল। বিজয় হিসেবে উপস্থাপিত হলেও ফল দিতে না পারা অভিযান তরুণ সুলতানের জ্যানিসারিদের প্রতি অবিশ্বাস এবং বাহিনী শুদ্ধির অভিপ্রায় আরও দৃঢ় করল।", "7d812c58"]},
"OLAYLAR_EK5:1622-04-23:0":{"b": ["হরমুজ পর্তুগিজদের কাছ থেকে দখল", "93e5f6cf"], "d": ["সাফাভি বাহিনী 1515 সাল থেকে পর্তুগিজ হাতে থাকা হরমুজ অবরোধ করে পুনরুদ্ধার করে; কেশম ও উপকূলের গামরুন (বন্দর আব্বাস)ও সাফাভি শাসনে যায় এবং উপসাগরীয় বাণিজ্য নতুন বন্দরে সরে যায়।", "cc55e4bf"]},
"OLAYLAR_EK5:1623-09-10:0":{"b": ["প্রথম মুস্তাফার দ্বিতীয় অপসারণ এবং চতুর্থ মুরাদের সিংহাসনারোহণ", "1b3a9e74"], "d": ["দ্বিতীয় ওসমানের হত্যার পর দ্বিতীয়বার সিংহাসনে বসানো প্রথম মুস্তাফা এক বছর তিন মাস পর আবার অপসারিত হলেন এবং এগারো বছর বয়সী চতুর্থ মুরাদ সুলতান ঘোষিত হলেন। প্রথম নয় বছর রাষ্ট্র কার্যত মা কোসেম সুলতান ও প্রাসাদের গণ্যমান্যদের দ্বারা পরিচালিত হলো। চতুর্থ মুরাদ 1632 সাল থেকে শাসনভার নিজের হাতে নিয়ে কঠোর কেন্দ্রীকরণের যুগ শুরু করবেন।", "6dea0fec"]},
"OLAYLAR_EK5:1623-11-28:0":{"b": ["বাগদাদের সাফাভিদের কাছে হারানো", "db81be0c"], "d": ["বাগদাদে বিদ্রোহ করা বেকির সুবাশির সাফাভিদের সঙ্গে চালানো দর কষাকষির শেষে অভ্যন্তরীণ দুর্গ রক্ষাকারী ছেলে দারবিশ মেহমেদ শহর শাহ আব্বাসের বাহিনীর কাছে সমর্পণ করলেন। খিলাফত উত্তরাধিকারের প্রতীক শহরগুলোর একটি এবং ইরাকের বড় অংশ হাতছাড়া হওয়া ইস্তানবুলে বড় ক্ষোভ সৃষ্টি করল। বাগদাদ পুনরুদ্ধার পনেরো বছর অটোমান পূর্ব নীতির একমাত্র লক্ষ্য হবে।", "ef09360d"]},
"OLAYLAR_EK5:1628-09-22:0":{"b": ["আবাজা মেহমেদ পাশার এরজুরুমকেন্দ্রিক বিদ্রোহ দমন", "e6da2729"], "d": ["দ্বিতীয় ওসমানের হত্যার প্রতিশোধ নেওয়ার দাবিতে জ্যানিসারিদের বিরুদ্ধে বিদ্রোহ করা এরজুরুমের বেইলারবেই আবাজা মেহমেদ পাশা বছরের পর বছর পূর্ব আনাতোলিয়া নিয়ন্ত্রণে রেখে কেন্দ্রের বিরুদ্ধে প্রতিরোধ করলেন। সদরে আজম হুসরেভ পাশার এরজুরুম অবরোধে আত্মসমর্পণে বাধ্য হলেন, ক্ষমা পেয়ে বসনিয়ায় নিযুক্ত হলেন। বিদ্রোহের অবসান চতুর্থ মুরাদের ইরানের বিরুদ্ধে অভিযানে বের হওয়ার পূর্বশর্ত ছিল।", "68311e29"]},
"OLAYLAR_EK5:1634-01-08:0":{"b": ["প্রথম শেখুল ইসলামের মৃত্যুদণ্ড: আহিজাদে হুসেইন এফেন্দি", "a60a58c5"], "d": ["সামরিক বিশৃঙ্খলায় মধ্যস্থতা করা এবং সুলতানকে বিচারপদ্ধতি সম্পর্কে লিখিত সতর্কবার্তা পাঠানোর অজুহাতে শেখুল ইসলাম আহিজাদে হুসেইন এফেন্দি ব্যুয়ুকচেকমেজের কাছে মৃত্যুদণ্ডপ্রাপ্ত হলেন। মৃত্যুদণ্ড পাওয়া প্রথম অটোমান শেখুল ইসলাম হওয়ায় উলামাশ্রেণির জন্য সর্বোচ্চ শাস্তি নির্বাসন হওয়ার প্রতিষ্ঠিত ঐতিহ্য ভাঙল। ঘটনা চতুর্থ মুরাদের কঠোর হয়ে ওঠা কর্তৃত্ব এবং রাষ্ট্র-উলামা ভারসাম্যের বিঘ্নের প্রতীক গণ্য হয়।", "2822f303"]},
"OLAYLAR_EK5:1635-08-08:0":{"b": ["চতুর্থ মুরাদের ইরেভান বিজয়", "b65a9b73"], "d": ["28 মার্চ 1635 সালে ইস্তানবুল থেকে যাত্রা করা চতুর্থ মুরাদ 28-29 জুলাই ইরেভান অবরোধ করলেন এবং 8 আগস্ট দুর্গ হস্তগত করলেন; এর পর পরিত্যক্ত তাবরিজে প্রবেশ করে শহর ধ্বংস করালেন। সুলতান বিজয়ের স্মৃতিতে তোপকাপি প্রাসাদে ইরেভান কিয়স্ক নির্মাণ করালেন। এই অভিযান সুলতানের নিজে সেনাবাহিনীর নেতৃত্ব দেওয়া ত্রিশ বছরের বিরতির পর প্রথম বড় পূর্ব অভিযান ছিল।", "2da4da04"]},
"OLAYLAR_EK5:1636-04-01:0":{"b": ["ইরেভানের সাফাভিদের কাছে হারানো", "fbb8dd25"], "d": ["অটোমান সেনাবাহিনীর পিছু হটার পর শাহ সাফির বাহিনী ইরেভান অবরোধ করে আট মাসের মধ্যে ফিরিয়ে নিল। দুর্গ এত দ্রুত হাতছাড়া হওয়া ককেশাসে স্থায়ী কর্তৃত্ব রসদের দিক থেকে কতটা কঠিন তা দেখাল। ইরেভান 1639 সালের কাসর-ই শিরিন চুক্তিতেও ইরানের হাতে থাকবে এবং অটোমানরা আজারবাইজান দাবি ছেড়ে দেবে।", "f90cb004"]},
"OLAYLAR_EK5:1638-12-24:0":{"b": ["বাগদাদের পুনরুদ্ধার", "4d2f27f3"], "d": ["8 মে 1638 সালে ইস্তানবুল থেকে বের হওয়া চতুর্থ মুরাদ চল্লিশ দিন স্থায়ী তীব্র অবরোধের পর পনেরো বছর ধরে সাফাভি হাতে থাকা বাগদাদ ফিরিয়ে নিলেন; অবরোধে উজির তাইয়ার মেহমেদ পাশা শহিদ হলেন। শহর বিজয়ে ইরাকে অটোমান শাসন পুনঃপ্রতিষ্ঠিত হলো এবং সুলতান 'বাগদাদ বিজেতা' উপাধি পেলেন। বিজয় পরের বছরের কাসর-ই শিরিন চুক্তিতে স্থায়ী হয়ে বর্তমান তুরস্ক-ইরান সীমান্তের ভিত্তি স্থাপন করল।", "bb99d1fb"]},
"OLAYLAR_EK5:1640-02-09:0":{"b": ["চতুর্থ মুরাদের মৃত্যু এবং সুলতান ইব্রাহিমের সিংহাসনারোহণ", "e2ca1ca0"], "d": ["সাতাশ বছর বয়সে (হিজরি গণনায় আঠাশ) মারা যাওয়া চতুর্থ মুরাদের পর রাজবংশের জীবিত একমাত্র পুরুষ সদস্য ভাই ইব্রাহিম সিংহাসনে বসলেন। বছরের পর বছর কাফেসে বাস করা নতুন সুলতানের রাজত্বে প্রাসাদ ব্যয় ও প্রাসাদের অভ্যন্তরীণ প্রভাব-সংগ্রাম রাষ্ট্রব্যবস্থাকে নাড়িয়ে দিল। আট বছর পর অপসারিত হয়ে নিহত হওয়ায় অটোমান ইতিহাসের দ্বিতীয় সুলতান হত্যা ঘটবে।", "9ad0a971"]},
"OLAYLAR_EK5:1642-02-26:0":{"b": ["আজাক দুর্গ কসাকদের কাছ থেকে পুনরুদ্ধার", "e5fcf160"], "d": ["1637 সালে দন কসাকদের দখল করা আজাক দুর্গ সুলতানজাদে মেহমেদ পাশা ও ক্রিমিয়ার খান চতুর্থ মেহমেদ গিরাইয়ের যৌথ অভিযানের মুখে খালি করা হলো; কসাকরা দুর্গে আগুন লাগিয়ে সরে গেল। কৃষ্ণ সাগরের উত্তর দ্বার ফিরে পাওয়া কসাক হামলা ইস্তানবুল প্রণালী পর্যন্ত পৌঁছানোর বিপজ্জনক যুগের সমাপ্তি ঘটাল। দুর্গ 1696 সালে এবার রুশ জার প্রথম পিটারের কাছে হারাবে।", "39448f1f"]},
"OLAYLAR_EK5:1645-08-22:0":{"b": ["ক্রিট অভিযানের সূচনা এবং খানিয়া বিজয়", "a1b0c77f"], "d": ["মাল্টার জলদস্যুরা অটোমান হজ জাহাজে আঘাত করে ক্রিটে আশ্রয় নেওয়ার অজুহাতে ভেনিসের বিরুদ্ধে যুদ্ধ ঘোষণা হলো এবং ইউসুফ পাশার নেতৃত্বাধীন নৌবহর দ্বীপে সৈন্য নামাল। চুয়ান্ন দিনের অবরোধের পর খানিয়া দুর্গ নিয়ে ক্রিটে প্রথম স্থায়ী অটোমান ঘাঁটি স্থাপিত হলো। এভাবে অটোমান ইতিহাসের সবচেয়ে দীর্ঘস্থায়ী যুদ্ধ শুরু হলো; দ্বীপ কেবল চব্বিশ বছর পর, 1669 সালে সম্পূর্ণ বিজিত হবে।", "2809708a"]},
"OLAYLAR_EK5:1646-11-13:0":{"b": ["রেসমো বিজয় — ক্রিটের দুই ভাগ", "8f2c4353"], "d": ["খানিয়া দখলের এক বছর পর দ্বীপের মধ্য অংশের রেসমো দুর্গও পড়ল এবং ক্রিটের পশ্চিম অর্ধেক সম্পূর্ণ অটোমান শাসনে এল। ভেনিসের হাতে কেবল রাজধানী কান্দিয়া ও পূর্ব প্রান্ত রইল; দ্বীপ তেইশ বছর দুই ভাগে বিভক্ত অবস্থায় রইল। রেসমো দখল কান্দিয়া অবরোধ শুরু করা পদক্ষেপ হলো — ইতিহাসের দীর্ঘতম অবরোধ এখানেই শুরু হলো।", "88ec9840"]},
"OLAYLAR_EK5:1648-03-31:0":{"b": ["ক্লিসের ভেনিসের কাছে হারানো", "5473c22c"], "d": ["ক্রিট (কান্দিয়া) যুদ্ধের দালমাটিয়া ফ্রন্টে ভেনিসীয় সেনাপতি লেওনার্দো ফসকোলোর পাল্টা আক্রমণ 1537 সাল থেকে সানজাক কেন্দ্র থাকা ক্লিসকেও অন্তর্ভুক্ত করল; দুর্গ ভেনিসের হাতে গেল। অটোমানদের সমস্ত শক্তিসহ ক্রিটে মনোযোগ দালমাটিয়া সীমান্তের এই ক্ষতি ফিরিয়ে আনা অসম্ভব করল — ক্লিস আর কখনো অটোমান শাসনে ফিরবে না; সানজাক কেন্দ্র লিভনোয় সরানো হলো।", "d0ec59d4"]},
"OLAYLAR_EK5:1648-05-01:0":{"b": ["কান্দিয়া অবরোধের সূচনা", "13016b10"], "d": ["খানিয়া ও রেসমো দখলের পর অটোমান সেনাবাহিনী দ্বীপে ভেনিসের শেষ বড় অবলম্বন কান্দিয়া অবরোধ করল। একুশ বছর স্থায়ী এই অবরোধ বিশ্ব সামরিক ইতিহাসের দীর্ঘতম অবরোধগুলোর একটি হিসেবে লিপিবদ্ধ হয়েছে। অবরোধকালে ভেনিসীয় নৌবহরের চানাক্কালে প্রণালী বন্ধ করার চেষ্টা যুদ্ধকে এজিয়ানের কেন্দ্রে নিয়ে যাবে।", "8a35e8f9"]},
"OLAYLAR_EK5:1651-09-02:0":{"b": ["বড় ভালিদে কোসেম সুলতানের হত্যা", "9d763f79"], "d": ["প্রায় বাষট্টি বছর বয়সী কোসেম সুলতান চতুর্থ মেহমেদের মা তুর্হান সুলতানের আদেশে কাজ করা বাশলালা উজুন সুলায়মান আগা ও তাঁর লোকদের হাতে হারেমের একটি কক্ষে নিহত হলেন। তিন সুলতানের আমলে রাষ্ট্রনীতি পরিচালনা করা এই শক্তিশালী রাজবংশীয় নারীর মৃত্যু 'নারীদের সালতানাত' নামের যুগের কার্যত অবসান গণ্য হয়। শূন্য হওয়া কর্তৃত্ব পাঁচ বছর পর কোপ্রুলু মেহমেদ পাশার অসাধারণ ক্ষমতাসহ সদরে আজম হওয়ার পথ খুলল।", "d1ff09cb"]},
"OLAYLAR_EK5:1656-07-13:0":{"b": ["চানাক্কালে বিপর্যয় এবং বজ্জাআদা ও লিমনোসের হারানো", "e01a1f7e"], "d": ["ভেনিসীয় অ্যাডমিরাল মোচেনিগোর 1656 সালের জুনে চানাক্কালে প্রণালীর সামনে অর্জিত বড় নৌবিজয় অটোমান নৌবহরকে প্রায় সম্পূর্ণ ধ্বংস করল; এর পর বজ্জাআদা, লিমনোস ও সামোথ্রেস দখল করা হলো। প্রণালী ভেনিসীয় অবরোধে পড়ায় ইস্তানবুলে খাদ্যের দাম বেড়ে গেল এবং রাজধানীতে আক্রমণের ভয় ছড়াল। এই বিপর্যয় 1656 সালের সেপ্টেম্বরে কোপ্রুলু মেহমেদ পাশাকে শর্তসাপেক্ষে ও অসাধারণ ক্ষমতাসহ সদরে আজম পদে আনার সরাসরি কারণ হলো।", "31f7a914"]},
"OLAYLAR_EK5:1657-08-25:0":{"b": ["চানাক্কালে বিজয় এবং বজ্জাআদার পুনরুদ্ধার", "603da863"], "d": ["কোপ্রুলু মেহমেদ পাশার সংগঠিত নৌবহর 19 জুলাই 1657 সালে প্রণালীর সামনে ভেনিসীয় বহরকে পরাজিত করল; এর পর কুর্দ পাশার নেতৃত্বাধীন বাহিনী 25 আগস্ট বজ্জাআদা ফিরিয়ে নিল এবং 30 আগস্ট ভেনিসীয়রা দ্বীপ সম্পূর্ণ খালি করল। নভেম্বরে লিমনোসও উদ্ধার হয়ে চানাক্কালে অবরোধ ভাঙল এবং ইস্তানবুলের রসদপথ আবার খুলল। কোপ্রুলু নিজে দ্বীপে গিয়ে সুরক্ষা ব্যবস্থা মেরামত করালেন; এই সাফল্য কোপ্রুলু যুগের প্রথম বড় সামরিক লাভ।", "af4d7bfd"]},
"OLAYLAR_EK5:1657-11-15:0":{"b": ["লেমনস ভেনিসের কাছ থেকে পুনরুদ্ধার", "a4c3c69b"], "d": ["1656 সালের জুলাইয়ে ভেনিসের নেওয়া লেমনস 1657 সালের নভেম্বরে অটোমানদের কাছে ফিরে আসে।", "1d61fe33"]},
"OLAYLAR_EK5:1658-08-27:0":{"b": ["ইয়ানোভা (ইনেউ) বিজয় এবং ট্রান্সিলভানিয়া অভিযান", "d1089616"], "d": ["অনুমতি ছাড়া পোল্যান্ড অভিযানে বের হয়ে অটোমান আশ্রয় লঙ্ঘন করা ট্রান্সিলভানিয়ার প্রিন্স দ্বিতীয় গিওর্গি রাকোচিকে শাস্তি দিতে অভিযানে বের হওয়া কোপ্রুলু মেহমেদ পাশা বেলগ্রেড হয়ে এগিয়ে কৌশলগত ইয়ানোভা দুর্গ নিলেন। ট্রান্সিলভানিয়ায় নতুন প্রিন্স নিযুক্ত করে অনুগত বন্ধনের কথা কঠোরভাবে স্মরণ করানো হলো। এই অভিযান অটোমানদের মধ্য ইউরোপে কর্তৃত্ব পুনঃপ্রতিষ্ঠার প্রচেষ্টার প্রথম কড়া ছিল। ট্রান্সিলভানিয়া আগে থেকেই অটোমানদের অনুগত প্রিন্সিপালিটি ছিল; ইয়ানোভা দখল বিদেশি রাষ্ট্রের কাছ থেকে বিজয় নয়, অনুগত ট্রান্সিলভানিয়ার এই দুর্গ প্রিন্সিপালিটির প্রশাসন থেকে বের করে সরাসরি অটোমান সানজাকের সঙ্গে যুক্ত করা ছিল; প্রিন্সিপালিটির বাকি অংশ অনুগত মর্যাদায় রইল।", "4e24d834"]},
"OLAYLAR_EK5:1659-02-16:0":{"b": ["আবাজা হাসান পাশার বিদ্রোহ দমন", "4ba74321"], "d": ["কোপ্রুলু মেহমেদ পাশার কঠোর শুদ্ধির বিরুদ্ধে আনাতোলিয়ার বেইলারবেই ও সেকবান আগাদের পেছনে পাওয়া আবাজা হাসান পাশা সদরে আজমের অপসারণ দাবি করে বড় অভ্যুত্থান শুরু করলেন। বিদ্রোহ আলেপ্পোয় দমন করা হলো এবং নেতারা সরিয়ে দেওয়া হলো; এটি প্রদেশের পাশাদের কেন্দ্রের বিরুদ্ধে শেষ সম্মিলিত প্রতিরোধ হলো। কোপ্রুলুর কর্তৃত্ব এভাবে প্রশ্নাতীত হলো এবং সদারত পদ আবার রাষ্ট্রের প্রকৃত নির্বাহী কেন্দ্রের অবস্থানে উঠল।", "900e66b5"]},
"OLAYLAR_EK5:1660-08-27:0":{"b": ["ভারাদ (ওরাদেয়া) বিজয়", "0e6ad300"], "d": ["অটোমানদের বিরুদ্ধে যুদ্ধ ঘোষণা করা ট্রান্সিলভানিয়ার প্রিন্স দ্বিতীয় গিওর্গি রাকোচির বিরুদ্ধে সংগঠিত অভিযানের কাঠামোয় ভারাদ দুর্গ ও শহর নেওয়া হলো। ট্রান্সিলভানিয়ার অন্যতম মূল দুর্গের পতনে অঞ্চলে নতুন অটোমান প্রদেশ (ভারাদ প্রদেশ) গঠিত হলো। বিজয় হাবসবুর্গদের সতর্ক করল এবং তিন বছর পর শুরু হওয়া অটোমান-অস্ট্রিয়া যুদ্ধের সরাসরি কারণগুলোর একটি হলো। একই তারিখে যুক্ত হওয়া অন্যান্য স্থান: ভারাত। এখানেও ভূমি বিদেশি রাষ্ট্রের কাছ থেকে নেওয়া হয়নি: ট্রান্সিলভানিয়া আগে থেকেই অনুগত অটোমান প্রিন্সিপালিটি ছিল; ভারাদের প্রদেশ হওয়া কেবল এই শহরের প্রশাসন অনুগত প্রিন্সিপালিটির কাছ থেকে নিয়ে সরাসরি সুলতানের সঙ্গে যুক্ত করল, ঠিক দুই বছর আগে ইয়ানোভার মতো।", "991162de"]},
"OLAYLAR_EK5:1664-08-01:0":{"b": ["সেন্ট গটহার্ড (সেন গোতার) যুদ্ধ", "61ebc1f2"], "d": ["রাব নদী পার হওয়া অটোমান বাহিনী মন্তেকুকোলির নেতৃত্বাধীন মিত্র ইউরোপীয় সেনাবাহিনীর দ্বারা থামানো হলো এবং ভারী ক্ষতি সইল। শৃঙ্খলাবদ্ধ আগ্নেয়াস্ত্রধারী পদাতিকের বন্দুক-গুলি অটোমান অশ্বারোহী আক্রমণের ওপর শ্রেষ্ঠত্ব প্রথমবার স্পষ্টভাবে দেখানোর কারণে যুদ্ধ সামরিক ইতিহাসে মোড় গণ্য হয়। পরাজয় সত্ত্বেও অটোমানরা নয় দিন পর স্বাক্ষরিত ভাসভার চুক্তিতে সুবিধাজনক শর্ত অর্জনে সফল হলো।", "4ab743fc"]},
"OLAYLAR_EK5:1664-08-09:0":{"b": ["ভাসভার চুক্তি", "089c978c"], "d": ["সেন্ট গটহার্ড পরাজয় সত্ত্বেও স্বাক্ষরিত চুক্তি ইউভার ও ভারাদের অটোমানদের হাতে থাকা, ট্রান্সিলভানিয়াকে অটোমান আশ্রয়ে নিরপেক্ষ রাখা এবং অস্ট্রিয়ার 200.000 কুরুশ 'উপহার' দেওয়া নির্ধারণ করল। বিশ বছর মেয়াদি এই শান্তি যুদ্ধে পরাজিত পক্ষের টেবিলে জেতার বিরল দৃষ্টান্তগুলোর একটি। চুক্তিতে হাবসবুর্গ জনমতে সৃষ্ট অসন্তোষ মধ্য হাঙ্গেরীয় আন্দোলন এবং পরোক্ষে 1683 সালের ভিয়েনা অভিযানকে পুষ্ট করবে।", "61ca5d47"]},
"OLAYLAR_EK5:1671-01-01:0":{"b": ["আলজিয়ার্সে দে শাসনের সূচনা", "e99faa51"], "d": ["আলজিয়ার্সের ওজাক ও তায়ফা-ই রাইস (জলদস্যু ক্যাপ্টেনরা) শেষ আগাকে অপসারণ করে হাজি মেহমেদকে আজীবন শর্তে দে নির্বাচিত করল। এরপর আলজিয়ার্স শাসন করল ইস্তানবুল নিযুক্ত বেইলারবেই নয়, স্থানীয় ওজাকের নিজেদের মধ্য থেকে নির্বাচিত দে; অটোমান বন্ধন খুতবায় সুলতানের নাম পড়া, সানজাক ও অভিযানের দায়িত্বে সীমিত রইল। আলজিয়ার্স এভাবে প্রদেশ থেকে ওজাকলিকে রূপান্তরিত হলো — একই রূপান্তর তিউনিস 1705 সালে হুসাইনিদের, ত্রিপোলি 1711 সালে কারামানলিদের সঙ্গে অনুভব করল।", "b8decd95"]},
"OLAYLAR_EK5:1672-06-04:0":{"b": ["পোল্যান্ড অভিযান শুরু — চতুর্থ মেহমেদ ও ফাজিল আহমেদ পাশা বাহিনীর শীর্ষে", "75e15a39"], "d": ["অটোমান আশ্রয়ে আসা ইউক্রেনের হেতম্যান পেত্রো দরোশেঙ্কোর বিরুদ্ধে পোল্যান্ডের আক্রমণ চলতে থাকায় ইস্তানবুল পোলিশ রাজার কাছে আক্রমণ ত্যাগ করতে বলল; ইতিবাচক উত্তর না আসায় পোল্যান্ডে অভিযানের সিদ্ধান্ত নেওয়া হলো। উজির-ই-আজম ফাজিল আহমেদ পাশা সুলতানও উপস্থিত থাকা সেনাবাহিনী নিয়ে 4 জুন 1672 সালে পোল্যান্ডের উদ্দেশে যাত্রা করলেন। অভিযান কামিয়ানেৎস বিজয় ও বুচাচ চুক্তিতে পরিণতি পাবে।", "7340721a"]},
"OLAYLAR_EK5:1672-08-27:0":{"b": ["কামিয়ানেৎস বিজয় এবং পোডোলিয়া প্রদেশের প্রতিষ্ঠা", "c3f4f6d0"], "d": ["নয় দিনের অবরোধের পর পোল্যান্ডের পূর্বের সবচেয়ে শক্তিশালী দুর্গ গণ্য কামিয়ানেৎস হস্তগত হলো; চতুর্থ মেহমেদ 2 সেপ্টেম্বর ক্যাথেড্রাল থেকে রূপান্তরিত মসজিদে প্রথম জুমার নামাজ আদায় করলেন। দুর্গকে কেন্দ্র করে পোডোলিয়া প্রদেশ গঠিত হলো এবং অটোমান পতাকা বর্তমান ইউক্রেনের ভূমিতে সবচেয়ে উত্তরে পৌঁছাল। কামিয়ানেৎস 1699 সালের কার্লোভিৎস চুক্তি পর্যন্ত সাম্রাজ্যের উত্তর-পশ্চিম প্রান্ত হিসেবে থাকবে।", "d89c513a"]},
"OLAYLAR_EK5:1674-08-03:0":{"b": ["কারা মুস্তাফা পাশা উমান পোল্যান্ডের কাছ থেকে নিলেন", "0d3543a0"], "d": ["পোল্যান্ডের বিরুদ্ধে পাঠানো কারা মুস্তাফা পাশা পোল্যান্ডের হাতে থাকা দুর্গগুলোর মধ্যে উমান হস্তগত করলেন; শহর কার্লোভিৎস পর্যন্ত অটোমান শাসনে থাকল।", "bdb8e553"]},
"OLAYLAR_EK5:1678-08-21:0":{"b": ["চেহরিন দুর্গ বিজয়", "a17cedd0"], "d": ["এক বছর আগে মেলেক ইব্রাহিম পাশার ফল না পাওয়া অভিযানের পর সদরে আজম মেরজিফনলু কারা মুস্তাফা পাশা নিজে নেতৃত্ব দিয়ে সুরক্ষিত চেহরিন দুর্গ অবরোধ করলেন (19/21 জুলাই) এবং 21 আগস্ট দখল করলেন। ইউক্রেনের কসাক হেতম্যানত্বের ওপর অটোমান-রুশ প্রতিদ্বন্দ্বিতার প্রতীক এই দুর্গের পতন রাশিয়াকে শান্তিতে বাধ্য করল। এই সাফল্য মেরজিফনলুর ভিয়েনার দিকে যাত্রার আত্মবিশ্বাসেরও উৎসগুলোর একটি হলো।", "aee53ec4"]},
"OLAYLAR_EK5:1681-02-13:0":{"b": ["বাখচিসারাই চুক্তি — রাশিয়ার সঙ্গে প্রথম আনুষ্ঠানিক শান্তি", "df82bc0b"], "d": ["চেহরিন অভিযানের পর ক্রিমিয়ার খানের মধ্যস্থতায় চালানো আলোচনার শেষে ওজু (নিপার) নদীকে সীমান্ত মেনে অটোমান রাষ্ট্র ও রাশিয়ার মধ্যে বিশ বছর মেয়াদি শান্তি স্বাক্ষরিত হলো। এটি দুই রাষ্ট্রের মধ্যে প্রথম ব্যাপক চুক্তি হওয়ায় অটোমান-রুশ সম্পর্কের সূচনা-দলিল গণ্য হয়। শান্তির ফলে পূর্ব ফ্রন্ট নিরাপদ করে সেনাবাহিনীকে মধ্য ইউরোপে পাঠানো গেল।", "56f57388"]},
"OLAYLAR_EK5:1682-09-16:0":{"b": ["তোকোলি ইমরেকে মধ্য হাঙ্গেরীয় রাজ্যের বেরাত প্রদান", "3cd8d51d"], "d": ["হাবসবুর্গ চাপের বিরুদ্ধে বিদ্রোহ করা প্রোটেস্ট্যান্ট হাঙ্গেরীয় অভিজাত তোকোলি ইমরে 1682 সালের এপ্রিল থেকে 'মধ্য হাঙ্গেরির নির্বাচিত রাজা' গণ্য হতে শুরু করলেন এবং 16 সেপ্টেম্বর বুদার বেইলারবেই ইব্রাহিম পাশা তাঁকে প্রিন্সিপালিটির নিদর্শন উপহার দিলেন। এভাবে অটোমান আশ্রয়ে নতুন অনুগত হাঙ্গেরীয় রাষ্ট্র গঠিত হলো। এই হস্তক্ষেপ অস্ট্রিয়ার সঙ্গে যুদ্ধ অনিবার্য করে পরের বছরের দ্বিতীয় ভিয়েনা অবরোধের শৃঙ্খল শুরু করল।", "6f7f5236"]},
"OLAYLAR_EK5:1684-08-06:0":{"b": ["আয়ামাভ্রার (লেফকাদা) ভেনিসের কাছে হারানো", "e6905fee"], "d": ["পবিত্র মৈত্রীতে যোগ দেওয়া ভেনিসের নৌবহর শহরে গোলাবর্ষণের পর আয়োনীয় সাগরের আয়ামাভ্রা দ্বীপ দখল করল। একই বছর প্রেভেজার পতনেও অটোমানদের আদ্রিয়াটিক মুখে নিয়ন্ত্রণ ভেঙে গেল। এই ক্ষতিগুলো মোরোসিনির তিন বছরের মধ্যে সমগ্র মোরিয়া দখল করা অভিযানের সূচনা-পদক্ষেপ ছিল।", "8fe34c55"]},
"OLAYLAR_EK5:1685-08-11:0":{"b": ["করোনের ভেনিসের কাছে হারানো", "2ed762bc"], "d": ["মোরোসিনির নেতৃত্বাধীন ভেনিসীয় বাহিনী মোরিয়া উপদ্বীপের দক্ষিণ-পশ্চিম প্রান্তের করোন দুর্গ দখল করল; শহর এর পর ত্রিশ বছর ভেনিসীয় শাসনে থাকবে। করোনের পতন মোরিয়া বিজয়ে ভেনিসীয় অভিযানের প্রথম বড় লাভ ছিল। দুর্গ কেবল 1715 সালে সিলাহদার আলি পাশার নেতৃত্বাধীন অটোমান সেনাবাহিনী ফিরিয়ে নিতে পারল।", "506cf83e"]},
"OLAYLAR_EK5:1688-04-08:0":{"b": ["এথেন্সের পুনরুদ্ধার — ভেনিসের সরে যাওয়া", "03393b46"], "d": ["1687 সালের সেপ্টেম্বরে অ্যাক্রোপোলিসে গোলাবর্ষণ করে পার্থেনন উড়িয়ে দেওয়া মোরোসিনি শীত এথেন্সে কাটিয়ে শহরে টিকে থাকা সম্ভব নয় বুঝলেন। প্লেগ মহামারি, রসদ-কষ্ট এবং অটোমান বাহিনীর গুছিয়ে ওঠায় ভেনিসীয় গ্যারিসন শহর খালি করে মোরিয়ায় সরে গেল। এথেন্স এভাবে যুদ্ধ ছাড়াই আবার অটোমান শাসনে ফিরল, তবে পার্থেননের ধ্বংস ফিরিয়ে আনা গেল না।", "79c8586a"]},
"OLAYLAR_EK5:1688-06-22:0":{"b": ["লিপভা (লিপ্পা) কারাফার কাছে আত্মসমর্পণ করল — অস্ট্রিয়ার হাতে গেল", "7f0a8d38"], "d": ["আন্তোনিও কারাফার তিন দিনের অবরোধের পর লিপভা 12-22 জুন 1688-এর মধ্যে আত্মসমর্পণ করে অস্ট্রিয়ার হাতে যায়। অটোমানরা পরে শহরটি ফিরিয়ে নেয়, অস্ট্রিয়া 1691 সালে আবার দখল করে; 1695 সালের অভিযানে অটোমানরা আবার নিয়ন্ত্রণ ফিরে পায়। একই তারিখে অ্যাটলাসে অটোমান থেকে হাবসবুর্গে যাওয়া অন্যান্য বসতি: আরাদ ও ভিলাগোশ (শিরিয়া)। আরাদের জন্য সূত্র কেবল বছর দেয় (MKL, Arad: 1551-1688-এর মধ্যে অটোমানদের হাতে); দিনটি লিপভা থেকে নেওয়া, ভিলাগোশ আরাদের ধারা অনুসরণ করে (ঘোষিত আনুমানিকতা)।", "0dfcf5af"]},
"OLAYLAR_EK5:1688-10-20:0":{"b": ["ভেনিসের ইউবোয়া (এগ্রিবোজ) অবরোধ প্রতিহত", "aae7e6a0"], "d": ["মোরিয়া দখলের পর এজিয়ানের দিকে অগ্রসর মোরোসিনি তিন মাসের বেশি অবরোধে ইউবোয়া নিতে চেষ্টা করলেন; তবে 1687-1688 শীতে শক্তিশালী করা সুরক্ষা ব্যবস্থা ও গ্যারিসনের প্রতিরোধের মুখে ভারী ক্ষতি করে পিছু হটতে বাধ্য হলেন। এই ব্যর্থতা ভেনিসের এজিয়ানে অগ্রগতি থামাল এবং মোরোসিনির সামরিক সুনাম নাড়িয়ে দিল। ইউবোয়া কার্লোভিৎসেও অটোমান হাতে থাকবে।", "ea8430a3"]},
"OLAYLAR_EK5:1690-04-23:0":{"b": ["কানিজসা দুর্গের অস্ট্রিয়ার কাছে হারানো", "553b45f3"], "d": ["1690 সালের জানুয়ারি থেকে 60.000 জনের হাবসবুর্গ সেনাবাহিনীর কঠোর অবরোধে পড়া কানিজসা মাসের পর মাস সাহায্য না পেয়ে প্রতিরোধের পর শেষ রক্ষী মুস্তাফা পাশার স্বাক্ষরিত আত্মসমর্পণ চুক্তিতে হাতছাড়া হলো। এভাবে তিরিয়াকি হাসান পাশার মহাকাব্যিক প্রতিরক্ষায় স্মরণীয় দুর্গে নব্বই বছরের অটোমান কর্তৃত্বের অবসান হলো। কানিজসার হারানো হাঙ্গেরির পশ্চিমে অটোমানদের শেষ বড় অবলম্বনের পতন ছিল।", "dc630d57"]},
"OLAYLAR_EK5:1691-06-22:0":{"b": ["দ্বিতীয় সুলায়মানের মৃত্যু", "d2478080"], "d": ["প্রায় চল্লিশ বছর খাঁচায় কাটানোর পর 1687 সালে সিংহাসনে বসানো দ্বিতীয় সুলায়মান অসুস্থ অবস্থায় বাহিনীর প্রস্তুতি দেখতে দেখতে 22 জুন 1691 শুক্রবার দুপুরের দিকে এডির্নে মারা যান; তাঁর শাসন তিন বছর আট মাস দুই দিন স্থায়ী হয়। প্রধান উজির সুলতানের মৃত্যু হলে ভাই আহমেদকে সিংহাসনে বসানোর প্রয়োজনীয় নির্দেশ আগেই দিয়েছিলেন। জানাজা একই দিনে আলায় কোশকে পড়া হয়; মরদেহ ইস্তানবুলে এনে আইনদাতা সুলতান সুলায়মানের সমাধিতে তাঁর ডান পাশে সমাহিত করা হয়।", "3cf4fcb1"]},
"OLAYLAR_EK5:1691-06-23:0":{"b": ["দ্বিতীয় আহমেদের সিংহাসনারোহণ", "52947b14"], "d": ["দ্বিতীয় সুলায়মানের মৃত্যুতে উনপঞ্চাশ বছর বয়সী ভাই দ্বিতীয় আহমেদ এডির্নে সিংহাসনে বসলেন। তাঁর রাজত্ব পবিত্র মৈত্রী যুদ্ধের সবচেয়ে ভারী বছরগুলোর সঙ্গে মিলে গেল; সিংহাসনারোহণের দুই মাস পর সালানকেমেনে সদরে আজম ফাজিল মুস্তাফা পাশা শহিদ হলেন। অন্যদিকে তাঁর আমলে চালু মালিকানে ব্যবস্থা অটোমান অর্থব্যবস্থার দীর্ঘমেয়াদি কাঠামো বদলে দেওয়া সবচেয়ে গুরুত্বপূর্ণ ব্যবস্থাগুলোর একটি হলো।", "d3441b14"]},
"OLAYLAR_EK5:1693-01-06:0":{"b": ["চতুর্থ মেহমেদের এডির্নে মৃত্যু", "17388b7e"], "d": ["1687 সালে সিংহাসনচ্যুত শিকারি মেহমেদ দ্বিতীয় সুলায়মানের 1689 সালের হাঙ্গেরীয় অভিযানের সময় এডির্নে আনা হন এবং অন্য ভাই দ্বিতীয় আহমেদের শাসনেরও সাক্ষী হন। প্রিয় এই শহরেই তিনি মারা যান। মরদেহ ইস্তানবুলে এনে মা তুরহান সুলতানের ইয়েনিজামির পাশের সমাধিতে সমাহিত করা হয়।", "fd0f3d8c"]},
"OLAYLAR_EK5:1695-02-06:0":{"b": ["দ্বিতীয় আহমেদের এডির্নে মৃত্যু", "c6306c08"], "d": ["চার বছরের শাসনকাল যুদ্ধে কাটানো দ্বিতীয় আহমেদ বাহান্ন বছর বয়সে ইস্তিস্কা (শোথ) রোগে এডির্নে মারা যান। মরদেহ ইস্তানবুলে এনে আইনদাতা সুলতান সুলায়মানের সমাধিতে দাফন করা হয়। তাঁর স্থলে ভাতিজা দ্বিতীয় মুস্তাফা বসেন।", "a61e819c"]},
"OLAYLAR_EK5:1696-01-01:0":{"b": ["বসরার ইরানিদের দ্বারা দখল", "a9cdf3a3"], "d": ["অটোমান রাষ্ট্র পশ্চিমে পবিত্র মৈত্রী যুদ্ধে ব্যস্ত থাকার সময় বসরা 1690 সালের প্লেগ মহামারির পর প্রথমে মুনতাফিক শেখ মানির, পরে হুওয়াইজা খান ফেরেজুল্লাহর লুটের শিকার হয়েছিল। এই বিশৃঙ্খলার সুযোগ নেওয়া ইরানিরা 1696 সালে শহর দখল করল এবং বসরায় একজন রক্ষী রেখে গেল।", "2db76d27"]},
"OLAYLAR_EK5:1700-07-14:0":{"b": ["ইস্তানবুল চুক্তি — আজাকের রাশিয়ার কাছে ছেড়ে দেওয়া", "79db4724"], "d": ["কার্লোভিৎসে রাশিয়ার সঙ্গে কেবল দুই বছরের যুদ্ধবিরতি করা গিয়েছিল; স্থায়ী শান্তি ইস্তানবুলে দেড় বছর স্থায়ী কঠিন দর কষাকষির পর স্বাক্ষরিত হলো। অটোমান রাষ্ট্র 1696 সালে হারানো আজাক দুর্গ ও আশপাশের ভূমি আনুষ্ঠানিকভাবে রাশিয়াকে ছেড়ে দিল, ক্রিমিয়ার খানের মস্কো থেকে পাওয়া বার্ষিক কর ত্যাগ করল। বিনিময়ে রাশিয়া ইস্তানবুলে স্থায়ী দূত রাখার অধিকার পেল; এভাবে কৃষ্ণ সাগরের উত্তর উপকূলে রুশ উপস্থিতি আইনত নিবন্ধিত হলো।", "a3a5a803"]},
"OLAYLAR_EK5:1701-01-01:0":{"b": ["দালতাবান মুস্তাফা পাশার কুর্না ও বসরা পুনরুদ্ধার", "7adb777d"], "d": ["কার্লোভিৎস চুক্তির পর বাগদাদের গভর্নর ও বসরার সেরাস্কার পদে আনা দালতাবান মুস্তাফা পাশা আলেপ্পো, রাক্কা, সিভাস ও কারামানের বাহিনী এবং বিরেচিক থেকে নেমে আসা নদী নৌবহর নিয়ে দক্ষিণে অগ্রসর হলেন। আশপাশের গোত্র শেখরা একে একে আনুগত্য জানালেন, ইরানের বসরা রক্ষী দাউদ খান শহর ত্যাগ করলেন এবং কুর্না ও বসরা আবার অটোমান শাসনে এল।", "60abbe06"]},
"OLAYLAR_EK5:1703-12-29:0":{"b": ["দ্বিতীয় মুস্তাফার মৃত্যু", "626c394d"], "d": ["এডির্ন ঘটনায় সিংহাসন ভাই তৃতীয় আহমেদকে ছেড়ে দেওয়া দ্বিতীয় মুস্তাফা সিংহাসনচ্যুতির প্রায় পাঁচ মাস পর প্রিয় এডির্নে মারা যান। সাম্প্রতিক ঘটনাবলির দুঃখও তাঁর অসুস্থতায় যুক্ত হয়েছিল। কিছু পশ্চিমা সূত্র লেখে, জনগণের মধ্যে তাঁকে বিষ খাওয়ানো হয়েছে বলে ধারণা ছড়িয়েছিল।", "8ce146e8"]},
"OLAYLAR_EK5:1704-01-01:0":{"b": ["বাগদাদে কোলেমেন (মামলুক) শাসনের সূচনা", "abe52618"], "d": ["জর্জীয় বংশোদ্ভূত হাসান পাশাকে বাগদাদের গভর্নর করায় ইরাকে কেন্দ্র থেকে নিযুক্ত গভর্নরদের জায়গায় নিজেদের দাসদের মধ্য থেকে গড়ে ওঠা শাসকগোষ্ঠী কর্তৃত্ব করার যুগ শুরু হলো। সুলায়মান পাশার 1749 সালের গভর্নরত্বে ব্যবস্থা পুরোপুরি স্থায়ী হলো এবং বাবে-আলি আর নিজের পছন্দের ব্যক্তি নয়, প্রভাব হাতে নেওয়া কোলেমেনদের একজনকে নিযুক্ত করতে বাধ্য হলো। এই আধা-স্বায়ত্তশাসিত কাঠামো ইরান সীমান্ত রক্ষায় কাজে এলেও ইরাকের ওপর কেন্দ্রীয় কর্তৃত্বের নিয়ন্ত্রণ দেড় শতাব্দী দুর্বল করল।", "7cf655d4"]},
"OLAYLAR_EK5:1705-07-12:0":{"b": ["তিউনিসে হুসাইনি রাজবংশের প্রতিষ্ঠা", "cb1a98f9"], "d": ["আলজিয়ার্স বাহিনীর তিউনিস আক্রমণে সৃষ্ট কর্তৃত্বশূন্যতায় তুর্কি বংশোদ্ভূত সিপাহি আগা হুসেইন ইবনে আলি বেগলিক দখল করলেন এবং অটোমান সুলতানের প্রতি আনুগত্য জানিয়ে বৈধতা অর্জন করলেন। তাঁর প্রতিষ্ঠিত রাজবংশ 1705-1735 এবং 1756-1957 সালের মধ্যে তিউনিস শাসন করল; ওজাক প্রশাসনের জায়গা নিল পিতা থেকে পুত্রে হস্তান্তরিত বেগলিক ব্যবস্থা। এভাবে পশ্চিমের ওজাকগুলোতে কেন্দ্রের সঙ্গে যুক্ত অথচ কার্যত স্বায়ত্তশাসিত রাজবংশীয় কাঠামোর প্রথম দৃষ্টান্ত জন্ম নিল।", "941c7858"]},
"OLAYLAR_EK5:1708-04-04:0":{"b": ["ওরান ও মেরস-এল-কেবিরের স্পেনীয়দের কাছ থেকে দখল", "b67ce06a"], "d": ["আলজিয়ার্স ওজাকের বেইলারবেই বাহিনী দুই শতাব্দী ধরে স্পেনীয় গ্যারিসনের হাতে থাকা ওরান ও বন্দর মেরস-এল-কেবির দীর্ঘ অবরোধের পর দখল করল। পশ্চিম ভূমধ্যসাগরে অটোমান আশ্রয়ে থাকা পশ্চিমের ওজাকগুলোর স্পেনের বিরুদ্ধে সবচেয়ে বড় সাফল্য ছিল এটি এবং আলজিয়ার্সের পশ্চিম পার্শ্ব নিরাপদ করল। শহর 1732 সালে আবার স্পেনীয় দখলে পড়বে, তবে 1792 সালে চূড়ান্তভাবে ফিরিয়ে নেওয়া হবে।", "33d9da74"]},
"OLAYLAR_EK5:1711-07-21:0":{"b": ["প্রুত চুক্তি — আজাক ও তাগানের ফিরিয়ে নেওয়া", "bac5d2a1"], "d": ["প্রুত নদীর তীরে অবরুদ্ধ রুশ সেনাবাহিনীর আত্মসমর্পণে স্বাক্ষরিত সাত ধারার চুক্তি আজাক দুর্গের ভূমি ও যুদ্ধসামগ্রীসহ অটোমানদের কাছে ফেরত দেওয়া নির্ধারণ করল। তাগান, কামেনকা ও ইয়েনিকালে দুর্গ ধ্বংস করা হবে, পক্ষগুলো এই অঞ্চলে নতুন দুর্গ নির্মাণ করবে না। প্রথম পিটারের ভরোনেজ ও আজাকে ষোলো বছর ধরে গড়া নৌবহর ও ঘাঁটি ব্যবস্থা ভেঙে পড়ল; রাশিয়ার কৃষ্ণ সাগরে নামা প্রায় পঞ্চাশ বছর বিলম্বিত হলো।", "657d45ff"]},
"OLAYLAR_EK5:1711-07-29:0":{"b": ["ত্রিপোলিতে কারামানলি রাজবংশের প্রতিষ্ঠা", "e1105d4a"], "d": ["ওজাক আগাদের দ্বন্দ্বে ক্লান্ত ত্রিপোলিতে অশ্বারোহী কর্মকর্তা আহমেদ কারামানলি শাসন হাতে নিলেন এবং ইস্তানবুল থেকে পাওয়া বেইলারবেইত্বের বেরাতে অবস্থান আনুষ্ঠানিক করলেন। আহমেদ পাশা, ছেলে মেহমেদ পাশা ও নাতি ইউসুফ পাশার হাতে 1711-1835 সালের মধ্যে চলা রাজবংশ জন্ম নিল; নিজের নৌবহর গড়া, ইউরোপীয় রাষ্ট্রের সঙ্গে সরাসরি চুক্তি স্বাক্ষর করা আধা-স্বাধীন কাঠামো উদ্ভূত হলো। এই যুগ কেবল 1835 সালে প্রদেশ সরাসরি কেন্দ্রের সঙ্গে যুক্ত হওয়ায় শেষ হবে।", "b1c3dd0a"]},
"OLAYLAR_EK5:1713-06-24:0":{"b": ["রাশিয়ার সঙ্গে এডির্ন চুক্তি", "14901a70"], "d": ["প্রুতে দেওয়া প্রতিশ্রুতি পালন না হওয়ায় আরও দুবার যুদ্ধ ঘোষণা হয়েছিল, অবশেষে রুশরা অঙ্গীকার মেনে নিলে এডির্নে স্থায়ী শান্তি স্বাক্ষরিত হলো। চুক্তি প্রুতের শর্ত নিশ্চিত করল; রাশিয়া পোল্যান্ডের বিষয়ে হস্তক্ষেপ করবে না, কসাক ভূমি থেকে সরে যাবে এবং সুইডেনের রাজা লৌহমানব দ্বাদশ চার্লসের দেশে ফেরায় বাধা দেবে না। উত্তর ফ্রন্ট এভাবে বন্ধ হওয়া অটোমান রাষ্ট্রের মোরিয়া ও ভেনিস ফ্রন্টের দিকে মুখ ফেরানো সম্ভব করল। একই তারিখে যুক্ত হওয়া অন্যান্য স্থান: খোতিন।", "34010e06"]},
"OLAYLAR_EK5:1714-12-08:0":{"b": ["ভেনিসের বিরুদ্ধে যুদ্ধ ঘোষণা — মোরিয়া অভিযানের প্রস্তুতি", "d970b122"], "d": ["ভেনিসের মন্টেনিগ্রোর বিদ্রোহীদের সমর্থন, অটোমান বাণিজ্য জাহাজ বাজেয়াপ্ত করা এবং কার্লোভিৎসে পাওয়া মোরিয়াকে ভারী করে চাপানোর অজুহাতে দিওয়ানে যুদ্ধের সিদ্ধান্ত নেওয়া হলো। সদরে আজম সিলাহদার দামাদ আলি পাশার প্রস্তুত অভিযান পরের বছর একশো দিনের কম সময়ে সমগ্র মোরিয়া উপদ্বীপ ফিরিয়ে নিয়ে শেষ হবে। তবে এই সাফল্য অস্ট্রিয়াকে সক্রিয় করবে এবং 1716 সালে অনেক ভারী যুদ্ধের দরজা খুলবে।", "ef2edb5f"]},
"OLAYLAR_EK5:1715-06-05:0":{"b": ["ইস্তেন্দিল (তিনোস): ভেনিসের এজিয়ানে শেষ দ্বীপের সমর্পণ", "4abec891"], "d": ["মোরিয়া অভিযানে বের হওয়া নৌবহর পথে ভেনিসের এজিয়ানে হাতে থাকা একমাত্র দ্বীপ ইস্তেন্দিলের সামনে নোঙর ফেলল। নাক্সোস ডিউকত্ব 1566 সালে পড়লেও ল্যাটিন জনসংখ্যার কারণে আরও দেড়শো বছর ভেনিসের পতাকা বহনকারী দ্বীপ সংক্ষিপ্ত অবরোধের পর রক্তপাত ছাড়াই আত্মসমর্পণ করল। এভাবে এজিয়ান সাগরে ভেনিসের শেষ পদচিহ্ন মুছে গেল এবং সাগর সম্পূর্ণ অটোমান অভ্যন্তরীণ সাগরে পরিণত হলো।", "7b191aca"]},
"OLAYLAR_EK5:1715-07-20:0":{"b": ["আনাবোলু বিজয় — মোরিয়ার মূল দুর্গ", "62a5808a"], "d": ["ভেনিসের মোরিয়ার রাজধানী ও সবচেয়ে শক্তিশালী দুর্গ আনাবোলু পালামিদি ব্যাস্টিয়ন নয় দিনের গোলাবর্ষণের পর দখল হওয়ায় পড়ল। দুর্গ এত দ্রুত নেওয়া উপদ্বীপের বাকি অংশের প্রতিরোধ ভাঙল। কার্লোভিৎসে হারানো মোরিয়ার পুনরুদ্ধার কার্যত এখানেই সম্পূর্ণ হলো। একই তারিখে অ্যাটলাসে ভেনিসের কাছ থেকে অটোমানদের হাতে যাওয়া অন্য বসতি: আর্গোস — আনাবোলুর আবি-মার্কেজ শৃঙ্খল অনুসরণ করে (TDV anabolu; ঘোষিত আনুমানিকতা)।", "8467e05c"]},
"OLAYLAR_EK5:1715-08-01:0":{"b": ["মোদনের আত্মসমর্পণ", "43faa909"], "d": ["আনাবোলুর পতনের পর মোরিয়ার দক্ষিণ-পশ্চিম প্রান্তের মোদন দুর্গ স্থলপথে সেনাবাহিনী ও সমুদ্রপথে নৌবহরের অবরোধে অল্প সময়ে আত্মসমর্পণ করল। ভেনিসের পূর্ব ভূমধ্যসাগর অভিযানে দুই শতাব্দী ব্যবহৃত এই বন্দর জাহাজের পানি ও খাদ্য নেওয়ার অপরিহার্য যাত্রাবিরতি স্থান ছিল। এর হারানো ভেনিসীয় নৌবহরের এজিয়ানে চলাচলের সক্ষমতা শেষ করল।", "0d2c6d1a"]},
"OLAYLAR_EK5:1715-08-16:0":{"b": ["কোরনের আত্মসমর্পণ — মোরিয়া অভিযানের সমাপ্তি", "e4b9c8a4"], "d": ["মেসেনিয়া উপসাগরের মুখে অবস্থিত কোরন দুর্গের আত্মসমর্পণের মাধ্যমে মোরিয়া উপদ্বীপে ভেনিসীয় শাসনের সম্পূর্ণ অবসান ঘটে। কার্লোভিৎসে হারানো উপদ্বীপটি অভিযান শুরুর মাত্র তিন মাস পরে পুরোপুরি পুনরুদ্ধার হয়। একই অভিযানের ধারাবাহিকতায় 1715 সালের সেপ্টেম্বরে আইওনীয় সাগরের আয়ামাভরা (লেফকাদা) দ্বীপও ভেনিসের কাছ থেকে নেওয়া হয়। এই দ্রুততা ভেনিসকে অস্ট্রিয়াকে যুদ্ধে টেনে আনতে বাধ্য করে এবং তিন বছর পর পাসারোভিৎসের পথ খুলে যায়।", "d3173b05"]},
"OLAYLAR_EK5:1715-09-07:0":{"b": ["কিথিরা দ্বীপ (চুহা দ্বীপ) দখল", "494de6c6"], "d": ["মোরিয়ার দক্ষিণ প্রান্তের চুহা দ্বীপ (কিথিরা) উপদ্বীপ সম্পূর্ণ হওয়ার পর নৌবহরের হাতে সমর্পিত হয়। আইওনীয় সাগর ও ইজিয়ানের মধ্যবর্তী পথ পাহারা দেওয়া এই দ্বীপ ছিল ভেনিসের এই জলসীমা নিয়ন্ত্রণের অগ্রবর্তী ঘাঁটি। তবে এটি অটোমানদের হাতে থাকা একমাত্র দ্বীপ হিসেবে টেকেনি: তিন বছর পর পাসারোভিৎসে তা ভেনিসকে ফিরিয়ে দেওয়া হয়।", "42162c0d"]},
"OLAYLAR_EK5:1716-04-13:0":{"b": ["অস্ট্রিয়া ও ভেনিস মৈত্রী গড়ল — 1716-1718 অটোমান-অস্ট্রিয়া যুদ্ধের দরজা", "99511ca2"], "d": ["অটোমানরা মোরিয়া ভেনিসের কাছ থেকে ফিরিয়ে নেওয়ার পর অস্ট্রিয়া কার্লোভিৎস চুক্তি লঙ্ঘিত হয়েছে দাবি করে ভেনিসের সঙ্গে মৈত্রী চুক্তি স্বাক্ষর করল; প্রিন্স ইউজিন সদরে আজমকে লেখা চিঠিতে ভেনিসের কাছ থেকে নেওয়া স্থানগুলো ফেরত চাইলেন। দাউদপাশা শিবিরের পরামর্শে সদরে আজম আলি পাশার চাপে অস্ট্রিয়ার বিরুদ্ধে যুদ্ধ ঘোষণা হলো এবং এর জন্য শেখুল ইসলামের কাছ থেকে ফতোয়া নেওয়া হলো।", "4a2089d7"]},
"OLAYLAR_EK5:1716-04-24:0":{"b": ["সদরে আজম আলি পাশা অস্ট্রিয়া অভিযানে বের হলেন", "2fbdce42"], "d": ["অস্ট্রিয়ার বিরুদ্ধে যুদ্ধ ঘোষণার পর সেরদার-ই একরেম আলি পাশা 100.000-এর বেশি সেনাবাহিনী নিয়ে অস্ট্রিয়া অভিযানে বের হলেন; নৌবহর একই গ্রীষ্মে কর্ফুর দিকে গেল। সেনাবাহিনী বেলগ্রেড থেকে ভারাদিনের দিকে এগোবে এবং আগস্টের শুরুর পরাজয়ে সদরে আজম শহিদ হবেন।", "02a5590b"]},
"OLAYLAR_EK5:1716-08-05:0":{"b": ["ভারাদিন (পেত্রোভারাদিন) পরাজয় — দামাদ আলি পাশার শাহাদাত", "265c1d81"], "d": ["বেলগ্রেড হয়ে দানিয়ুব পার হওয়া অটোমান সেনাবাহিনী প্রিন্স ইউজিনের নেতৃত্বাধীন অস্ট্রিয়ান বাহিনীর সঙ্গে ভারাদিনের সামনে মুখোমুখি হলো; প্রথম আঘাতে জ্যানিসারি আক্রমণ শত্রুর পরিখা ভেদ করলেও অশ্বারোহী পার্শ্ব ভেঙে পড়ায় সারি ছত্রভঙ্গ হলো। সদরে আজম সিলাহদার দামাদ আলি পাশা কপালে গুলি লেগে শহিদ হলেন, শিবির ও কামান বহর সম্পূর্ণ শত্রুর হাতে গেল। অটোমান ঘটনাপঞ্জিতে 'ভারাদিন বছর' নামে স্মরণ করা এই পরাজয় তেমেশভার এবং পরের বছর বেলগ্রেড হারানোর শৃঙ্খলের প্রথম কড়া ছিল।", "ad21a2c3"]},
"OLAYLAR_EK5:1716-08-20:0":{"b": ["কর্ফু অবরোধের ব্যর্থতায় পরিণতি", "b2aa7011"], "d": ["মোরিয়ার সেরাস্কার কারা মুস্তাফা পাশা স্থলপথে, কাপুদান-ই দরিয়া জানিম হোজা মেহমেদ পাশা নৌবহর নিয়ে সমুদ্রপথে কর্ফুর ওপর ঝাঁপিয়ে পড়লেন; দ্বীপটি আদ্রিয়াটিকে ভেনিসের মূল ঘাঁটি ছিল। কিন্তু দুর্গের অত্যন্ত শক্তিশালী সুরক্ষা, ভেনিসীয় নৌবহরের আনা সাহায্য এবং দানিয়ুব ফ্রন্ট থেকে আসা পরাজয়ের খবর অবরোধ তুলে নেওয়ার কারণ হলো। কর্ফু দখল না হওয়া মোরিয়ার পুনর্বিজয়ে উঠে আসা উদ্দীপনা নিভিয়ে দিল এবং যুদ্ধের কেন্দ্রভার হাঙ্গেরির দিকে সরিয়ে দিল।", "4589579c"]},
"OLAYLAR_EK5:1716-10-13:0":{"b": ["তেমেশভারের (তিমিশোয়ারা) অস্ট্রিয়ার কাছে হারানো", "27fe1365"], "d": ["ভারাদিন পরাজয়ের পর প্রিন্স ইউজিন সরাসরি তেমেশভারের দিকে অগ্রসর হলেন এবং দুর্গ চল্লিশ দিনের বেশি অবরোধের শেষে সমঝোতায় আত্মসমর্পণ করল। 1552 সালে কানুনির আমলে বিজিত এবং 164 বছর ধরে বেইলারবেইত্বের কেন্দ্র হিসেবে হাঙ্গেরি প্রতিরক্ষার পূর্ব স্তম্ভ গণ্য শহর এভাবে হাতছাড়া হলো। তেমেশভারের পতনে বানাত অঞ্চল পুরোটাই অস্ট্রিয়ার হাতে গেল এবং অটোমান সীমান্ত দানিয়ুবের দক্ষিণে ঠেলে দেওয়া হলো। একই তারিখে অ্যাটলাসে অটোমানদের কাছ থেকে হাবসবুর্গের হাতে যাওয়া অন্যান্য বসতি: Csákóvár, Facset ও Karánşebeş (Caransebeş) — তেমেশভার প্রদেশের হাতবদলের সঙ্গে (TDV timisvar; স্থানের স্তরে দিন সূত্রে নেই, আবি-মার্কেজ শৃঙ্খল, ঘোষিত আনুমানিকতা)।", "a1408ad1"]},
"OLAYLAR_EK5:1716-11-16:0":{"b": ["হারাম (ইয়েনি পালাঙ্কা) দুর্গের অস্ট্রিয়ার কাছে সমর্পণ — বানাতের দানিয়ুব তীর হাতছাড়া", "38ee4c6d"], "d": ["তেমেশভারের পতনের পর বানাতের অবশিষ্টাংশ নেওয়ার দায়িত্বপ্রাপ্ত অস্ট্রিয়ান অশ্বারোহী জেনারেল মার্সি 14 নভেম্বর দানিয়ুব তীরের হারামের (ইয়েনি পালাঙ্কা) দিকে অগ্রসর হলেন; 16 নভেম্বর দুর্গে পৌঁছালে 200 জনের অটোমান গ্যারিসন সাদা পতাকা তুলে স্বাধীনভাবে সরে যাওয়ার শর্তে আত্মসমর্পণ করল। এভাবে 1552 সাল থেকে অটোমান হাতে থাকা দক্ষিণ বানাতের দানিয়ুব রেখাও অস্ট্রিয়ার হাতে গেল। একই তারিখে অ্যাটলাসে অটোমানদের কাছ থেকে হাবসবুর্গের হাতে যাওয়া অন্য বসতি: Versec — হারামের আবি-মার্কেজ শৃঙ্খল অনুসরণ করে (Bánlaky 0019/1703; ঘোষিত আনুমানিকতা)।", "5b54ecb0"]},
"OLAYLAR_EK5:1718-07-21:0":{"b": ["পাসারোভিৎস চুক্তি — মোরিয়া অর্জিত, বেলগ্রেড ও বানাত হারানো", "d46aa216"], "d": ["ভেনিসের কাছ থেকে মোরিয়া পুনরুদ্ধার করা হয়েছিল, কিন্তু যুদ্ধে নামা অস্ট্রিয়া পেত্রোভারাদিন ও বেলগ্রেডে জয়ের ফলে আলোচনায় এগিয়ে যায়। ইংল্যান্ড ও হল্যান্ডের মধ্যস্থতায় স্বাক্ষরিত চুক্তিতে মোরিয়া অটোমানদের হাতে থাকে, বিনিময়ে বেলগ্রেডসহ উত্তর সার্বিয়া, বানাত ও ছোট ওয়ালাচিয়া অস্ট্রিয়াকে ছেড়ে দেওয়া হয়; টিডিভি-র ভাষায় 'উত্তর বসনিয়া সম্পূর্ণ অস্ট্রিয়াকে ছেড়ে দেওয়া হয়েছে' — সাভা নদীর তীরের বোসনা দুবিৎসা ও বোসনা ব্রদের মতো দুর্গ মানচিত্রে এই দিন থেকে অস্ট্রিয়ার অধীনে যায় (সুনির্দিষ্ট সীমানা কমিশনাররা এক এক করে টেনেছিলেন, টিডিভি এই দুর্গগুলোর নাম উল্লেখ করে না); ভেনিস আইওনীয় উপকূলের প্রেভেজা ও চুহার মতো ঘাঁটি ধরে রাখে। একই দিনে স্বাক্ষরিত বাণিজ্য আহদনামায় অস্ট্রীয় পণ্যের শুল্ক শতকরা পাঁচ থেকে তিনে নামানো হয়। চুক্তিটি মধ্য ইউরোপে অটোমান রাষ্ট্রের পশ্চাদপসরণ নথিভুক্ত করার পাশাপাশি যে সাতাশ বছরের শান্তি খুলে দেয়, তা লালে যুগের (1718-1730) ভিত্তি গড়ে: নেভশেহিরলি দামাদ ইব্রাহিম পাশার শাসনে প্রথম অটোমান ছাপাখানা (1727, ইব্রাহিম মুতেফেররিকা), অনুবাদ পরিষদ, গুটিবসন্তের টিকা-পর্যবেক্ষণ ও নতুন প্রাসাদ-সংস্কৃতি এই শান্তির বছরগুলোর ফসল। একই দিনে অ্যাটলাসে হাত বদল হওয়া অন্যান্য বসতি: ক্রাইওভা (Craiova), রিমনিক (Râmnicu Vâlcea) ও তুর্নু সেভেরিন (ছোট ওয়ালাচিয়া/অলটেনিয়া, অটোমান থেকে অস্ট্রিয়ায়) এবং আয়ামাভরা (লেফকাদা) (অটোমান থেকে ভেনিসে; টিডিভি ayamavra: 1718 সালে পাসারোভিৎস চুক্তিতে দ্বীপটি ভেনিসকে ছেড়ে দেওয়া হয়)। ছোট ওয়ালাচিয়ায় আরও তার্গু জিউ অস্ট্রিয়ায়; ভোনিৎসা (Voniçe, টিডিভি pasarofca-antlasmasi) ও চুহা দ্বীপ (কিথিরা, টিডিভি cuka-adasi: পাসারোভিৎসের ৩য় অনুচ্ছেদ) ভেনিসে যায়।", "ec4430bf"]},
"OLAYLAR_EK5:1723-06-15:0":{"b": ["পূর্ব অভিযান: তিফলিস দখল এবং ইরান যুদ্ধের সূচনা", "78343dc2"], "d": ["সাফাভি রাষ্ট্র আফগান আক্রমণে ভেঙে পড়া এবং রাশিয়ার কাস্পিয়ান উপকূলে নামায় অটোমান রাষ্ট্র শূন্যতা সম্পূর্ণ রুশ প্রভাবে না যাওয়ার জন্য পূর্বে সেনাবাহিনী পাঠাল। তিফলিস দখল করে জর্জিয়া অটোমান শাসনের সঙ্গে যুক্ত করা হলো; এর পর গাঞ্জা, ইরেভান ও নাখচিভানের দিকে অগ্রগতি চলল। লালে যুগের শান্তিপূর্ণ চেহারার আড়ালে চালানো এই অভিযান তেরো বছর স্থায়ী হবে এবং শেষে অর্জিত সব স্থান ফিরিয়ে দেওয়ায় সমাপ্ত দীর্ঘ পূর্ব অভিযানের সূচনা হলো।", "5c412d91"]},
"OLAYLAR_EK5:1723-08-01:0":{"b": ["1723 সালের ইরান অভিযান: শিরভান ও জর্জিয়ায় প্রবেশ", "c81189fc"], "d": ["সাফাভি রাষ্ট্র আফগান আক্রমণে ভেঙে পড়ায়, রাশিয়াকে কাস্পিয়ান উপকূলে নামতে বাধা দেওয়ার যুক্তিতে পূর্বে অভিযান শুরু হয়। এরজুরুম বাহিনী জর্জিয়া হয়ে তিফলিসে এবং শিরভান শাখা শামাখিতে প্রবেশ করে একশ ত্রিশ বছর আগে হারানো ভূমি ফিরে পায়। এটি ছিল ককেশাসে অটোমানদের শেষ বড় অগ্রযাত্রা।", "9f84acd9"]},
"OLAYLAR_EK5:1723-10-01:0":{"b": ["কেরমানশাহ দখল — জাগরোসের দ্বার", "ad14799f"], "d": ["বাগদাদ বাহিনী জাগরোস গিরিপথ পেরিয়ে ইরানের পশ্চিম দ্বার বলে গণ্য কেরমানশাহ দখল করে। শহরটি বাগদাদ থেকে ইসফাহানগামী কাফেলা ও সেনাপথের ওপর ছিল এবং এর দখল ইরাক প্রদেশের পূর্ব নিরাপত্তা নিশ্চিত করে। এই অগ্রযাত্রা বিভক্ত সাফাভি দেশে অটোমান ও রাশিয়ার মধ্যে ভাগাভাগির প্রতিযোগিতা শুরু করে।", "65dba49c"]},
"OLAYLAR_EK5:1724-06-24:0":{"b": ["ইস্তানবুল মুকাসেমানামে — ইরানকে রাশিয়ার সঙ্গে ভাগাভাগি", "fce8eec2"], "d": ["ভেঙে পড়া সাফাভি দেশের ওপর অটোমান ও রাশিয়ার মুখোমুখি হওয়া ঠেকাতে ফরাসি দূতের মধ্যস্থতায় একটি বিভাজন চুক্তি স্বাক্ষরিত হলো। কাস্পিয়ান সাগরের পশ্চিম ও দক্ষিণ উপকূল রাশিয়াকে, জর্জিয়া, শিরভান, আজারবাইজান ও পশ্চিম ইরানের শহরগুলো অটোমান রাষ্ট্রকে ছেড়ে দেওয়া হলো। কাগজে বড় লাভ মনে হওয়া এই ভাগাভাগি অল্পকাল পরে নাদির শাহের উত্থানে কার্যত অকার্যকর হবে। চুক্তি অনুযায়ী শাবরান ও মুশকুরের মতো শিরভানের উর্বর ভূমি রাশিয়ার দিকে রাখা হলো (Çaycıoğlu, DergiPark)।", "7b0b411b"]},
"OLAYLAR_EK5:1724-08-11:0":{"b": ["নাখচিভান দখল", "bdf14d0a"], "d": ["আরাস নদী ধরে অগ্রসর অটোমান বাহিনী নাখচিভান ও ওরদুবাদ দখল করে; জুলফাও নাখচিভান লিভায় যুক্ত হয়। ইরানের উত্তর-পশ্চিম দ্বার এই শহর নবগঠিত ইরেভান প্রদেশের অধীনে আসে। এভাবে অটোমান সীমানা কানুনি আমলের পূর্বতম রেখায় আবার পৌঁছায়।", "9e602879"]},
"OLAYLAR_EK5:1724-08-31:0":{"b": ["হামাদান বিজয়", "e1339a97"], "d": ["কেরমানশাহ থেকে পূর্বে অগ্রসর বাহিনী দীর্ঘ অবরোধের পর ইরান মালভূমির পশ্চিম প্রান্তের হামাদান দখল করে। শহরটি ছিল ইরাকাইন অভিযানের পর অটোমান বাহিনীর পৌঁছানো সবচেয়ে পূর্বের বিন্দু ইসফাহানের পথের শেষ বড় বিরতিস্থল। একই বছর রাশিয়ার সঙ্গে স্বাক্ষরিত ইস্তানবুল চুক্তি ভেঙে পড়া ইরানের অটোমান ও রাশিয়ার মধ্যে ভাগাভাগিকে কাগজে লিপিবদ্ধ করে।", "81552031"]},
"OLAYLAR_EK5:1724-10-03:0":{"b": ["ইরেভান পুনর্বিজয়", "88acabef"], "d": ["নব্বই দিনের কঠিন অবরোধের পর আরাস উপত্যকার মূল দুর্গ ইরেভান আবার অটোমান শাসনে আসে। 1583 সালে নির্মিত ও 1604 সালে হারানো দুর্গটি এবার আরও শক্তিশালী গ্যারিসন দিয়ে সুরক্ষিত করা হয়। অবরোধের দীর্ঘতা ছিল অটোমান বাহিনী আর সহজে এগোতে পারছে না তারই লক্ষণ। কার্পি (উচকিলিসে), শেরুর, মাকু ও শুরেগেল নাহিয়াগুলোও ইরেভান প্রদেশের সঙ্গে যুক্ত হয়।", "a989b1eb"]},
"OLAYLAR_EK5:1725-07-28:0":{"b": ["তাবরিজ দখল — আজারবাইজান হস্তগত", "e502a4f7"], "d": ["এক বছর আগের ব্যর্থ চেষ্টার পর পুনরায় অবরুদ্ধ তাবরিজ রাস্তায় রাস্তায় চলা কঠিন যুদ্ধের পর অটোমান সেনাবাহিনীর কাছে আত্মসমর্পণ করল। তাবরিজ প্রদেশের অধীন মেরেন্দ, মারাগা ও সোভুকবুলাক (মাহাবাদ)-ও অটোমান শাসনে এল। একই বছর লোরি, গাঞ্জা, আর্দাবিল ও খুররামাবাদও নেওয়া হয়ে ইস্তানবুল মুকাসেমানামে অনুযায়ী অটোমান ভাগে পড়া অঞ্চলগুলো কার্যত দখল হলো। পূর্বে পৌঁছানো এই বিস্তৃতি ফারহাদ পাশা চুক্তির যুগের পর সবচেয়ে অগ্রবর্তী সীমানা ছিল; তবে তা ধরে রাখা সেনাবাহিনী ও কোষাগারের ওপর ভারী বোঝা চাপাল।", "e0953563"]},
"OLAYLAR_EK5:1725-09-04:0":{"b": ["গাঞ্জা বিজয় — ককেশাস অভিযানের সমাপ্তি", "875bca7a"], "d": ["ককেশাস অভিযানের শেষ লক্ষ্য গাঞ্জা কুর ও আরাসের মধ্যবর্তী কারাবাখের কেন্দ্র হিসেবে সমর্পিত হয়। শিরভান, ইরেভান, নাখচিভান ও গাঞ্জা রেখা সম্পূর্ণ হওয়ায় অটোমান রাষ্ট্র ককেশাসে 1590 সালের বিস্তৃতিতে পৌঁছায়। কিন্তু এই লাভ স্বল্পস্থায়ী হয়: নাদির শাহের উত্থান দশ বছরের মধ্যে পুরো অঞ্চল ফিরিয়ে নেবে।", "265db7e0"]},
"OLAYLAR_EK5:1727-10-04:0":{"b": ["হামাদান চুক্তি — পশ্চিম ইরানের অটোমানদের সঙ্গে যুক্ত হওয়া", "94a29dc3"], "d": ["আফগান শাসক আশরাফ শাহের সঙ্গে স্বাক্ষরিত চুক্তিতে চার বছর স্থায়ী যুদ্ধ শেষ হলো এবং অটোমান রাষ্ট্রের দখল করা পশ্চিম ইরানের ভূমি আইনত স্বীকৃত হলো। আশরাফ শাহ বিনিময়ে অটোমান সুলতানের খলিফাত্ব মেনে নিলেন এবং ইরানে খুতবা সুলতানের নামে পাঠের দায়িত্ব নিলেন। এই কূটনৈতিক বিজয় স্বল্পস্থায়ী হলো; নাদির শাহের 1730 সালে শুরু করা পাল্টা আক্রমণ কয়েক বছরের মধ্যে চুক্তির অর্জন মুছে দেবে।", "fd0174b9"]},
"OLAYLAR_EK5:1731-01-01:0":{"b": ["হেকিমোগলু আলি পাশা রুমিয়ে দখল করলেন", "eac7f64d"], "d": ["ইরান অভিযানে হেকিমোগলু আলি পাশা প্রথমে উর্মিয়া (রুমিয়ে) এবং তারপর অটোমানদের জন্য খালি করা তাবরিজ 15 নভেম্বর 1731 দখল করেন। টিডিভি উর্মিয়া দখলের দিন দেয় না; কেবল বছর এবং তাবরিজের আগে ঘটার কথা জানা যায়।", "f99d74f9"]},
"OLAYLAR_EK5:1732-01-08:0":{"b": ["আহমেদ পাশা চুক্তি — পশ্চিম ইরানের বড় অংশ ফেরত", "590d839f"], "d": ["নাদির শাহের মেলায়িরে অর্জিত বিজয় এবং পরপর আসা ইরানি আক্রমণে বাগদাদের গভর্নর আহমেদ পাশা কেন্দ্রকে না জানিয়ে একটি শান্তি-পাঠ স্বাক্ষর করলেন। চুক্তি অনুযায়ী আরাস নদীকে সীমান্ত মানা হলো; হামাদান, কেরমানশাহ, আর্দালান, আর্দাবিল ও তাবরিজের মতো পশ্চিম ইরানের শহরগুলো ইরানকে ফিরিয়ে দেওয়া হলো, গাঞ্জা ও তিফলিস অটোমানদের হাতে রইল। ইস্তানবুলে প্রতিক্রিয়ায় গৃহীত এই পাঠ নাদির শাহও অপর্যাপ্ত পেলেন এবং 1732 সাল শেষ হওয়ার আগেই যুদ্ধ আবার জ্বলে উঠল। অ্যাটলাস হোয়ের শৃঙ্খল অনুসরণকারী কোতুরকেও এই দিনে অটোমানদের কাছ থেকে সাফাভিদের হাতে গেছে ধরে (TDV hoy; কোতুরের নির্দিষ্ট দিন সূত্রে নেই — ঘোষিত আনুমানিকতা)।", "fdaa1e6f"]},
"OLAYLAR_EK5:1732-07-01:0":{"b": ["ওরানের পুনরায় স্পেনের কাছে হারানো", "20485027"], "d": ["স্পেনের রাজা পঞ্চম ফেলিপের পাঠানো বড় অবতরণ নৌবহর কাউন্ট মন্তেমারের নেতৃত্বে ওরানের সামনে এল এবং আলজিয়ার্স ওজাক বাহিনীকে পরাজিত করে শহর ফিরিয়ে নিল। চব্বিশ বছর আগে বিজিত বন্দর ষাট বছর আবার স্পেনীয় গ্যারিসনের হাতে থাকবে। পশ্চিম ভূমধ্যসাগরে পশ্চিমের ওজাকগুলোর শক্তির সীমা দেখানো এই ক্ষতি কেবল 1792 সালে ওরানের চূড়ান্ত বিজয়ে পূরণ হলো।", "b255a8da"]},
"OLAYLAR_EK5:1733-05-01:0":{"b": ["হুমবারাজি ওজাকের ইউরোপীয় ধাঁচে সংস্কার এবং হুমবারাহানে প্রতিষ্ঠা", "d980cf2a"], "d": ["অটোমান সেবায় আসা ফরাসি বংশোদ্ভূত হুমবারাজি আহমেদ পাশা সদরে আজম হেকিমওগলু আলি পাশার সমর্থনে হুমবারাজি ওজাককে বেতনভুক্ত ও ইউরোপীয় ধরনে সংগঠিত বাহিনীতে পরিণত করলেন। বসনিয়া থেকে সংগৃহীত তিন শত সৈন্যকে গণিত ও জ্যামিতিভিত্তিক নিয়মিত প্রশিক্ষণ দেওয়া হলো; সংগঠন, সরঞ্জাম ও অবসরের জন্য নতুন নিয়মাবলি প্রস্তুত হলো, আধুনিক প্রযুক্তিতে একশো গ্রেনেড কামান ও পঞ্চাশ হাজার গ্রেনেড তৈরি হলো। জ্যামিতি পড়ানো হুমবারাহানে অটোমানদের আধুনিক সামরিক প্রকৌশল শিক্ষার প্রথম বীজ গণ্য হয়।", "181b7161"]},
"OLAYLAR_EK5:1736-06-24:0":{"b": ["তৃতীয় আহমেদের মৃত্যু", "455f7fba"], "d": ["পাত্রোনা হালিল বিদ্রোহে 1730 সালে সিংহাসনচ্যুত তৃতীয় আহমেদ জীবনের শেষ ছয় বছর তোপকাপি প্রাসাদের সিংহাসনচ্যুত সুলতানদের জন্য নির্ধারিত মহলে কাটান এবং তেষট্টি বছর বয়সে মারা যান। বাহচেকাপিতে ইয়েনিজামির পাশে দাদি তুরহান সুলতানের সমাধিতে সমাহিত হন।", "00cc8767"]},
"OLAYLAR_EK5:1736-09-01:0":{"b": ["ইস্তানবুল চুক্তি — দক্ষিণ ককেশাস ইরানকে ছেড়ে দেওয়া", "8c205aab"], "d": ["চার বছর স্থায়ী দ্বিতীয় ইরান যুদ্ধ আরপাচায় পরাজয় এবং গাঞ্জা ও তিফলিস হারানোর পর স্বাক্ষরিত চুক্তিতে শেষ হলো। অটোমান রাষ্ট্র 1723 সাল থেকে দখল করা সমগ্র দক্ষিণ ককেশাস ও পশ্চিম ইরানের ভূমি থেকে সরে গেল, সীমান্ত 1639 সালের কাসর-ই শিরিন রেখায় ফিরল। তেরো বছরের পূর্ব অভিযান থেকে ভারী আর্থিক বোঝা ও খালি কোষাগার রইল; অন্যদিকে রাশিয়ার সঙ্গে শুরু হওয়া নতুন যুদ্ধের জন্য পূর্ব ফ্রন্ট বন্ধ হওয়া ছিল অত্যাবশ্যক লাভ।", "bcb0cbe8"]},
"OLAYLAR_EK5:1737-07-11:0":{"b": ["ওজি (ওচাকভ) দুর্গের রুশদের হাতে পতন", "f93e61f3"], "d": ["মার্শাল মুন্নিকের নেতৃত্বাধীন রুশ সেনাবাহিনী নিপার মোহনার ওজি দুর্গ অবরোধ করল; অস্ত্রাগার বিস্ফোরিত হওয়ায় প্রতিরক্ষা ভেঙে পড়ল এবং দুর্গ ব্যাপক প্রাণহানিসহ পড়ল। কৃষ্ণ সাগরের উত্তর-পশ্চিম উপকূলের তালা গণ্য ওজি হাতছাড়া হওয়া ক্রিমিয়ার পথ রুশদের জন্য খুলে দিল এবং ইস্তানবুলে বড় আতঙ্ক সৃষ্টি করল। দুর্গ পরের বছর মহামারি ও রসদ-সংকটের কারণে রুশদের দ্বারা খালি করা হয়ে আবার অটোমানদের হাতে যাবে।", "479e0090"]},
"OLAYLAR_EK5:1737-08-04:0":{"b": ["বানা লুকা বিজয় — বসনিয়ার উদ্ধার", "f603865a"], "d": ["অস্ট্রিয়ান বাহিনী বসনিয়ায় প্রবেশ করে বানা লুকা অবরোধ করলে বসনিয়ার গভর্নর হেকিমওগলু আলি পাশা স্থানীয়দের কাছ থেকে সংগৃহীত বাহিনী নিয়ে সাহায্যে ছুটে এসে সংখ্যায় শ্রেষ্ঠ শত্রুকে ভারী পরাজয়ে ফেললেন। এই বিজয় অস্ট্রিয়ার বসনিয়া দখল পরিকল্পনাকে প্রথম আঘাতেই ভেঙে দিল এবং প্রদেশের উত্তর সম্পূর্ণ ফিরিয়ে নেওয়া হলো। বানা লুকা 1683-এর পর অস্ট্রিয়ার বিরুদ্ধে ক্রমাগত পিছু হটা অটোমান সেনাবাহিনীর মনোবল ফিরিয়ে আনা মোড়গুলোর একটি হলো।", "81c1850e"]},
"OLAYLAR_EK5:1739-07-22:0":{"b": ["হিসারচিক (গ্রোৎস্কা) বিজয় — বেলগ্রেডের পথ খোলা", "2101cdff"], "d": ["বেলগ্রেড রক্ষায় এগিয়ে আসা অস্ট্রিয়ান সেনাবাহিনী দানিয়ুব তীরের সংকীর্ণ গিরিপথে ফাঁদে পড়ে সারা দিনের যুদ্ধে ভারী ক্ষতি সইল। মার্শাল ভালিসের বাহিনী বিশৃঙ্খলভাবে বেলগ্রেডে সরে যাওয়ার সময় অটোমান সেনাবাহিনী দুর্গের সামনে গিয়ে অবরোধ শুরু করল। হিসারচিক কার্লোভিৎসের পর অস্ট্রিয়ার বিরুদ্ধে অর্জিত সবচেয়ে নিশ্চিত খোলা যুদ্ধের বিজয় এবং সরাসরি বেলগ্রেড পুনরুদ্ধার নিশ্চিত করল।", "5811893a"]},
"OLAYLAR_EK5:1739-10-03:0":{"b": ["নিশ চুক্তি — রাশিয়ার সঙ্গে শান্তি, আজাকের নিরপেক্ষকরণ এবং ক্রিমীয় আক্রমণ বন্ধ", "674f974e"], "d": ["অস্ট্রিয়া বেলগ্রেডে শান্তিতে সম্মত হওয়ায় একা পড়া রাশিয়া ফরাসি দূত ভিলনেভের মধ্যস্থতায় যুদ্ধ শেষ করতে বাধ্য হলো। আজাক দুর্গের প্রাচীর ধ্বংস করে অঞ্চল দুই রাষ্ট্রের মধ্যে নিরপেক্ষ ভূমি ঘোষিত হলো; রাশিয়া কৃষ্ণ সাগরে যুদ্ধ ও বাণিজ্য জাহাজ না রাখার শর্ত মেনে নিল। এভাবে রাশিয়ার সাগরে নামার লক্ষ্য আরও এক প্রজন্ম পিছিয়ে গেল এবং অটোমান রাষ্ট্র অষ্টাদশ শতাব্দীতে শেষবারের মতো টেবিল থেকে লাভবান হয়ে উঠল।", "7ca0d614"]},
"OLAYLAR_EK5:1739-12-12:0":{"b": ["ওজি রুশ দখল থেকে ফিরল: 1739 শান্তিতে দুর্গ ধ্বংসের পর সমর্পণ", "7ecc2bef"], "d": ["রুশরা ওজি 11 জুলাই 1737-এ নিয়েছিল। 1739 সালে রাশিয়ার সঙ্গে হওয়া শান্তির কারণে দুর্গের প্রাচীর ধ্বংসের পর আবার অটোমানদের হাতে সমর্পণ করা হলো; অটোমানরা ওজি ইয়াশ চুক্তির আগে 1788 পর্যন্ত ধরে রাখল।", "39ee6708"]},
"OLAYLAR_EK5:1743-10-23:0":{"b": ["মোসুল প্রতিরক্ষা — নাদির শাহের প্রতিহত হওয়া", "c03ffbc1"], "d": ["কিরকুক ও এরবিল দখল করে মোসুলের সামনে আসা নাদির শাহ চল্লিশ দিন ধরে শহরে গোলাবর্ষণ করলেন এবং পরপর সাধারণ আক্রমণ চালালেন। গভর্নর হুসেইন পাশা আল-জালিলি শহরের জনগণকেও অস্ত্রসজ্জিত করে চালানো প্রতিরক্ষা ইরানি বাহিনীকে ভারী ক্ষতিসহ অবরোধ তুলতে বাধ্য করল। মোসুলের টিকে থাকা সমগ্র ইরাক হাতছাড়া হওয়া ঠেকাল এবং জালিলি পরিবারের শহরে প্রভাব এক শতাব্দী দৃঢ় করল।", "b9f67e29"]},
"OLAYLAR_EK5:1744-01-01:0":{"b": ["দিরিয়া মৈত্রী — নাজদে প্রথম সৌদি আমিরাতের প্রতিষ্ঠা", "188751bf"], "d": ["উয়েইনা থেকে বিতাড়িত আলিম মুহাম্মদ ইবনে আবদুল ওয়াহহাবকে দিরিয়ায় আশ্রয় দেওয়া আমির মুহাম্মদ ইবনে সৌদ তাঁর সঙ্গে রাজনৈতিক কর্তৃত্বকে ধর্মীয় আহ্বানের সেবায় নিয়োজিত করার মৈত্রী গড়লেন। এই চুক্তি সৌদ পরিবারের জন্য নতুন ইতিহাস শুরু করল এবং নাজদের বিক্ষিপ্ত মরূদ্যান আমিরাতগুলোকে একটি আন্দোলনের ঘিরে একত্র করল। অর্ধ শতাব্দীর মধ্যে কারবালা, মক্কা ও মদিনা পর্যন্ত বিস্তৃত হবে এই শক্তি অটোমান রাষ্ট্রকে হিজাজে নিজের কর্তৃত্ব রক্ষায় বাধ্য করবে।", "6843c874"]},
"OLAYLAR_EK5:1746-09-04:0":{"b": ["কেরদেন চুক্তি — অটোমান-ইরান যুদ্ধের সমাপ্তি", "1d3a919e"], "d": ["চার বছর স্থায়ী শেষ যুদ্ধের পর স্বাক্ষরিত চুক্তিতে 1639 সালের কাসর-ই শিরিন সীমান্ত হুবহু নবায়িত হলো; দুই পক্ষই ভূমিলাভ করতে পারল না। নাদির শাহের জাফরি মাজহাবকে পঞ্চম মাজহাব হিসেবে স্বীকৃতির পীড়াপীড়ির দাবি প্রতিদানহীন রইল, অন্যদিকে ইরানি হাজিদের স্বাধীনভাবে হজ এবং পারস্পরিক দূত বিনিময়ের সিদ্ধান্ত হলো। দুই শতাব্দীর বেশি অটোমান-ইরান যুদ্ধ এভাবে কার্যত শেষ হলো; এই সীমান্ত আজ পর্যন্ত বহুলাংশে সংরক্ষিত।", "2a089331"]},
"OLAYLAR_EK5:1754-12-13:0":{"b": ["প্রথম মাহমুদের মৃত্যু এবং তৃতীয় ওসমানের সিংহাসনারোহণ", "30203700"], "d": ["চব্বিশ বছরের রাজত্বে বেলগ্রেড চুক্তিতে হারানো ভূমি ফিরিয়ে নেওয়া এবং হুমবারাজি ওজাক সংস্কার সমর্থন করা প্রথম মাহমুদ জুমার সেলামলিক থেকে ফেরার পথে মারা গেলেন। তাঁর স্থানে আটান্ন বছর বয়স পর্যন্ত কাফেসে জীবনযাপন করা ভাই তৃতীয় ওসমান এলেন। সংক্ষিপ্ত ও উদ্বিগ্ন রাজত্ব শুরু হলো; তিন বছরে ছয় সদরে আজম বদলানো তৃতীয় ওসমানের আমলে রাষ্ট্রীয় কাজে স্পষ্ট স্থবিরতা বিরাজ করল।", "8bdf7c4e"]},
"OLAYLAR_EK5:1757-10-30:0":{"b": ["তৃতীয় ওসমানের মৃত্যু এবং তৃতীয় মুস্তাফার সিংহাসনারোহণ", "3ac10f85"], "d": ["তিন বছরের রাজত্বের পর তৃতীয় ওসমানের মৃত্যুতে সংস্কার ভাবনায় উন্মুক্ত এবং রাষ্ট্রীয় কাজে ঘনিষ্ঠ আগ্রহী তৃতীয় মুস্তাফা সিংহাসনে বসলেন। নতুন সুলতান সদরে আজম কোজা রাগিব পাশার অভিজ্ঞতার ওপর নির্ভর করে অর্থব্যবস্থা শুধরে এবং সেনাবাহিনী নবায়নের চেষ্টা করলেন; ব্যারন দ্য তোতের দ্রুতগামী কামান বাহিনী এই সময়ে গঠিত হলো। তবে 1768 সালে প্রবেশ করা রুশ যুদ্ধ সতেরো বছরের রাজত্বের সব অর্জন ম্লান করে দেবে।", "2d13aff2"]},
"OLAYLAR_EK5:1768-10-08:0":{"b": ["রাশিয়ার বিরুদ্ধে যুদ্ধ ঘোষণা — বাল্তা ঘটনা এবং 1768-1774 যুদ্ধের সূচনা", "9c6aabe0"], "d": ["পোল্যান্ডের বার কনফেডারেশনকে তাড়া করা রুশ ও কসাক বাহিনী অটোমান সীমান্তের বাল্তা শহরে হামলা করে পুড়িয়ে দেওয়ায় দিওয়ান যুদ্ধের সিদ্ধান্ত নিল, রুশ দূতকে ইয়েদিকুলে বন্দি করা হলো। গুরুতর সামরিক প্রস্তুতি ছাড়া এবং ছয় মাস আগে ঘোষণা করে যুদ্ধে প্রবেশ শুরু থেকেই খারাপ গেল। ছয় বছর স্থায়ী এই সংগ্রাম চেশমে হামলা, কার্তাল পরাজয় এবং ক্রিমিয়া দখলের মাধ্যমে অটোমান ইতিহাসের সবচেয়ে ভারী পরাজয় ধারাগুলোর একটিতে পরিণত হবে।", "18bfa4d5"]},
"OLAYLAR_EK5:1769-09-20:0":{"b": ["খোতিন দুর্গের রুশদের কাছে হারানো", "66d43ea4"], "d": ["প্রিন্স গোলিৎসিনের নেতৃত্বাধীন রুশ সেনাবাহিনীর দুটি প্রচেষ্টা প্রতিহত হওয়ার পর কামিয়ানেৎস ও খোতিনের মাঝে সদরে আজমের পরাজয়ে সেনাবাহিনী পিছু হটল এবং রক্ষীরা দুর্গ খালি করল। দানিয়ুবের উত্তরের সবচেয়ে শক্তিশালী অটোমান দুর্গ বিনা প্রতিরোধে হাতছাড়া হওয়া ওয়ালাচিয়া ও মলদোভার দরজা রুশদের জন্য খুলে দিল। দুই প্রিন্সিপালিটি একই বছর দখল হলো; খোতিন কেবল 1774 সালে কুচুক কায়নারজা চুক্তিতে ফেরত পাওয়া গেল।", "1d0b219f"]}
});
